import time
import datetime
import logging
import csv
import signal
import sys
import spidev
import RPi.GPIO as GPIO
import adafruit_dht

# Configure logging
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
DHT_PIN = 4
MOVING_AVERAGE_WINDOW = 5
LOG_INTERVAL = 60
CALIBRATION_TIME = 60

# Global state
running = True
spi = None
dht_device = None

# Data storage
adc_readings = {0: [], 1: []}
dht_readings = []

# Moving average buffers
adc_moving_avg = {0: [], 1: []}
dht_moving_avg = []

# Calibration flag
calibration_complete = False

def signal_handler(sig, frame):
    global running
    running = False

def initialize_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        logging.info("SPI initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing SPI: {e}")
        return False

def initialize_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logging.info("DHT22 initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing DHT22: {e}")
        return False

def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        logging.error(f"Invalid MCP3008 channel: {channel}")
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"Error reading MCP3008 channel {channel}: {e}")
        return None

def read_dht22():
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logging.error("DHT22 returned None values.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"DHT22 read error (retry): {e}")
        return None, None
    except Exception as e:
        logging.error(f"Error reading DHT22: {e}")
        return None, None

def validate_data(data):
    if data is None:
        return False
    if not (0 <= data <= 100):
        logging.error(f"Invalid humidity value: {data}")
        return False
    if not (-20 <= data <= 50):
        logging.error(f"Invalid temperature value: {data}")
        return False
    return True

def moving_average(data, window_size):
    if not data:
        return None
    if len(data) < window_size:
        return sum(data) / len(data) if data else None
    window = data[-window_size:]
    return sum(window) / window_size

def log_data(timestamp, adc0, adc1, temperature, humidity):
    try:
        with open('gas_data.csv', 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, adc0, adc1, temperature, humidity])
    except Exception as e:
        logging.error(f"Error writing to CSV file: {e}")

def cleanup():
    global spi, dht_device
    if spi:
        try:
            spi.close()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    GPIO.cleanup()
    logging.info("Resources cleaned up.")

def main():
    global running, calibration_complete

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_spi():
        sys.exit(1)
    if not initialize_dht22():
        sys.exit(1)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.IN)

    logging.info("Starting calibration...")
    start_time = time.time()
    while time.time() - start_time < CALIBRATION_TIME and running:
        adc0 = read_mcp3008(0)
        adc1 = read_mcp3008(1)
        if adc0 is not None:
            adc_readings[0].append(adc0)
        if adc1 is not None:
            adc_readings[1].append(adc1)
        time.sleep(0.1)

    calibration_complete = True
    logging.info("Calibration complete.")

    try:
        while running:
            timestamp = datetime.datetime.now().isoformat()

            adc0 = read_mcp3008(0)
            adc1 = read_mcp3008(1)

            temperature, humidity = read_dht22()

            if adc0 is not None:
                adc_readings[0].append(adc0)
                adc_moving_avg[0] = moving_average(adc_readings[0], MOVING_AVERAGE_WINDOW)
            if adc1 is not None:
                adc_readings[1].append(adc1)
                adc_moving_avg[1] = moving_average(adc_readings[1], MOVING_AVERAGE_WINDOW)
            if temperature is not None and humidity is not None:
                dht_readings.append(temperature)
                dht_moving_avg = moving_average(dht_readings, MOVING_AVERAGE_WINDOW)

            if validate_data(temperature) and validate_data(humidity):
                log_data(timestamp, adc_moving_avg[0], adc_moving_avg[1], dht_moving_avg, humidity)
            else:
                logging.error("Invalid sensor data. Skipping logging.")

            for _ in range(LOG_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

