import spidev
import time
import sys

# SPI configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
ADC_CHANNEL = 0
READING_COUNT = 5
DELAY_SECONDS = 2


def read_adc(spi, channel):
    """Read a single-ended channel from the MCP3008 and return a 10-bit int."""
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid ADC channel {channel}; must be 0-7.")
    tx = [0x01, (0x08 | channel) << 4, 0x00]
    rx = spi.xfer2(tx)
    if len(rx) != 3:
        raise IOError(f"Unexpected SPI response length: {len(rx)}")
    return ((rx[1] & 0x03) << 8) | rx[2]


def main():
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = 0
    except Exception as e:
        print(f"Error opening SPI bus {SPI_BUS}, device {SPI_DEVICE}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(READING_COUNT):
            try:
                raw = read_adc(spi, ADC_CHANNEL)
                moisture = round((raw / 1023.0) * 100, 2)
                print(f"Soil moisture level: {moisture}%")
            except (IOError, ValueError) as e:
                print(f"Error reading ADC channel {ADC_CHANNEL}: {e}", file=sys.stderr)
                break
            if i < READING_COUNT - 1:
                time.sleep(DELAY_SECONDS)
        if i == READING_COUNT:
            print("Soil moisture reading sequence completed.")
    except KeyboardInterrupt:
        print("Script interrupted by user.")
    finally:
        try:
            spi.close()
        except Exception:
            pass
        print("SPI connection closed.")


if __name__ == "__main__":
    main()

