import time
import logging
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class Oscilloscope:
    """
    Object-oriented oscilloscope driver for Raspberry Pi using an ADS1115
    ADC at I2C address 0x48 on I2C bus 1 (GPIO2/GPIO3).
    """

    def __init__(self, address=0x48, gain=1, channels=(0, 1)):
        self.address = address
        self.gain = gain
        self.channels = channels
        self.i2c = None
        self.ads = None
        self.channels_in = {}
        self.running = False
        self._original_handlers = {}

    def initialize(self):
        """Initialize I2C bus, ADS1115, and ADC channels."""
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            logging.info(f"I2C bus initialized on SCL={board.SCL}, SDA={board.SDA}")
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus: {e}")
            return False

        try:
            self.ads = ADS.ADS1115(self.i2c, address=self.address)
            self.ads.gain = self.gain
            logging.info(f"ADS1115 initialized at address 0x{self.address:02X}, gain={self.gain}")
        except Exception as e:
            logging.error(f"Failed to initialize ADS1115 at 0x{self.address:02X}: {e}")
            self.close()
            return False

        try:
            self.channels_in = {ch: AnalogIn(self.ads, getattr(ADS, f"P{ch}")) for ch in self.channels}
            logging.info(f"ADC channels {self.channels} configured in single-ended mode")
        except Exception as e:
            logging.error(f"Failed to configure ADC channels: {e}")
            self.close()
            return False

        self.running = True
        return True

    def read_channels(self):
        """Read all configured ADC channels and return a dict of values."""
        values = {}
        for ch in self.channels:
            try:
                values[ch] = self.channels_in[ch].voltage
            except Exception as e:
                logging.error(f"Error reading channel {ch}: {e}")
                values[ch] = None
        return values

    def run(self):
        """Continuously read and print ADC values to stdout at ~10 Hz."""
        if not self.running:
            logging.warning("Oscilloscope not initialized. Call initialize() first.")
            return

        print("timestamp,ch0_v,ch1_v")
        logging.info("Sampling started. Press Ctrl+C to stop.")

        try:
            while self.running:
                loop_start = time.monotonic()
                values = self.read_channels()
                timestamp = time.monotonic()
                print(f"{timestamp:.3f},{values[0]:.4f},{values[1]:.4f}")
                elapsed = time.monotonic() - loop_start
                sleep_time = max(0.0, 0.1 - elapsed)
                time.sleep(sleep_time)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Stopping sampling loop.")
        except Exception as e:
            logging.error(f"Unexpected error during sampling: {e}")
        finally:
            self.close()

    def close(self):
        """Release all resources: clear channels, release ADS1115, deinit I2C."""
        if not self.running:
            return

        self.running = False
        logging.info("Releasing resources...")

        for ch in list(self.channels_in.keys()):
            try:
                del self.channels_in[ch]
            except Exception as e:
                logging.error(f"Error clearing channel {ch}: {e}")

        if self.ads is not None:
            try:
                self.ads = None
            except Exception as e:
                logging.error(f"Error releasing ADS1115: {e}")

        if self.i2c is not None:
            try:
                self.i2c.deinit()
                logging.info("I2C bus deinitialized.")
            except Exception as e:
                logging.error(f"Error deinitializing I2C bus: {e}")
            finally:
                self.i2c = None

        logging.info("Resources released. Oscilloscope closed.")

    def _signal_handler(self, signum, frame):
        """Handle SIGTERM/SIGINT by setting the running flag to False."""
        logging.info(f"Signal {signum} received. Initiating shutdown.")
        self.running = False


def main():
    scope = Oscilloscope(address=0x48, gain=1, channels=(0, 1))

    scope._original_handlers = {
        signal.SIGINT: signal.getsignal(signal.SIGINT),
        signal.SIGTERM: signal.getsignal(signal.SIGTERM),
    }

    signal.signal(signal.SIGINT, scope._signal_handler)
    signal.signal(signal.SIGTERM, scope._signal_handler)

    try:
        if not scope.initialize():
            sys.exit(1)
        scope.run()
    except Exception as e:
        logging.error(f"Fatal error in main: {e}")
        scope.close()
        sys.exit(1)
    finally:
        for sig, handler in scope._original_handlers.items():
            signal.signal(sig, handler)


if __name__ == "__main__":
    main()

