import argparse
import logging
import queue
import signal
import spidev
import sys
import time

import RPi.GPIO as GPIO


class SoundSensor:
    """Reads sound levels from digital or analog sensors on a Raspberry Pi."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins=None, channels=None, spi_speed=1000000,
                 log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue
        self.running = True
        self.spi = None
        self.gpio_pins = gpio_pins
        self.channels = channels

        if self.sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError(f"gpio_pins required for digital sensor {sensor_id}")
            GPIO.setmode(GPIO.BCM)
            for pin in gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == 'analog':
            if not channels:
                raise ValueError(f"channels required for analog sensor {sensor_id}")
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error(f"Failed to open SPI for sensor {sensor_id}: {e}")
                raise

    def read_sensor(self):
        """Reads the sensor and returns the value or None on error."""
        if self.sensor_type == 'digital':
            if not self.gpio_pins:
                return None
            try:
                return GPIO.input(self.gpio_pins[0])
            except Exception as e:
                logging.error(f"GPIO read error on pin {self.gpio_pins[0]} for sensor {self.sensor_id}: {e}")
                return None
        elif self.sensor_type == 'analog':
            if not self.channels:
                return None
            try:
                adc_value = self._read_mcp3008(self.channels[0])
                if adc_value is None:
                    return None
                return adc_value
            except Exception as e:
                logging.error(f"SPI read error on channel {self.channels[0]} for sensor {self.sensor_id}: {e}")
                return None
        return None

    def _read_mcp3008(self, channel):
        """Reads a single-ended channel from the MCP3008."""
        if not 0 <= channel <= 7:
            raise ValueError(f"Channel must be 0-7, got {channel}")
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"SPI transfer error on channel {channel}: {e}")
            return None

    def run(self):
        """Continuously reads the sensor and logs events."""
        while self.running:
            try:
                value = self.read_sensor()
                if value is None:
                    time.sleep(1.0 / self.sample_rate)
                    continue

                if self.sensor_type == 'digital' and value >= self.threshold:
                    self._log_event(f"Digital sound detected on pin {self.gpio_pins[0]}")
                    time.sleep(0.1)
                elif self.sensor_type == 'analog' and value >= self.threshold:
                    self._log_event(f"Analog sound detected on channel {self.channels[0]} (value={value})")
                    time.sleep(0.1)

                time.sleep(1.0 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in sensor {self.sensor_id} thread: {e}")
                time.sleep(1.0 / self.sample_rate)

    def stop(self):
        """Stops the sensor thread and releases resources."""
        self.running = False
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
        if self.sensor_type == 'digital':
            try:
                GPIO.cleanup(self.gpio_pins)
            except Exception:
                pass

    def _log_event(self, event):
        """Logs an event to the queue."""
        if self.log_queue:
            try:
                self.log_queue.put((self.sensor_id, event))
            except Exception as e:
                logging.error(f"Failed to put event in queue for sensor {self.sensor_id}: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor")
    parser.add_argument("--sensor_type", required=True, choices=['digital', 'analog'], help="Sensor type")
    parser.add_argument("--threshold", type=int, required=True, help="Threshold value")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate in Hz")
    parser.add_argument("--log_file", default="sound_events.log", help="Log file path")
    parser.add_argument("--gpio_pins", nargs='+', type=int, help="GPIO pins for digital sensors")
    parser.add_argument("--channels", nargs='+', type=int, help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs='+', type=str, default=['sensor1'], help="Sensor IDs")
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []

    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold,
                                 args.sample_rate, args.gpio_pins, args.channels,
                                 args.spi_speed, log_queue)
            sensors.append(sensor)
            sensor_thread = threading.Thread(target=sensor.run, daemon=True)
            sensor_thread.start()
        except Exception as e:
            logging.error(f"Failed to initialize sensor {sensor_id}: {e}")

    def signal_handler(sig, frame):
        logging.info("Shutting down...")
        for sensor in sensors:
            sensor.stop()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                sensor_id, event = log_queue.get(timeout=1)
                logging.info(f"Sensor {sensor_id}: {event}")
            except queue.Empty:
                pass
    except KeyboardInterrupt:
        signal_handler(None, None)


if __name__ == "__main__":
    import threading
    main()

