import signal
import sys
import time
import logging
from datetime import datetime

import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
I2C_ADDRESS = 0x57
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(message)s',
)
logger = logging.getLogger(__name__)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _format_part_id(part_id):
    """Safely format the part_id field, which may be an _AdaValue in emulators."""
    try:
        return int(part_id)
    except (TypeError, ValueError):
        return str(part_id)


def _read_fifo_samples(sensor):
    """Read IR and RED samples from the FIFO; return (ir_sample, red_sample) or None."""
    try:
        fifo = sensor.get_fifo()
    except OSError as exc:
        logger.error('I2C bus error reading FIFO: %s', exc)
        return None
    except Exception as exc:
        logger.error('Unexpected error reading FIFO: %s', exc)
        return None

    if fifo is None or fifo.num_samples == 0:
        return None

    try:
        ir_sample = fifo.ir_sample
        red_sample = fifo.red_sample
    except Exception as exc:
        logger.error('Error accessing FIFO sample fields: %s', exc)
        return None

    return ir_sample, red_sample


def _compute_heart_rate(sensor):
    """Compute a simple peak-count heart rate over WINDOW_SECONDS."""
    deadline = time.monotonic() + WINDOW_SECONDS
    peaks = 0
    while _running and time.monotonic() < deadline:
        samples = _read_fifo_samples(sensor)
        if samples is None:
            time.sleep(0.1)
            continue
        ir_sample, red_sample = samples

        # Basic peak detection: look for large changes in RED (pulse) vs IR (baseline).
        if red_sample > 1000 and ir_sample > 1000:
            if red_sample > ir_sample * 1.5:
                peaks += 1

        time.sleep(0.1)

    if peaks == 0:
        return 0
    return int(peaks * 60.0 / WINDOW_SECONDS)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c, address=I2C_ADDRESS)
        logger.info('MAX30102 initialized at 0x%02X', I2C_ADDRESS)

        while _running:
            heart_rate = _compute_heart_rate(sensor)
            spo2 = _format_part_id(sensor.spo2)

            timestamp = datetime.now().isoformat(timespec='seconds')
            log_entry = (
                f'{timestamp} - Heart Rate: {heart_rate} BPM, '
                f'SpO2: {spo2}%'
            )
            logger.info(log_entry)

            try:
                with open(LOG_FILE, 'a') as fh:
                    fh.write(log_entry + '\n')
            except OSError as exc:
                logger.error('Failed to write log file: %s', exc)

            time.sleep(SAMPLE_INTERVAL)

    except OSError as exc:
        logger.error('I2C initialization or sensor-absent error: %s', exc)
    except Exception as exc:
        logger.error('Unexpected error: %s', exc)
    finally:
        if sensor is not None:
            try:
                sensor.reset()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        logger.info('Resources released. Exiting.')


if __name__ == '__main__':
    main()

