        except Exception as e:
            logger.error(f"Error releasing GPIO: {e}")

def load_config(config_file="config.json"):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in configuration file: {e}")
        sys.exit(1)

def capture_image(camera):
    """Captures an image from the camera and returns it as a PIL Image."""
    try:
        # Capture array and convert to PIL Image
        image_array = camera.capture_array()
        image = Image.fromarray(image_array)
        return image
    except Exception as e:
        logger.error(f"Error capturing image: {e}")
        return None

def send_image_to_cloud(image, cloud_url):
    """Sends an image to the cloud for inference."""
    try:
        stream = io.BytesIO()
        image.save(stream, format='JPEG')
        stream.seek(0)

        response = requests.post(
            cloud_url,
            files={'image': (image.filename or 'image.jpg', stream)},
            timeout=10
        )
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        logger.error(f"Error sending image to cloud: {e}")
        return None

def indicate_bird(led_pin):
    """Activates the LED for 1 second to indicate a bird."""
    try:
        led.on()
        time.sleep(1)
        led.off()
    except Exception as e:
        logger.error(f"Error controlling LED: {e}")

def main():
    """Main function to run the bird feeder."""
    global camera, door, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    cloud_url = config.get("cloud_url")

    try:
        camera = Picamera2()
        camera_config = camera.create_preview_configuration(
            main={"size": (224, 224), "format": "RGB888"}
        )
        camera.configure(camera_config)
        camera.start()
        logger.info("Camera initialized successfully.")
    except Exception as e:
        logger.error(f"Failed to initialize camera: {e}")
        sys.exit(1)

    # Initialize GPIO for door control if configured
    if "gpio_door_control" in config:
        try:
            door = OutputDevice(config["gpio_door_control"])
            logger.info(f"GPIO door control initialized on pin {config['gpio_door_control']}.")
        except Exception as e:
            logger.error(f"Failed to initialize GPIO door control: {e}")
            door = None
    else:
        logger.info("GPIO door control not configured.")

    try:
        while running:
            image = capture_image(camera)
            if image is None:
                time.sleep(0.1)
                continue

            result = send_image_to_cloud(image, cloud_url)
            if result is None:
                time.sleep(0.1)
                continue

            if result.get("prediction", "unknown") == "bird":
                indicate_bird(config.get("led_pin", 17))

                if door is not None:
                    try:
                        door.on()
                        time.sleep(2)
                        door.off()
                    except Exception as e:
                        logger.error(f"Error controlling door: {e}")
            else:
                logger.debug(f"No bird detected. Prediction: {result.get('prediction', 'unknown')}")

            time.sleep(0.1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

