import io
import time
import json
import signal
import threading
import queue
import logging
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from gpiozero import LED

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=self.config['camera_queue_size'])
        self.running = False
        self.led = None
        self.alert_timer = None
        self.alert_active = False
        self.alert_lock = threading.Lock()
        self.gpio_pin = self.config.get('gpio_pin')
        self.motion_threshold = self.config.get('motion_threshold', 0)
        self.alert_duration = self.config.get('alert_duration', 1)
        self.alert_cooldown = self.config.get('alert_cooldown', 5)
        self.last_alert_time = 0
        self.last_motion_time = 0
        self.motion_cooldown = self.config.get('motion_cooldown', 2)
        self.motion_active = False
        self.motion_lock = threading.Lock()

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_still_configuration(
                main={"size": (self.config['camera_resolution_width'], self.config['camera_resolution_height'])}
            ))
            self.camera.start()
            time.sleep(2)
            logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            return False

    def initialize_gpio(self):
        if self.gpio_pin is None:
            return True
        try:
            self.led = LED(self.gpio_pin)
            logger.info(f"GPIO pin {self.gpio_pin} initialized for LED.")
            return True
        except Exception as e:
            logger.error(f"Error initializing GPIO pin {self.gpio_pin}: {e}")
            return False

    def capture_frames(self):
        try:
            while self.running:
                frame = self.camera.capture_array()
                if frame is None:
                    logger.warning("Captured frame is None.")
                    time.sleep(0.1)
                    continue
                stream = io.BytesIO()
                from PIL import Image
                img = Image.fromarray(frame)
                img.save(stream, format='JPEG')
                stream.seek(0)
                self.frame_queue.put(stream, timeout=1)
                time.sleep(0.1)
        except Exception as e:
            logger.error(f"Error capturing frames: {e}")
        finally:
            if self.camera:
                self.camera.stop()
                self.camera.close()
            logger.info("Camera stopped and closed.")

    def trigger_alert(self):
        with self.alert_lock:
            if self.alert_active:
                return
            self.alert_active = True
            logger.info("Alert triggered.")
            if self.led:
                self.led.on()
            self.alert_timer = threading.Timer(self.alert_duration, self.deactivate_alert)
            self.alert_timer.daemon = True
            self.alert_timer.start()

    def deactivate_alert(self):
        with self.alert_lock:
            self.alert_active = False
            if self.led:
                self.led.off()
            logger.info("Alert deactivated.")

    def check_motion(self):
        try:
            while self.running:
                if self.frame_queue.empty():
                    time.sleep(0.1)
                    continue
                stream = self.frame_queue.get(timeout=1)
                try:
                    img = Image.open(stream)
                    stream.seek(0)
                    stream.truncate()
                    if self.motion_threshold > 0:
                        if time.time() - self.last_motion_time > self.motion_cooldown:
                            with self.motion_lock:
                                if self.motion_active:
                                    self.motion_active = False
                                    logger.info("Motion deactivated.")
                    else:
                        if not self.motion_active:
                            with self.motion_lock:
                                if not self.motion_active:
                                    self.motion_active = True
                                    self.last_motion_time = time.time()
                                    logger.info("Motion detected.")
                        if self.motion_active and (time.time() - self.last_motion_time > self.motion_cooldown):
                            with self.motion_lock:
                                self.motion_active = False
                                logger.info("Motion deactivated.")
                except Exception as e:
                    logger.error(f"Error processing frame: {e}")
                finally:
                    stream.close()
                time.sleep(0.1)
        except Exception as e:
            logger.error(f"Error checking motion: {e}")

    def run(self):
        if not self.initialize_camera():
            return
        if not self.initialize_gpio():
            logger.warning("GPIO initialization failed. Continuing without LED.")
        self.running = True
        capture_thread = threading.Thread(target=self.capture_frames, daemon=True)
        motion_thread = threading.Thread(target=self.check_motion, daemon=True)
        capture_thread.start()
        motion_thread.start()
        try:
            while self.running:
                time.sleep(0.1)
        except KeyboardInterrupt:
            logger.info("Keyboard interrupt received.")
        finally:
            self.stop()

    def stop(self):
        self.running = False
        if self.alert_timer:
            self.alert_timer.cancel()
        if self.led:
            self.led.close()
        GPIO.cleanup()
        logger.info("Program terminated.")

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error(f"Config file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logger.error(f"Invalid JSON format in config file: {config_file}")
        return None

def main():
    config_file = "config.json"
    config = load_config(config_file)
    if not config:
        return
    handler = CameraHandler(config)
    def signal_handler(sig, frame):
        logger.info("Signal received, stopping...")
        handler.stop()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    handler.run()

if __name__ == "__main__":
    main()

