import cv2
import time
import signal
import sys
import os
from gpiozero import LED, Button, AngularServo

# --- Configuration ---
CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
CAMERA_INDEX = 0
RESOLUTION = (320, 240)
FRAME_DELAY = 0.02
SERVO_INCREMENT = 20
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_MIN_DUTY = 2.0
SERVO_MAX_DUTY = 12.0

# --- Globals for cleanup ---
camera = None
running = True
led = None
button = None
servo = None


def cleanup():
    """Release all resources on exit."""
    global camera, led, button, servo
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    cv2.destroyAllWindows()
    for dev in (led, button, servo):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    led = button = servo = None


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def load_cascade(path):
    """Load the cascade classifier, raising an error if it fails."""
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Cascade file not found: {path}")
    cascade = cv2.CascadeClassifier(path)
    if cascade.empty():
        raise ValueError(f"Failed to load cascade classifier from {path}")
    return cascade


def detect_faces(frame, cascade):
    """Detect faces in a grayscale frame; return (gray, faces)."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
    return gray, faces


def draw_rectangles(frame, faces):
    """Draw rectangles around detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)


def control_servo(angle):
    """Drive the servo to the given angle (0-180)."""
    if servo is None:
        return
    try:
        servo.angle = angle
    except Exception as e:
        print(f"Servo control error: {e}", file=sys.stderr)


def main():
    global camera, led, button, servo, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # --- Load cascade ---
    try:
        cascade = load_cascade(CASCADE_PATH)
    except Exception as e:
        print(f"Error loading cascade: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # --- Initialize GPIO (gpiozero) ---
    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = AngularServo(
            SERVO_PIN,
            initial_angle=0,
            min_angle=0,
            max_angle=180,
            min_pulse_width=SERVO_MIN_DUTY / 100.0,
            max_pulse_width=SERVO_MAX_DUTY / 100.0,
        )
    except Exception as e:
        print(f"Warning: GPIO initialization failed: {e}", file=sys.stderr)
        print("Continuing without GPIO control.", file=sys.stderr)
        led = None
        button = None
        servo = None

    # --- Open camera ---
    try:
        camera = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)
        if not camera.isOpened():
            raise IOError("Cannot open /dev/video0")
    except Exception as e:
        print(f"Error opening camera: {e}", file=sys.stderr)
        cleanup()
        sys.exit(0)

    current_angle = 0
    has_gui = True

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Error reading frame from camera", file=sys.stderr)
                break

            frame = cv2.resize(frame, RESOLUTION)
            gray, faces = detect_faces(frame, cascade)

            if led is not None:
                try:
                    led.on() if faces else led.off()
                except Exception as e:
                    print(f"LED control error: {e}", file=sys.stderr)

            if faces:
                cx = sum(f[0] + f[2] // 2 for f in faces) / len(faces)
                if cx > RESOLUTION[0] // 2:
                    current_angle = min(180, current_angle + SERVO_INCREMENT)
                else:
                    current_angle = max(0, current_angle - SERVO_INCREMENT)
                control_servo(current_angle)

            draw_rectangles(frame, faces)

            if has_gui:
                try:
                    cv2.imshow('Human Detection', frame)
                    if cv2.waitKey(1) & 0xFF == ord('q'):
                        break
                except Exception as e:
                    print(f"GUI display error: {e}", file=sys.stderr)
                    has_gui = False
            else:
                time.sleep(FRAME_DELAY)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

