import logging
import signal
import sys
import board
import busio

try:
    import adafruit_bmp280
    import adafruit_bme280
    import adafruit_ms8607
except ImportError:
    adafruit_bmp280 = None
    adafruit_bme280 = None
    adafruit_ms8607 = None

CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"

DEFAULT_SAMPLING_INTERVAL = 60

VALID_PRESSURE_MIN = 70000
VALID_PRESSURE_MAX = 110000
VALID_TEMPERATURE_MIN = -20
VALID_TEMPERATURE_MAX = 50
VALID_HUMIDITY_MIN = 0
VALID_HUMIDITY_MAX = 100

BMP280_CHIP_ID = 0x58
BME280_CHIP_ID = 0x60
MS8607_CHIP_ID = 0x60

SUPPORTED_ADDRESSES = {
    "BMP280": [0x76, 0x77],
    "BME280": [0x76, 0x77],
    "MS8607": [0x78],
}

running = True


def signal_handler(sig, frame):
    global running
    running = False


def setup_logging():
    logging.basicConfig(
        filename=ERROR_LOG_FILE,
        level=logging.ERROR,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def load_configuration(config_file):
    config = {}
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    logging.error(f"Malformed config line: {line}")
                    continue
                key, value = line.split("=", 1)
                config[key.strip()] = value.strip()
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
    except Exception as e:
        logging.error(f"Error reading configuration file: {e}")
    return config


def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        logging.error(f"Error initializing I2C bus: {e}")
        return None


def initialize_sensor(sensor_type, i2c, address, sensor_id):
    if sensor_type == "BMP280":
        if adafruit_bmp280 is None:
            logging.error("adafruit_bmp280 library not available.")
            return None
        try:
            bmp = adafruit_bmp280.BMP280_I2C(i2c, address=address)
            if bmp.chip_id != BMP280_CHIP_ID:
                logging.error(f"BMP280 at 0x{address:02X} returned chip ID 0x{bmp.chip_id:02X}, expected 0x{BMP280_CHIP_ID:02X}")
                return None
            return bmp, sensor_id
        except Exception as e:
            logging.error(f"Error initializing BMP280 at 0x{address:02X}: {e}")
            return None
    elif sensor_type == "BME280":
        if adafruit_bme280 is None:
            logging.error("adafruit_bme280 library not available.")
            return None
        try:
            bme = adafruit_bme280.BME280_I2C(i2c, address=address)
            if bme.chip_id != BME280_CHIP_ID:
                logging.error(f"BME280 at 0x{address:02X} returned chip ID 0x{bme.chip_id:02X}, expected 0x{BME280_CHIP_ID:02X}")
                return None
            return bme, sensor_id
        except Exception as e:
            logging.error(f"Error initializing BME280 at 0x{address:02X}: {e}")
            return None
    elif sensor_type == "MS8607":
        if adafruit_ms8607 is None:
            logging.error("adafruit_ms8607 library not available.")
            return None
        try:
            ms = adafruit_ms8607.MS8607(i2c, address=address)
            if ms.chip_id != MS8607_CHIP_ID:
                logging.error(f"MS8607 at 0x{address:02X} returned chip ID 0x{ms.chip_id:02X}, expected 0x{MS8607_CHIP_ID:02X}")
                return None
            return ms, sensor_id
        except Exception as e:
            logging.error(f"Error initializing MS8607 at 0x{address:02X}: {e}")
            return None
    else:
        logging.error(f"Unknown sensor type: {sensor_type}")
        return None


def read_sensor_data(sensor, sensor_type, sensor_id):
    try:
        pressure = sensor.pressure
        temperature = sensor.temperature
        humidity = None
        if sensor_type in ("BME280", "MS8607"):
            humidity = sensor.humidity
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading sensor data from {sensor_type} {sensor_id}: {e}")
        return None, None, None


def validate_data(pressure, temperature, humidity):
    if pressure is None or temperature is None:
        return False
    if not (VALID_PRESSURE_MIN <= pressure <= VALID_PRESSURE_MAX):
        logging.warning(f"Invalid pressure reading: {pressure} Pa")
        return False
    if not (VALID_TEMPERATURE_MIN <= temperature <= VALID_TEMPERATURE_MAX):
        logging.warning(f"Invalid temperature reading: {temperature} C")
        return False
    if humidity is not None and not (VALID_HUMIDITY_MIN <= humidity <= VALID_HUMIDITY_MAX):
        logging.warning(f"Invalid humidity reading: {humidity} %")
        return False
    return True


def store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS sensor_data (timestamp TEXT, sensor_type TEXT, sensor_id TEXT, pressure_pa REAL, temperature_c REAL, humidity_percent REAL)"
        )
        cursor.execute(
            "INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent) VALUES (?, ?, ?, ?, ?, ?)",
            (timestamp, sensor_type, sensor_id, pressure, temperature, humidity),
        )
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    setup_logging()
    config = load_configuration(CONFIG_FILE)
    i2c = initialize_i2c()
    if i2c is None:
        logging.error("I2C initialization failed. Exiting.")
        return
    sensors = []
    for sensor_num in range(1, 4):
        sensor_type = config.get(f"Sensor{sensor_num}_Type", "")
        sensor_address = config.get(f"Sensor{sensor_num}_Address", "")
        sensor_id = config.get(f"Sensor{sensor_num}_ID", "")
        if not sensor_type:
            continue
        try:
            sensor_address = int(sensor_address, 16)
        except ValueError:
            logging.error(f"Invalid hex address for Sensor{sensor_num}: {sensor_address}")
            continue
        if sensor_address not in SUPPORTED_ADDRESSES.get(sensor_type, []):
            logging.error(f"Unsupported I2C address 0x{sensor_address:02X} for {sensor_type}")
            continue
        sensor, sensor_id = initialize_sensor(sensor_type, i2c, sensor_address, sensor_id)
        if sensor:
            sensors.append((sensor, sensor_type, sensor_id))
    if not sensors:
        logging.error("No sensors detected. Exiting.")
        return
    sampling_interval = config.get("Sampling_Interval_Seconds", DEFAULT_SAMPLING_INTERVAL)
    if sampling_interval <= 0:
        logging.error("Invalid sampling interval. Exiting.")
        return
    logging.info(f"Starting monitoring with interval {sampling_interval}s. Sensors: {[s[1] for s in sensors]}")
    try:
        while running:
            for sensor, sensor_type, sensor_id in sensors:
                timestamp = datetime.datetime.now().isoformat()
                pressure, temperature, humidity = read_sensor_data(sensor, sensor_type, sensor_id)
                if pressure is not None and temperature is not None:
                    if validate_data(pressure, temperature, humidity):
                        store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity)
                time.sleep(sampling_interval)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

