import time
import signal
import sys
import random
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Configuration
BUZZER_PIN = 17
TEMP_THRESHOLD = 30.0
POLL_INTERVAL = 0.1
ALERT_DURATION = 1.0
AMG8833_I2C_ADDR = 0x69

# Global resources for cleanup
buzzer = None
i2c = None
amg = None
running = True


def cleanup():
    """Release all hardware resources cleanly."""
    global buzzer, i2c, amg
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if amg is not None:
        try:
            amg.close()
        except Exception:
            pass
        amg = None
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize I2C bus, AMG8833 sensor, and buzzer.
    Returns True on success, False on failure."""
    global i2c, amg, buzzer
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False
    try:
        amg = adafruit_amg88xx.AMG88XX(i2c, addr=AMG8833_I2C_ADDR)
    except Exception as e:
        print(f"Error initializing AMG8833 at 0x{AMG8833_I2C_ADDR:02X}: {e}")
        print("Falling back to simulated thermal data.")
        amg = None
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing buzzer on GPIO{BUZZER_PIN}: {e}")
        buzzer = None
    return amg is not None


def read_thermal_data():
    """Read 8x8 thermal data from AMG8833 or simulate it."""
    if amg is not None:
        try:
            pixels = amg.pixels
            if len(pixels) != 64:
                print("Warning: unexpected pixel count from AMG8833.")
                return None
            return pixels
        except Exception as e:
            print(f"Error reading AMG8833: {e}")
            return None
    else:
        return [random.uniform(20.0, 45.0) for _ in range(64)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds the temperature threshold."""
    if thermal_data is None:
        return False
    return any(temp > TEMP_THRESHOLD for temp in thermal_data)


def trigger_alert(buzzer_obj):
    """Sound the buzzer for ALERT_DURATION seconds."""
    if buzzer_obj is None:
        return
    try:
        buzzer_obj.on()
        time.sleep(ALERT_DURATION)
        buzzer_obj.off()
    except Exception as e:
        print(f"Error controlling buzzer: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_hardware():
        print("Hardware initialization failed. Exiting.")
        sys.exit(1)

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            thermal_data = read_thermal_data()
            if thermal_data is not None:
                human_detected = detect_human(thermal_data)
                if human_detected:
                    print("Human detected! Activating alert.")
                    trigger_alert(buzzer)
                else:
                    print("No human detected.")
            else:
                print("Thermal data unavailable. Check sensor connection.")
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

