import os
import sys
import time
import signal
import logging
import threading
import paho.mqtt.client as mqtt
from gpiozero import OutputDevice
import adafruit_dht
import board

# Configuration
DHT_PIN = board.D4
SOIL_MOISTURE_CHANNEL = 0
LIGHT_LEVEL_CHANNEL = 1
WATER_PUMP_PIN = 22
VENTILATION_FAN_PIN = 23
SOIL_MOISTURE_THRESHOLD = 30.0
TEMPERATURE_THRESHOLD_HIGH = 30.0
TEMPERATURE_THRESHOLD_LOW = 25.0
READ_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2

# Logging setup
logging.basicConfig(
    filename='greenhouse.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
console_handler = logging.StreamHandler()
console_handler.setLevel(logging.INFO)
console_handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
logging.getLogger().addHandler(console_handler)

# Global state
running = True
pump_state = False
fan_state = False
pump = None
fan = None
dht_device = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False


def read_dht22():
    global dht_device
    if dht_device is None:
        logging.error("DHT22 device not initialized")
        return None, None
    for attempt in range(MAX_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            logging.warning(f"DHT22 returned None on attempt {attempt + 1}")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error on attempt {attempt + 1}: {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error on attempt {attempt + 1}: {e}")
        time.sleep(RETRY_DELAY)
    logging.error("DHT22 failed after all retries")
    return None, None


def read_ads1115(channel):
    try:
        import smbus2
        bus = smbus2.SMBus(1)
        config = 0x4003 | ((channel & 0x01) << 12) | (0x0003 << 9)
        bus.write_i2c_block_data(0x48, 0x01, [(config >> 8) & 0xFF, config & 0xFF])
        time.sleep(0.1)
        data = bus.read_i2c_block_data(0x48, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        if raw & 0x8000:
            raw -= 1 << 16
        voltage = raw * 3.3 / 32767.0
        return voltage
    except Exception as e:
        logging.error(f"ADS1115 read error on channel {channel}: {e}")
        return None


def validate_reading(value, min_val, max_val, name):
    if value is None:
        return False, f"{name} reading is None"
    if not (min_val <= value <= max_val):
        return False, f"{name} value {value} out of range [{min_val}, {max_val}]"
    return True, None


def publish_mqtt(topic, payload):
    global mqtt_client
    if mqtt_client is None or not mqtt_client.is_connected():
        logging.warning("MQTT client not connected, cannot publish")
        return
    try:
        mqtt_client.publish(topic, payload, qos=0, retain=False)
        logging.info(f"Published to {topic}: {payload}")
    except Exception as e:
        logging.error(f"MQTT publish error to {topic}: {e}")


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logging.info("Connected to MQTT broker")
        client.subscribe("greenhouse/actuator/water_pump/control")
        client.subscribe("greenhouse/actuator/ventilation_fan/control")
        logging.info("Subscribed to actuator control topics")
    else:
        logging.error(f"MQTT connection failed with reason code {reason_code}")


def on_message(client, userdata, msg):
    global pump_state, fan_state
    try:
        topic = msg.topic
        payload = msg.payload.decode().strip().upper()
        logging.info(f"Received '{payload}' on {topic}")
        if topic == "greenhouse/actuator/water_pump/control":
            if payload == "ON":
                pump_state = True
                logging.info("Water pump manual override: ON")
            elif payload == "OFF":
                pump_state = False
                logging.info("Water pump manual override: OFF")
            else:
                logging.warning(f"Invalid water pump payload: {payload}")
        elif topic == "greenhouse/actuator/ventilation_fan/control":
            if payload == "ON":
                fan_state = True
                logging.info("Ventilation fan manual override: ON")
            elif payload == "OFF":
                fan_state = False
                logging.info("Ventilation fan manual override: OFF")
            else:
                logging.warning(f"Invalid fan payload: {payload}")
    except Exception as e:
        logging.error(f"MQTT message processing error: {e}")


def control_actuator(actuator, name, threshold, on_threshold, off_threshold, current_state):
    global pump_state, fan_state
    if actuator is None:
        logging.warning(f"Cannot control {name}: actuator device not initialized")
        return
    try:
        if actuator.is_active:
            logging.info(f"{name} is currently ON")
            return
        if on_threshold and current_state >= on_threshold:
            logging.info(f"{name} threshold reached, turning ON")
            actuator.on()
            if name == "Water Pump":
                pump_state = True
            elif name == "Ventilation Fan":
                fan_state = True
            publish_mqtt(f"greenhouse/actuator/{name}/status", "ON")
            time.sleep(10)
            actuator.off()
            if name == "Water Pump":
                pump_state = False
            elif name == "Ventilation Fan":
                fan_state = False
            publish_mqtt(f"greenhouse/actuator/{name}/status", "OFF")
            logging.info(f"{name} turned OFF after 10 seconds")
        elif off_threshold and current_state < off_threshold:
            logging.info(f"{name} threshold reached, turning OFF")
            actuator.off()
            if name == "Water Pump":
                pump_state = False
            elif name == "Ventilation Fan":
                fan_state = False
            publish_mqtt(f"greenhouse/actuator/{name}/status", "OFF")
    except Exception as e:
        logging.error(f"Error controlling {name}: {e}")


def cleanup():
    global pump, fan, dht_device, mqtt_client
    logging.info("Cleaning up resources...")
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception as e:
            logging.error(f"Error closing pump: {e}")
    if fan is not None:
        try:
            fan.off()
            fan.close()
        except Exception as e:
            logging.error(f"Error closing fan: {e}")
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception as e:
            logging.error(f"Error closing DHT22: {e}")
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception as e:
            logging.error(f"Error disconnecting MQTT: {e}")
    logging.info("Cleanup complete")


def main():
    global running, pump, fan, dht_device, mqtt_client
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        pump = OutputDevice(WATER_PUMP_PIN, active_high=True, initial_value=False)
        fan = OutputDevice(VENTILATION_FAN_PIN, active_high=True, initial_value=False)
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        mqtt_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        mqtt_client.username_pw_set(os.environ.get("MQTT_BROKER_USERNAME"),
                                    os.environ.get("MQTT_BROKER_PASSWORD"))
        mqtt_client.on_connect = on_connect
        mqtt_client.on_message = on_message
        mqtt_client.tls_set()
        mqtt_client.connect(os.environ.get("MQTT_BROKER_HOST", "localhost"),
                            int(os.environ.get("MQTT_BROKER_PORT", "8883")), keepalive=60)
        mqtt_client.loop_start()
        while running:
            temperature, humidity = read_dht22()
            soil_voltage = read_ads1115(SOIL_MOISTURE_CHANNEL)
            light_voltage = read_ads1115(LIGHT_LEVEL_CHANNEL)
            if temperature is not None and humidity is not None:
                temp_valid, temp_msg = validate_reading(temperature, -40, 80, "Temperature")
                hum_valid, hum_msg = validate_reading(humidity, 0, 100, "Humidity")
                if temp_valid and hum_valid:
                    publish_mqtt("greenhouse/temperature", f"{temperature:.1f}")
                    publish_mqtt("greenhouse/humidity", f"{humidity:.1f}")
                    logging.info(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                else:
                    logging.warning(f"Invalid temperature/humidity: {temp_msg}, {hum_msg}")
            else:
                logging.warning("DHT22 read failed, skipping temperature/humidity")
            if soil_voltage is not None:
                soil_moisture = 100 - (soil_voltage / 3.3) * 100
                soil_valid, soil_msg = validate_reading(soil_moisture, 0, 100, "Soil Moisture")
                if soil_valid:
                    publish_mqtt("greenhouse/soil_moisture", f"{soil_moisture:.1f}")
                    logging.info(f"Soil Moisture: {soil_moisture:.1f}%")
                    control_actuator(pump, "Water Pump", SOIL_MOISTURE_THRESHOLD, None, None, pump_state)
                else:
                    logging.warning(f"Invalid soil moisture: {soil_msg}")
            else:
                logging.warning("Soil moisture read failed")
            if light_voltage is not None:
                light_level = (light_voltage / 3.3) * 100
                light_valid, light_msg = validate_reading(light_level, 0, 100, "Light Level")
                if light_valid:
                    publish_mqtt("greenhouse/light_level", f"{light_level:.1f}")
                    logging.info(f"Light Level: {light_level:.1f}%")
            else:
                logging.warning("Light level read failed")
            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

