cam = None
try:
    cam = Picamera2()
    config = cam.create_preview_configuration(
        main={"size": (640, 360), "format": "RGB888"},
        controls={"FrameRate": 30}
    )
    cam.configure(config)
    cam.start()
    time.sleep(1)
except Exception as e:
    print(f"Camera initialization failed: {e}", file=sys.stderr)
    if cam is not None:
        try:
            cam.close()
        except Exception:
            pass
    sys.exit(1)

