import signal
import sys
import time
import board
import busio
import digitalio
from PIL import Image, ImageDraw, ImageFont
import adafruit_epd.il0373
import adafruit_bme280_spi

# ---------------------------------------------------------------------------
# Pin assignments (BCM numbering)
#   BME280: CS=GPIO7 (CE1), SCK=GPIO11, MOSI=GPIO10, MISO=GPIO9
#   IL0373: CS=GPIO5, DC=GPIO6, RST=GPIO9, BUSY=GPIO10
# ---------------------------------------------------------------------------
BME280_CS_PIN = board.D7   # CE1 -> GPIO7
EPD_CS_PIN = board.D5      # GPIO5
EPD_DC_PIN = board.D6      # GPIO6
EPD_RST_PIN = board.D9     # GPIO9
EPD_BUSY_PIN = board.D10   # GPIO10

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_spi = None
_epd = None
_bme = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _spi, _epd, _bme
    if _epd is not None:
        try:
            _epd.display()
        except Exception:
            pass
    for dev in (_epd, _bme):
        if dev is not None:
            try:
                dev.deinit()
            except Exception:
                pass
    if _spi is not None:
        try:
            _spi.deinit()
        except Exception:
            pass


def _init_spi():
    global _spi
    try:
        return busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize SPI bus: {exc}")
        return None


def _init_epd(spi):
    global _epd
    try:
        cs = digitalio.DigitalInOut(EPD_CS_PIN)
        dc = digitalio.DigitalInOut(EPD_DC_PIN)
        rst = digitalio.DigitalInOut(EPD_RST_PIN)
        busy = digitalio.DigitalInOut(EPD_BUSY_PIN)
        return adafruit_epd.il0373.IL0373(
            128, 296, spi, cs, dc, rst, busy
        )
    except Exception as exc:
        print(f"[ERROR] Failed to initialize e-paper display: {exc}")
        return None


def _init_bme280(spi):
    global _bme
    try:
        cs = digitalio.DigitalInOut(BME280_CS_PIN)
        return adafruit_bme280_spi.Adafruit_BME280_SPI(spi, cs)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize BME280 sensor: {exc}")
        return None


def _read_sensor(bme):
    try:
        return bme.temperature, bme.humidity, bme.pressure
    except (RuntimeError, ValueError) as exc:
        print(f"[ERROR] BME280 read failed: {exc}")
        return None, None, None


def _update_display(epd, temp, hum, pres):
    try:
        image = Image.new("1", (epd.width, epd.height), 255)
        draw = ImageDraw.Draw(image)
        font = ImageFont.load_default()

        if temp is not None:
            draw.text((0, 0), f"Temp: {temp:.1f} C", font=font, fill=0)
        if hum is not None:
            draw.text((0, 16), f"Hum: {hum:.1f} %", font=font, fill=0)
        if pres is not None:
            draw.text((0, 32), f"Pres: {pres:.1f} hPa", font=font, fill=0)

        epd.image(image)
        epd.display()
    except Exception as exc:
        print(f"[ERROR] Display update failed: {exc}")


def main():
    global _running, _spi, _epd, _bme

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _spi = _init_spi()
    if _spi is None:
        print("[FATAL] Cannot continue without SPI bus.")
        sys.exit(1)

    _epd = _init_epd(_spi)
    if _epd is None:
        print("[FATAL] Cannot continue without e-paper display.")
        _cleanup()
        sys.exit(1)

    _bme = _init_bme280(_spi)
    if _bme is None:
        print("[WARN] BME280 not detected; display will show blank readings.")

    while _running:
        temp, hum, pres = _read_sensor(_bme)
        if temp is not None and hum is not None and pres is not None:
            print(f"T={temp:.1f} C  H={hum:.1f} %  P={pres:.1f} hPa")
        else:
            print("[WARN] Skipping display update due to sensor read failure.")

        _update_display(_epd, temp, hum, pres)

        # Sleep in small increments so signals are caught promptly
        slept = 0
        while _running and slept < 60:
            time.sleep(1)
            slept += 1

    _cleanup()


if __name__ == "__main__":
    main()

