import signal
import sys
import time
import cv2
import numpy as np
import RPi.GPIO as GPIO
from picamera2 import Picamera2
import serial

# Constants
CAMERA_RESOLUTION = (160, 120)
CAMERA_FRAMERATE = 16
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY_CYCLE = 7.0
SERVO_MIN_DUTY_CYCLE = 5.0
SERVO_MAX_DUTY_CYCLE = 12.0
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
SEARCH_ANGLE = 0.0

# Global state for cleanup
pwm1 = None
pwm2 = None
camera = None
arduino = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def initialize_camera():
    try:
        cam = Picamera2()
        config = cam.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        cam.configure(config)
        cam.start()
        return cam
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None


def initialize_arduino():
    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(2)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing Arduino: {e}", file=sys.stderr)
        return None


def initialize_gpio():
    GPIO.setmode(GPIO.BOARD)
    GPIO.setup(SERVO_PIN_1, GPIO.OUT)
    GPIO.setup(SERVO_PIN_2, GPIO.OUT)
    pwm1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
    pwm2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
    pwm1.start(SERVO_CENTER_DUTY_CYCLE)
    pwm2.start(SERVO_CENTER_DUTY_CYCLE)
    return pwm1, pwm2


def segment_red(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask1 = cv2.inRange(hsv, np.array([160, 160, 10]), np.array([190, 255, 255]))
    mask2 = cv2.inRange(ycr, np.array([0, 165, 0]), np.array([255, 255, 255]))
    mask = mask1 | mask2
    mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
    mask = cv2.dilate(mask, np.ones((8, 8), np.uint8))
    return mask


def find_largest_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = None
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = contour
    if largest_contour is not None:
        x, y, w, h = cv2.boundingRect(largest_contour)
        return x, y, w, h, largest_area
    return None


def control_servo(pwm, angle):
    duty = SERVO_CENTER_DUTY_CYCLE + (angle * 5)
    duty = max(SERVO_MIN_DUTY_CYCLE, min(SERVO_MAX_DUTY_CYCLE, duty))
    pwm.ChangeDutyCycle(duty)


def cleanup():
    global pwm1, pwm2, camera, arduino
    if pwm1 is not None:
        pwm1.stop()
    if pwm2 is not None:
        pwm2.stop()
    GPIO.cleanup()
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass
    if arduino is not None and arduino.is_open:
        arduino.close()


def main():
    global camera, arduino, pwm1, pwm2, running, SEARCH_ANGLE

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = initialize_camera()
    if camera is None:
        cleanup()
        sys.exit(1)

    arduino = initialize_arduino()
    if arduino is None:
        cleanup()
        sys.exit(1)

    pwm1, pwm2 = initialize_gpio()

    try:
        while running:
            frame = camera.capture_array()
            if frame is None:
                continue
            frame = cv2.flip(frame, 1)
            mask = segment_red(frame)
            result = find_largest_blob(mask)

            if result is None:
                if SEARCH_ANGLE < 1.0:
                    control_servo(pwm2, SEARCH_ANGLE)
                    SEARCH_ANGLE += 0.1
                else:
                    control_servo(pwm2, SERVO_CENTER_DUTY_CYCLE)
                    SEARCH_ANGLE = 0.0
                try:
                    arduino.write(b'h')
                except serial.SerialException as e:
                    print(f"Error writing to Arduino: {e}", file=sys.stderr)
            else:
                x, y, w, h, area = result
                center_x = x + w / 2.0 - CAMERA_RESOLUTION[0] / 2.0
                center_y = CAMERA_RESOLUTION[1] / 2.0 - (y + h / 2.0)

                control_servo(pwm1, SERVO_CENTER_DUTY_CYCLE)
                control_servo(pwm2, SERVO_CENTER_DUTY_CYCLE)

                if center_x < -24:
                    if 10 < h < 30:
                        try:
                            arduino.write(b'k')
                        except serial.SerialException as e:
                            print(f"Error writing to Arduino: {e}", file=sys.stderr)
                    else:
                        try:
                            arduino.write(b'a')
                        except serial.SerialException as e:
                            print(f"Error writing to Arduino: {e}", file=sys.stderr)
                elif center_x > 24:
                    if 10 < h < 30:
                        try:
                            arduino.write(b'j')
                        except serial.SerialException as e:
                            print(f"Error writing to Arduino: {e}", file=sys.stderr)
                    else:
                        try:
                            arduino.write(b'b')
                        except serial.SerialException as e:
                            print(f"Error writing to Arduino: {e}", file=sys.stderr)
                else:
                    try:
                        arduino.write(b'g')
                    except serial.SerialException as e:
                        print(f"Error writing to Arduino: {e}", file=sys.stderr)

                if 10 < h < 25:
                    try:
                        arduino.write(b'f')
                    except serial.SerialException as e:
                        print(f"Error writing to Arduino: {e}", file=sys.stderr)
                elif 25 <= h < 85:
                    try:
                        arduino.write(b'c')
                    except serial.SerialException as e:
                        print(f"Error writing to Arduino: {e}", file=sys.stderr)
                    time.sleep(0.7)
                elif h >= 85 or h <= 10:
                    try:
                        arduino.write(b'd')
                    except serial.SerialException as e:
                        print(f"Error writing to Arduino: {e}", file=sys.stderr)

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

