#!/usr/bin/env python3
"""Wildlife camera with PIR motion sensor and picamera2 video capture."""

import os
import sys
import time
import signal
import logging
import configparser
from datetime import datetime
from pathlib import Path

from gpiozero import MotionSensor
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

DEFAULT_CONFIG = {
    'RESOLUTION': '640x480',
    'FRAMERATE': '20',
    'IMAGE_QUALITY': '85',
    'VIDEO_BITRATE': '1700000',
    'GPIO_PIN': '4',
    'MOTION_DELAY': '2',
    'STORAGE_DIRECTORY': '/home/pi/wildlife_media',
    'DISK_SPACE_THRESHOLD_MB': '500',
    'LOG_FILE': '/var/log/wildlifecam/wildlifecam.log',
    'LOG_LEVEL': 'INFO',
}


class WildlifeCamera:
    def __init__(self, config_file='config.ini'):
        self.config = configparser.ConfigParser()
        self.config.read_dict({'DEFAULT': DEFAULT_CONFIG})
        self.config.read(config_file)
        self.log = self._setup_logging()
        self.resolution = self._parse_resolution()
        self.frame_rate = self._parse_int('FRAMERATE')
        self.image_quality = self._parse_int('IMAGE_QUALITY')
        self.video_bitrate = self._parse_int('VIDEO_BITRATE')
        self.gpio_pin = self._parse_int('GPIO_PIN')
        self.motion_delay = self._parse_int('MOTION_DELAY')
        self.storage_directory = self._parse_path('STORAGE_DIRECTORY')
        self.disk_space_threshold_mb = self._parse_int('DISK_SPACE_THRESHOLD_MB')
        self.log_file = self._parse_path('LOG_FILE')
        self.log_level = self._parse_log_level()
        self.picam2 = None
        self.pir = None
        self._running = True
        self._degraded = False

    def _setup_logging(self):
        log_dir = Path(self.log_file).parent
        if not log_dir.exists() or not log_dir.is_dir():
            try:
                log_dir.mkdir(parents=True, exist_ok=True)
            except OSError as e:
                print(f'Cannot create log directory {log_dir}: {e}', file=sys.stderr)
                log_dir = Path('./logs')
                try:
                    log_dir.mkdir(parents=True, exist_ok=True)
                except OSError:
                    log_dir = Path('.')
        log_file = str(log_dir / Path(self.log_file).name)
        logging.basicConfig(
            filename=log_file,
            level=getattr(logging, self.log_level.upper(), logging.INFO),
            format='%(asctime)s - %(levelname)s - %(message)s',
        )
        return logging.getLogger(__name__)

    @staticmethod
    def _parse_resolution(res_str=None):
        res = res_str if res_str else self.config.get('DEFAULT', 'RESOLUTION')
        try:
            w, h = res.lower().split('x')
            return (int(w), int(h))
        except ValueError:
            self.log.error(f'Invalid resolution "{res}", using default 640x480')
            return (640, 480)

    @staticmethod
    def _parse_int(key, val=None):
        return int(val if val else self.config.get('DEFAULT', key))

    @staticmethod
    def _parse_path(key, val=None):
        return val if val else self.config.get('DEFAULT', key)

    @staticmethod
    def _parse_log_level(level=None):
        return level if level else self.config.get('DEFAULT', 'LOG_LEVEL')

    def _init_camera(self):
        try:
            self.picam2 = Picamera2()
            still_config = self.picam2.create_still_configuration(
                main={'size': self.resolution}
            )
            video_config = self.picam2.create_video_configuration(
                main={'size': self.resolution},
                controls={'FrameRate': self.frame_rate},
            )
            self.picam2.configure(still_config)
            self.picam2.start()
            self.log.info('Camera initialized successfully')
        except Exception as e:
            self.log.error(f'Failed to initialize camera: {e}')
            self.picam2 = None
            self._degraded = True

    def _init_pir(self):
        try:
            self.pir = MotionSensor(self.gpio_pin, pull_up=False)
            self.log.info(f'PIR sensor initialized on GPIO {self.gpio_pin}')
        except Exception as e:
            self.log.error(f'Failed to initialize PIR sensor: {e}')
            self.pir = None
            self._degraded = True

    def _cleanup(self, signum=None, frame=None):
        self._running = False
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception:
                pass
        if self.pir is not None:
            try:
                self.pir.close()
            except Exception:
                pass
        self.log.info('Cleanup complete')
        if signum is not None:
            sys.exit(0)

    def _ensure_storage_dir(self):
        storage_path = Path(self.storage_directory)
        storage_path.mkdir(parents=True, exist_ok=True)
        return str(storage_path)

    def _check_disk_space(self, storage_dir):
        try:
            statvfs = os.statvfs(storage_dir)
            free_mb = (statvfs.f_bavail * statvfs.f_frsize) / (1024 * 1024)
            if free_mb < self.disk_space_threshold_mb:
                self._delete_oldest_files(storage_dir)
        except OSError as e:
            self.log.warning(f'Cannot check disk space: {e}')

    def _delete_oldest_files(self, storage_dir):
        try:
            storage_path = Path(storage_dir)
            files = sorted(
                f for f in storage_path.iterdir()
                if f.is_file() and not f.name.startswith('.')
            )
            total_size = sum(f.stat().st_size for f in files)
            while total_size < self.disk_space_threshold_mb * 1024 * 1024:
                oldest = files.pop(0)
                try:
                    oldest.unlink()
                    total_size -= oldest.stat().st_size
                    self.log.info(f'Deleted oldest file: {oldest}')
                except OSError as e:
                    self.log.error(f'Failed to delete {oldest}: {e}')
                    break
        except Exception as e:
            self.log.error(f'Error deleting oldest files: {e}')

    def _capture_images(self):
        images = []
        for i in range(3):
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            filename = f'image_{timestamp}_{i}.jpg'
            filepath = os.path.join(self.storage_directory, filename)
            try:
                self.picam2.configure(self.picam2.create_still_configuration(
                    main={'size': self.resolution}
                ))
                self.picam2.start()
                self.picam2.capture_file(filepath, format='jpeg')
                self.picam2.stop()
                images.append(filepath)
                self.log.info(f'Captured image: {filepath}')
            except Exception as e:
                self.log.error(f'Failed to capture image {i}: {e}')
                return None
            time.sleep(0.5)
        return images

    def _capture_video(self):
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        videofilename = f'video_{timestamp}.h264'
        videofilepath = os.path.join(self.storage_directory, videofilename)
        try:
            encoder = H264Encoder(bitrate=self.video_bitrate)
            output = FileOutput(videofilepath)
            self.picam2.configure(self.picam2.create_video_configuration(
                main={'size': self.resolution},
                controls={'FrameRate': self.frame_rate},
            ))
            self.picam2.start()
            encoder.start()
            encoder.output = output
            encoder.start()
            self.picam2.start_encoder(encoder)
            time.sleep(5)
            self.picam2.stop_encoder()
            encoder.stop()
            self.picam2.stop()
            self.log.info(f'Captured video: {videofilepath}')
            return videofilepath
        except Exception as e:
            self.log.error(f'Failed to capture video: {e}')
            return None

    def run(self):
        signal.signal(signal.SIGINT, self._cleanup)
        signal.signal(signal.SIGTERM, self._cleanup)
        storage_dir = self._ensure_storage_dir()
        self._init_camera()
        self._init_pir()
        if self._degraded:
            self.log.warning('Running in degraded mode (camera/GPIO unavailable)')
        try:
            while self._running:
                if self.pir is not None:
                    if self.pir.wait_for_motion(timeout=1.0):
                        self.log.info('Motion detected!')
                        time.sleep(self.motion_delay)
                        self._check_disk_space(storage_dir)
                        images = self._capture_images()
                        if images:
                            video_path = self._capture_video()
                            if video_path:
                                self.log.info('Capture sequence complete')
                        else:
                            self.log.warning('Image capture failed, skipping video')
                else:
                    self.log.warning('PIR sensor unavailable, waiting...')
                time.sleep(0.1)
        except Exception as e:
            self.log.error(f'Unexpected error in main loop: {e}')
        finally:
            self._cleanup()


if __name__ == '__main__':
    camera = WildlifeCamera()
    camera.run()

