import io
import os
import time
import signal
import logging
import configparser
from datetime import datetime

import RPi.GPIO as GPIO
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput
import smbus2

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename='security_camera.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG_FILE = 'config.ini'
DEFAULT_CONFIG = {
    'motion_threshold': '20',
    'motion_sensitivity': '50',
    'debounce_time': '5',
    'recording_duration': '10',
    'disk_space_limit': '500',
}


def load_config(path):
    cfg = configparser.ConfigParser()
    cfg.read(path)
    for section, defaults in DEFAULT_CONFIG.items():
        if not cfg.has_section(section):
            cfg[section] = {}
        for key, defval in defaults.items():
            if not cfg.has_option(section, key):
                cfg[section][key] = defval
    return cfg


# ---------------------------------------------------------------------------
# BH1750 light sensor
# ---------------------------------------------------------------------------
class BH1750:
    def __init__(self, bus=1, addr=0x23):
        self.bus = bus
        self.addr = addr
        self.bus_obj = None
        self._init_sensor()

    def _init_sensor(self):
        try:
            self.bus_obj = smbus2.SMBus(self.bus)
            # Power on: 0x01
            self.bus_obj.write_byte(self.addr, 0x01)
            time.sleep(0.01)
            # Continuous high-res mode: 0x10
            self.bus_obj.write_byte(self.addr, 0x10)
            time.sleep(0.18)  # max measurement time for high-res mode
            logging.info("BH1750 initialized on bus %d addr 0x%02X", self.bus, self.addr)
        except Exception as e:
            logging.error("Failed to initialize BH1750: %s", e)
            self.bus_obj = None

    def read_light_level(self):
        if self.bus_obj is None:
            return None
        try:
            data = self.bus_obj.read_i2c_block_data(self.addr, 0x00, 2)
            if len(data) < 2:
                logging.error("BH1750: incomplete read (%d bytes)", len(data))
                return None
            raw = data[1] + 256 * data[0]
            lux = raw / 1.2
            return lux
        except Exception as e:
            logging.error("BH1750 read error: %s", e)
            return None

    def close(self):
        if self.bus_obj is not None:
            try:
                self.bus_obj.close()
            except Exception:
                pass
            self.bus_obj = None


# ---------------------------------------------------------------------------
# Circular frame buffer
# ---------------------------------------------------------------------------
class CircularFrameBuffer:
    def __init__(self, capacity=72):
        self.capacity = capacity
        self.frames = []
        self.index = 0

    def append(self, frame):
        self.frames.append(frame)
        if len(self.frames) > self.capacity:
            self.frames.pop(0)
        self.index = (self.index + 1) % self.capacity

    def get_last_n(self, n):
        if len(self.frames) < n:
            return list(self.frames)
        start = self.index - n + 1
        if start < 0:
            start += self.capacity
        return self.frames[start:] + self.frames[:start]


# ---------------------------------------------------------------------------
# Motion detector
# ---------------------------------------------------------------------------
class MotionDetector:
    def __init__(self, threshold, sensitivity, debounce):
        self.threshold = threshold
        self.sensitivity = sensitivity
        self.debounce = debounce
        self.motion_active = False
        self.last_motion_time = 0.0

    def detect(self, frame1, frame2):
        if frame1 is None or frame2 is None:
            return False
        if len(frame1) != len(frame2):
            return False
        diff = sum(abs(p1 - p2) for p1, p2 in zip(frame1, frame2))
        avg_diff = diff / len(frame1)
        changed_pct = (diff / (len(frame1) * 255.0)) * 100.0
        if avg_diff > self.threshold and changed_pct > self.sensitivity:
            now = time.time()
            if not self.motion_active or (now - self.last_motion_time) > self.debounce:
                self.motion_active = True
                self.last_motion_time = now
                return True
        else:
            self.motion_active = False
        return False

    def is_active(self):
        return self.motion_active


# ---------------------------------------------------------------------------
# SecurityCamera
# ---------------------------------------------------------------------------
class SecurityCamera:
    def __init__(self, config):
        self.config = config
        self.motion_threshold = self.config.getint('motion_settings', 'motion_threshold')
        self.motion_sensitivity = self.config.getint('motion_settings', 'motion_sensitivity')
        self.debounce_time = self.config.getint('motion_settings', 'debounce_time')
        self.recording_duration = self.config.getint('recording_settings', 'recording_duration')
        self.disk_space_limit = self.config.getint('recording_settings', 'disk_space_limit')
        self.output_dir = '/home/pi/security_footage'
        self.camera = None
        self.encoder = None
        self.bus = None
        self.light_sensor = None
        self.gpio_pin = 17
        self.frame_buffer = CircularFrameBuffer(72)
        self.motion_detector = MotionDetector(
            self.motion_threshold,
            self.motion_sensitivity,
            self.debounce_time
        )
        self.running = True

    def initialize(self):
        try:
            os.makedirs(self.output_dir, exist_ok=True)
            logging.info("Output directory ready: %s", self.output_dir)
        except OSError as e:
            logging.error("Cannot create output directory: %s", e)
            return False

        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": (640, 480), "format": "YUV420"},
                controls={"FrameRate": 24}
            )
            self.camera.configure(config)
            self.camera.start()
            logging.info("Camera initialized at 640x480 @ 24 fps")
        except Exception as e:
            logging.error("Camera init failed: %s", e)
            return False

        try:
            self.encoder = H264Encoder(bitrate=10000000)
            logging.info("H264 encoder ready")
        except Exception as e:
            logging.error("Encoder init failed: %s", e)
            return False

        try:
            self.light_sensor = BH1750(bus=1, addr=0x23)
        except Exception as e:
            logging.warning("BH1750 init failed (%s); continuing without light sensor", e)
            self.light_sensor = None

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info("GPIO %d reserved as input (future sensor)", self.gpio_pin)
        except Exception as e:
            logging.warning("GPIO init failed (%s); continuing without GPIO", e)

        return True

    def _read_frame(self):
        try:
            return self.camera.capture_array("main")
        except Exception as e:
            logging.error("Frame capture failed: %s", e)
            return None

    def _save_recording(self, filename):
        try:
            output = FileOutput(filename)
            self.encoder.output = output
            self.encoder.start()
            self.camera.start_encoder(self.encoder)
            time.sleep(self.recording_duration)
            self.camera.stop_encoder(self.encoder)
            self.encoder.stop()
            logging.info("Saved %s", filename)
        except Exception as e:
            logging.error("Recording failed for %s: %s", filename, e)
            try:
                self.camera.stop_encoder(self.encoder)
                self.encoder.stop()
            except Exception:
                pass

    def _check_disk_space(self):
        try:
            total = os.path.getsize(self.output_dir)
            mb = total / (1024 * 1024)
            if mb > self.disk_space_limit:
                logging.warning("Disk usage %.1f MB exceeds limit %d MB", mb, self.disk_space_limit)
                while mb > self.disk_space_limit:
                    files = sorted(
                        os.listdir(self.output_dir),
                        key=lambda f: os.path.getmtime(os.path.join(self.output_dir, f))
                    )
                    if not files:
                        break
                    f = os.path.join(self.output_dir, files[0])
                    try:
                        os.remove(f)
                        mb -= os.path.getsize(f) / (1024 * 1024)
                        logging.info("Deleted oldest file: %s", f)
                    except OSError as e:
                        logging.error("Could not delete %s: %s", f, e)
                        break
        except Exception as e:
            logging.error("Disk check error: %s", e)

    def run(self):
        if not self.initialize():
            return

        logging.info("Security camera started")
        try:
            while self.running:
                frame1 = self._read_frame()
                if frame1 is None:
                    time.sleep(0.1)
                    continue
                self.frame_buffer.append(frame1)

                if self.light_sensor is not None:
                    lux = self.light_sensor.read_light_level()
                    if lux is not None:
                        logging.info("Ambient light: %.2f lux", lux)

                self._check_disk_space()

                frame2 = self._read_frame()
                if frame2 is None:
                    time.sleep(0.1)
                    continue

                if self.motion_detector.detect(frame1, frame2):
                    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                    filename = os.path.join(
                        self.output_dir,
                        f"camera1_{timestamp}.h264"
                    )
                    logging.info("Motion detected - starting recording %s", filename)
                    self._save_recording(filename)
                    self.frame_buffer.clear()

                time.sleep(0.1)
        except Exception as e:
            logging.error("Unexpected error in main loop: %s", e)
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Shutting down...")
        self.running = False
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
        if self.encoder is not None:
            try:
                self.encoder.stop()
            except Exception:
                pass
        if self.light_sensor is not None:
            self.light_sensor.close()
        try:
            GPIO.cleanup()
        except Exception:
            pass
        logging.info("Cleanup complete")


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def signal_handler(signum, frame):
    logging.info("Signal %d received, shutting down", signum)
    raise SystemExit(0)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    camera = SecurityCamera(config)
    camera.run()


if __name__ == "__main__":
    main()

