        picam2.start()
        logger.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        return None

def initialize_gpio(pin):
    try:
        device = OutputDevice(pin, active_high=True, initial_value=True)
        logger.info(f"GPIO pin {pin} initialized as output (HIGH).")
        return device
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        return None

def process_frame(frame):
    try:
        return frame[ROI]
    except Exception as e:
        logger.error(f"Frame processing failed: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2 = None
    gpio_device = None

    try:
        picam2 = initialize_camera()
        if picam2 is None:
            raise RuntimeError("Camera initialization failed.")

        gpio_device = initialize_gpio(ACTIVE_PIN)
        if gpio_device is None:
            raise RuntimeError("GPIO initialization failed.")

        cv2.namedWindow("Output Image", cv2.WINDOW_AUTOSIZE)
        logger.info("Entering main loop. Press Enter to exit.")

        while running:
            frame = picam2.capture_array()
            if frame is None:
                logger.warning("Captured empty frame, skipping.")
                continue

            processed_frame = process_frame(frame)
            if processed_frame is None:
                continue

            cv2.imshow("Output Image", processed_frame)

            key = cv2.waitKey(1) & 0xFF
            if key == 10:
                logger.info("Enter key pressed, exiting...")
                break

    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received.")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        logger.info("Cleaning up resources...")
        if picam2 is not None:
            try:
                picam2.stop()
                logger.info("Camera stopped.")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
        cv2.destroyAllWindows()
        if gpio_device is not None:
            try:
                gpio_device.off()
                gpio_device.close()
                logger.info("GPIO pin released.")
            except Exception as e:
                logger.error(f"Error releasing GPIO: {e}")
        logger.info("Cleanup complete.")

if __name__ == "__main__":
    main()

