import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# BCM pin definitions
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05  # seconds

# Global references for cleanup
inputs = []
outputs = []
running = True


def cleanup():
    """Release all GPIO resources cleanly."""
    global inputs, outputs
    for dev in list(outputs):
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
    for dev in list(inputs):
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
    inputs.clear()
    outputs.clear()


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def main():
    global inputs, outputs, running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize input pins with internal pull-up resistors (active-low)
    for pin in INPUT_PINS:
        try:
            dev = Button(pin, pull_up=True, bounce_time=0.02)
            inputs.append(dev)
        except GPIOZeroError as e:
            print(f"Error: Failed to initialize input GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)
        except Exception as e:
            print(f"Error: Unexpected failure initializing input GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    # Initialize output pins, starting LOW
    for pin in OUTPUT_PINS:
        try:
            dev = OutputDevice(pin, active_high=True, initial_value=False)
            outputs.append(dev)
        except GPIOZeroError as e:
            print(f"Error: Failed to initialize output GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)
        except Exception as e:
            print(f"Error: Unexpected failure initializing output GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    print("GPIO initialized. Polling every 0.05 s. Press Ctrl-C to exit.")

    output_state = False

    try:
        while running:
            for idx, input_dev in enumerate(inputs):
                try:
                    if input_dev.is_active:  # True when pin is LOW (active-low)
                        if idx == 0:
                            outputs[0].on()   # GPIO 23 HIGH
                        elif idx == 1:
                            outputs[0].off()  # GPIO 23 LOW
                        elif idx == 2:
                            output_state = not output_state
                            outputs[1].value = output_state
                except DeviceClosed:
                    print("Error: Input device closed unexpectedly.", file=sys.stderr)
                    break
                except GPIOZeroError as e:
                    print(f"Error: GPIO read failed on pin {INPUT_PINS[idx]}: {e}", file=sys.stderr)
                    break
                except Exception as e:
                    print(f"Error: Unexpected failure reading pin {INPUT_PINS[idx]}: {e}", file=sys.stderr)
                    break

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

