import os
import time
import datetime
import threading
import signal
import socketserver
import http.server
import io
import logging
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SurveillanceSystem:
    def __init__(self, record_dir='recordings', max_disk_gb=1.0, pre_record_seconds=5, post_record_seconds=10,
                 motion_threshold=20, min_motion_vectors=10, camera_resolution=(640, 480), camera_framerate=15):
        self.record_dir = record_dir
        self.max_disk_gb = max_disk_gb
        self.pre_record_seconds = pre_record_seconds
        self.post_record_seconds = post_record_seconds
        self.motion_threshold = motion_threshold
        self.min_motion_vectors = min_motion_vectors
        self.camera_resolution = camera_resolution
        self.camera_framerate = camera_framerate
        self.picam2 = None
        self.encoder = None
        self.output = None
        self.running = True
        self.motion_detected = False
        self.last_frame = None
        self.last_motion_time = 0
        self.lock = threading.Lock()
        self.httpd = None
        self.frame_buffer = []
        self.frame_buffer_lock = threading.Lock()
        self.frame_buffer_index = 0
        self.frame_buffer_size = 0
        self.frame_buffer_capacity = 100

    def start_camera(self):
        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_video_configuration(
                main={"size": self.camera_resolution, "format": "RGB888"},
                controls={"FrameRate": self.camera_framerate}
            )
            self.picam2.configure(config)
            self.picam2.start()
            logging.info("Camera started successfully.")
        except Exception as e:
            logging.error(f"Failed to start camera: {e}")
            raise

    def start_encoder(self):
        try:
            self.encoder = H264Encoder(bitrate=10000000)
            self.output = FileOutput()
            self.encoder.output = self.output
            logging.info("H.264 encoder initialized.")
        except Exception as e:
            logging.error(f"Failed to initialize encoder: {e}")
            raise

    def start_httpd(self):
        try:
            self.httpd = socketserver.TCPServer(("", 8000), HTTPHandler)
            self.httpd.allow_reuse_address = True
            self.httpd.daemon_threads = True
            self.httpd.server_class.address_family = os.environ.get('SERVER_ADDR_FAMILY', '0.0.0.0')
            self.httpd.timeout = 1.0
            self.httpd.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.httpd.socket.settimeout(1.0)
            httpd_thread = threading.Thread(target=self.httpd.serve_forever)
            httpd_thread.daemon = True
            httpd_thread.start()
            logging.info("HTTP server started on port 8000.")
        except Exception as e:
            logging.error(f"Failed to start HTTP server: {e}")
            raise

    def stop_httpd(self):
        if self.httpd:
            self.httpd.shutdown()
            self.httpd.server_close()
            logging.info("HTTP server stopped.")

    def manage_disk_space(self):
        try:
            self.delete_oldest_files()
        except Exception as e:
            logging.error(f"Error managing disk space: {e}")

    def delete_oldest_files(self):
        try:
            record_dir = self.record_dir
            if not os.path.exists(record_dir):
                return

            files = []
            total_size = 0
            for root, dirs, filenames in os.walk(record_dir):
                for f in filenames:
                    fp = os.path.join(root, f)
                    try:
                        files.append((os.path.getmtime(fp), os.path.getsize(fp), fp))
                        total_size += os.path.getsize(fp)
                    except OSError as e:
                        logging.warning(f"Error accessing file {fp}: {e}")

            files.sort()

            max_size = self.max_disk_gb * 1024 * 1024 * 1024
            while total_size > max_size and files:
                age, size, fp = files.pop(0)
                try:
                    os.remove(fp)
                    total_size -= size
                    logging.info(f"Deleted oldest file: {fp}")
                except OSError as e:
                    logging.error(f"Error deleting file {fp}: {e}")
        except Exception as e:
            logging.error(f"Error deleting oldest files: {e}")

    def detect_motion(self):
        try:
            frame = self.picam2.capture_array()
            if frame is None:
                return

            with self.lock:
                if self.last_frame is None:
                    self.last_frame = frame
                    return

            frame_delta = np.abs(frame.astype(np.int16) - self.last_frame.astype(np.int16))
            diff = np.sum(frame_delta)
            self.last_frame = frame

            if diff > self.motion_threshold:
                self.motion_detected = True
                self.last_motion_time = time.time()
                logging.info(f"Motion detected (diff: {diff})")
            else:
                self.motion_detected = False

        except Exception as e:
            logging.error(f"Error detecting motion: {e}")

    def record_video(self):
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
