import cv2
import pyzbar.pyzbar as pyzbar
import argparse
import time
import datetime
import logging
import threading
import queue
import os
import configparser
import signal
import sys

# Global flag for graceful shutdown
shutdown_flag = threading.Event()

def signal_handler(sig, frame):
    logging.info("Shutdown signal received. Cleaning up...")
    shutdown_flag.set()

def load_config(config_file):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        logging.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    return config

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def initialize_camera(camera_id, device_index):
    try:
        camera = cv2.VideoCapture(device_index)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera at device index {device_index}")
        logging.info(f"Camera {camera_id} initialized successfully at device index {device_index}")
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera {camera_id}: {e}")
        return None

def capture_frame(camera, frame_queue, camera_id):
    while not shutdown_flag.is_set():
        try:
            ret, frame = camera.read()
            if not ret:
                logging.error(f"Failed to capture frame from camera {camera_id}")
                break
            frame_queue.put((camera_id, frame))
        except Exception as e:
            logging.error(f"Error capturing frame from camera {camera_id}: {e}")
            break

def decode_qr_code(frame, camera_id):
    try:
        decoded_objects = pyzbar.decode(frame)
        for obj in decoded_objects:
            qr_data = obj.data.decode("utf-8")
            logging.info(f"QR Code detected by camera {camera_id}: {qr_data}")
            return qr_data
    except Exception as e:
        logging.error(f"Error decoding QR code from camera {camera_id}: {e}")
    return None

def process_frame(frame, camera_id, frame_buffer, motion_threshold, redundancy_time_window):
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (5, 5), 0)

        if frame_buffer.empty():
            frame_buffer.append(gray)
            return None

        frame_buffer.append(gray)
        diff = cv2.absdiff(gray, frame_buffer[-2])
        thresh = cv2.threshold(diff, motion_threshold, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        for contour in contours:
            if cv2.contourArea(contour) < 500:
                continue
            motion_detected = True
            break
        else:
            motion_detected = False

        if motion_detected:
            qr_data = decode_qr_code(frame, camera_id)
            if qr_data:
                return qr_data
        return None
    except Exception as e:
        logging.error(f"Error processing frame from camera {camera_id}: {e}")
        return None

def log_qr_code(qr_data, camera_id):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_message = f"{timestamp} - Camera {camera_id} - QR Code: {qr_data}\n"
    try:
        with open("inventory.log", "a") as log_file:
            log_file.write(log_message)
        logging.info(f"QR code logged: {qr_data} from camera {camera_id}")
    except Exception as e:
        logging.error(f"Error writing to inventory.log: {e}")
        try:
            with open("backup_inventory.log", "a") as backup_log_file:
                backup_log_file.write(log_message)
            logging.info("QR code logged to backup_inventory.log")
        except Exception as backup_e:
            logging.error(f"Error writing to backup_inventory.log: {backup_e}")

def simulate_cloud_upload(log_file):
    try:
        with open(log_file, "r") as f:
            content = f.read()
        print(f"Simulating cloud upload: {content}")
        with open(log_file, "w") as f:
            f.write("")
        logging.info("Simulated cloud upload completed.")
    except Exception as e:
        logging.error(f"Error simulating cloud upload: {e}")

def main():
    parser = argparse.ArgumentParser(description="QR Code Inventory System")
    parser.add_argument("--config", default="config.ini", help="Path to the configuration file")
    args = parser.parse_args()

    config = load_config(args.config)
    setup_logging(config.get("DEFAULT", "log_file", fallback="inventory.log"))

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera_ids = [1, 2]
    camera_devices = [0, 2]
    frame_buffers = [queue.SimpleQueue() for _ in camera_ids]

    cameras = []
    for i, camera_id in enumerate(camera_ids):
        camera = initialize_camera(camera_id, camera_devices[i])
        if camera is None:
            logging.error(f"Failed to initialize camera {camera_id}. Exiting.")
            for cam in cameras:
                cam.release()
            sys.exit(1)
        cameras.append(camera)

    capture_threads = []
    for i, camera in enumerate(cameras):
        thread = threading.Thread(target=capture_frame, args=(camera, frame_buffers[i], i+1))
        thread.daemon = True
        capture_threads.append(thread)
        thread.start()

    last_qr_code_scan_time = {i+1: 0.0 for i in range(len(camera_ids))}
    last_cloud_upload_time = time.time()
    cloud_upload_interval = config.getint("DEFAULT", "cloud_upload_interval", fallback=60)
    motion_threshold = config.getint("DEFAULT", "motion_threshold", fallback=25)
    redundancy_time_window = config.getfloat("DEFAULT", "redundancy_time_window", fallback=5.0)
    frame_buffer_size = config.getint("DEFAULT", "frame_buffer_size", fallback=30)
    reinit_delay = config.getfloat("DEFAULT", "reinit_delay", fallback=5.0)
    watchdog_timeout = config.getint("DEFAULT", "watchdog_timeout", fallback=30)

    last_qr_code_scan_time_check = time.time()

    try:
        while not shutdown_flag.is_set():
            for i, camera_id in enumerate(camera_ids):
                if shutdown_flag.is_set():
                    break
                try:
                    camera_id_int = i + 1
                    camera = cameras[i]
                    if not camera.isOpened():
                        logging.warning(f"Camera {camera_id} is not opened. Reinitializing...")
                        camera.release()
                        time.sleep(reinit_delay)
                        camera = initialize_camera(camera_id, camera_devices[i])
                        if camera is None:
                            logging.error(f"Failed to reinitialize camera {camera_id}. Exiting.")
                            break
                        cameras[i] = camera
                        continue

                    while not frame_buffers[i].empty():
                        camera_id_in_frame, frame = frame_buffers[i].get(timeout=1)
                        if camera_id_in_frame != camera_id:
                            continue

                        qr_data = process_frame(frame, camera_id, frame_buffers[i], motion_threshold, redundancy_time_window)
                        if qr_data:
                            current_time = time.time()
                            if current_time - last_qr_code_scan_time[camera_id] > redundancy_time_window:
                                log_qr_code(qr_data, camera_id)
                                last_qr_code_scan_time[camera_id] = current_time
                            else:
                                logging.info(f"Duplicate QR code detected: {qr_data} from camera {camera_id}")

                    if time.time() - last_qr_code_scan_time_check > watchdog_timeout:
                        logging.warning("Watchdog timeout triggered. Restarting program.")
                        os.execv(sys.executable, [sys.executable] + sys.argv)
                    last_qr_code_scan_time_check = time.time()

                    if time.time() - last_cloud_upload_time > cloud_upload_interval:
                        simulate_cloud_upload("inventory.log")
                        last_cloud_upload_time = time.time()

                except Exception as e:
                    logging.error(f"Error processing camera {camera_id}: {e}")
                    try:
                        cameras[i].release()
                        time.sleep(reinit_delay)
                        cameras[i] = initialize_camera(camera_id, camera_devices[i])
                    except Exception as reinit_e:
                        logging.error(f"Failed to reinitialize camera {camera_id}: {reinit_e}")

            time.sleep(0.1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources...")
        for camera in cameras:
            if camera is not None:
                camera.release()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

