import os
import signal
import sys
import threading
import configparser
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import CPUTemperature
except ImportError:
    CPUTemperature = None

CONFIG_FILE = 'config.txt'

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        print(f"Error: Configuration file '{config_file}' not found.")
        sys.exit(1)
    try:
        config.read(config_file)
    except Exception as e:
        print(f"Error reading configuration file: {e}")
        sys.exit(1)
    return config

def parse_resolution(resolution_str):
    try:
        width, height = map(int, resolution_str.split('x'))
        return width, height
    except ValueError:
        print(f"Error: Invalid resolution format '{resolution_str}'. Use WxH (e.g., 640x480).")
        sys.exit(1)

def parse_roi(roi_str):
    try:
        x1, y1, x2, y2 = map(int, roi_str.split(','))
        return x1, y1, x2, y2
    except ValueError:
        print(f"Error: Invalid ROI format '{roi_str}'. Use x1,y1,x2,y2 (e.g., 100,100,200,200).")
        sys.exit(1)

def detect_motion(frame1, frame2, roi_x1, roi_y1, roi_x2, roi_y2, motion_threshold):
    try:
        img1 = Image.fromarray(frame1)
        img2 = Image.fromarray(frame2)
        roi1 = img1.crop((roi_x1, roi_y1, roi_x2, roi_y2))
        roi2 = img2.crop((roi_x1, roi_y1, roi_x2, roi_y2))
        diff = Image.eval(roi1.convert('L'), lambda x: 0 if x == roi2.convert('L').getpixel((0, 0)) else 255)
        changed_pixels = sum(1 for pixel in diff.getdata() if pixel != 0)
        total_pixels = roi1.size[0] * roi1.size[1]
        if total_pixels == 0:
            return 0.0
        percentage = (changed_pixels / total_pixels) * 100
        return percentage
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return 0.0

def capture_snapshot(picam2, snapshot_dir):
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(snapshot_dir, f"motion_{timestamp}.jpg")
        picam2.capture_file(filename)
        print(f"Snapshot saved: {filename}")
    except Exception as e:
        print(f"Error capturing snapshot: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    config = load_config(CONFIG_FILE)

    try:
        resolution = parse_resolution(config['Camera']['resolution'])
        roi = parse_roi(config['Camera']['roi'])
        motion_threshold = float(config['Motion']['motion_threshold'])
        confirmation_delay = float(config['Motion']['confirmation_delay'])
        temperature_threshold = float(config['Temperature']['temperature_threshold'])
        snapshot_dir = config['General']['snapshot_dir']
        simulated_temperature = config['General'].getboolean('simulated_temperature')
    except KeyError as e:
        print(f"Error: Missing configuration parameter '{e}' in config.txt.")
        sys.exit(1)
    except ValueError as e:
        print(f"Error: Invalid configuration value: {e}")
        sys.exit(1)

    if Picamera2 is None:
        print("Error: picamera2 library not installed. Install with: pip install picamera2")
        sys.exit(1)

    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={"format": 'RGB888', "size": resolution}))
        picam2.start()
        time.sleep(2)
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

    cpu_temp = None
    if CPUTemperature is not None and not simulated_temperature:
        try:
            cpu_temp = CPUTemperature()
        except Exception as e:
            print(f"Warning: Could not initialize CPUTemperature: {e}. Using simulated temperature.")
            cpu_temp = None

    last_frame = None
    last_motion_time = None
    last_temp_alert_time = None

    try:
        while running:
            try:
                frame = picam2.capture_array()
            except Exception as e:
                print(f"Error capturing frame: {e}")
                time.sleep(0.1)
                continue

            if last_frame is not None:
                percentage = detect_motion(last_frame, frame, roi[0], roi[1], roi[2], roi[3], motion_threshold)
                if percentage > motion_threshold:
                    if last_motion_time is None or (time.time() - last_motion_time) > confirmation_delay:
                        print(f"Motion detected! Percentage: {percentage:.2f}%")
                        capture_snapshot(picam2, snapshot_dir)
                        last_motion_time = time.time()

            last_frame = frame

            if cpu_temp is not None:
                try:
                    temp = cpu_temp.temperature
                except Exception as e:
                    print(f"Error reading CPU temperature: {e}")
                    temp = None

            if temp is None and simulated_temperature:
                temp = 25.0

            if temp is not None and (last_temp_alert_time is None or (time.time() - last_temp_alert_time) > 60):
                if temp > temperature_threshold:
                    print(f"High temperature detected! Temperature: {temp:.2f}°C")
                    last_temp_alert_time = time.time()

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        try:
            picam2.stop()
        except Exception:
            pass
        print("Exiting program.")

if __name__ == "__main__":
    main()

