import cv2
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    global running

    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        print(f"Error: Failed to load Haar Cascade from {cascade_path}", file=sys.stderr)
        sys.exit(1)

    picam2 = None
    try:
        picam2 = Picamera2(camera_num=0)
        config = picam2.create_preview_configuration(
            main={"format": 'XRGB8888', "size": (640, 480)}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(1)  # warm-up

        while running:
            frame = picam2.capture_array()
            if frame is None:
                print("Warning: Empty frame captured, skipping...", file=sys.stderr)
                continue

            # XRGB8888 has 4 channels; convert to BGR for OpenCV display
            if frame.shape[2] == 4:
                bgr_frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)
            else:
                bgr_frame = frame

            gray = cv2.cvtColor(bgr_frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(
                gray, scaleFactor=1.1, minNeighbors=5
            )

            for (x, y, w, h) in faces:
                cv2.rectangle(bgr_frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                print('Face detected!')

            cv2.imshow('Real-time Face Detection', bgr_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

