import argparse
import datetime
import json
import logging
import signal
import sys
import threading
import time

import cv2
import face_recognition
import gpiozero
from picamera2 import Picamera2

MOTION_THRESHOLD = 500
CONFIDENCE_THRESHOLD = 0.6
ENCODINGS_FILE = "encodings.json"
DEFAULT_LOG_LEVEL = "INFO"

RELAY_PIN = 17


class DoorAccessSystem:
    def __init__(self, args):
        self.args = args
        self.logger = self._setup_logging()
        self.relay = None
        self.picam2 = None
        self.running = True
        self.last_trigger_time = 0.0
        self.lock = threading.Lock()

    def _setup_logging(self):
        level = getattr(logging, self.args.log_level.upper(), None)
        if not isinstance(level, int):
            raise ValueError(f"Invalid log level: {self.args.log_level}")
        logging.basicConfig(
            level=level,
            format="%(asctime)s - %(levelname)s - %(message)s",
        )
        return logging.getLogger(__name__)

    def _load_encodings(self):
        try:
            with open(ENCODINGS_FILE, "r") as f:
                return json.load(f)
        except FileNotFoundError:
            self.logger.warning(f"Encodings file '{ENCODINGS_FILE}' not found; starting empty.")
            return {}
        except json.JSONDecodeError as e:
            self.logger.error(f"Invalid JSON in '{ENCODINGS_FILE}': {e}")
            return {}

    def _save_encodings(self, encodings):
        try:
            with open(ENCODINGS_FILE, "w") as f:
                json.dump(encodings, f, indent=4)
        except OSError as e:
            self.logger.error(f"Failed to save encodings: {e}")

    def _init_camera(self):
        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_preview_configuration(
                main={"format": "XRGB8888", "size": (640, 480)}
            )
            self.picam2.configure(config)
            self.picam2.start()
            self.logger.info("Camera initialized at 640x480.")
        except Exception as e:
            self.logger.error(f"Camera initialization failed: {e}")
            raise

    def _init_relay(self):
        try:
            self.relay = gpiozero.OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
            self.logger.info(f"Relay initialized on GPIO {RELAY_PIN}.")
        except Exception as e:
            self.logger.error(f"Relay initialization failed: {e}")
            raise

    def _detect_motion(self, frame1, frame2):
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
        dilated = cv2.dilate(thresh, None, iterations=3)
        contours, _ = cv2.findContours(
            dilated, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
        )
        for c in contours:
            if cv2.contourArea(c) < MOTION_THRESHOLD:
                continue
            (x, y, w, h) = cv2.boundingRect(c)
            cv2.rectangle(frame1, (x, y), (x + w, y + h), (0, 255, 0), 2)
            return True
        return False

    def _recognize_faces(self, frame):
        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        boxes = face_recognition.face_locations(rgb)
        encodings = face_recognition.face_encodings(rgb, boxes)
        names = []
        for enc in encodings:
            matches = face_recognition.compare_faces(
                self.known_encodings, enc
            )
            name = "Unknown"
            if True in matches:
                matched_idxs = [i for (i, b) in enumerate(matches) if b]
                counts = {}
                for i in matched_idxs:
                    user_name = list(self.known_encodings.keys())[i]
                    counts[user_name] = counts.get(user_name, 0) + 1
                name = max(counts, key=counts.get)
            confidence = 1.0 - face_recognition.face_distance(
                self.known_encodings, enc
            )[0]
            names.append((name, confidence))
        return boxes, names

    def _activate_relay(self):
        now = time.time()
        with self.lock:
            if now - self.last_trigger_time < self.args.debounce_time:
                self.logger.info("Debounce active; skipping relay activation.")
                return
            self.last_trigger_time = now
        try:
            self.relay.on()
            self.logger.info(f"Relay ON for {self.args.door_open_duration}s.")
            time.sleep(self.args.door_open_duration)
            self.relay.off()
            self.logger.info("Relay OFF.")
        except Exception as e:
            self.logger.error(f"Relay control error: {e}")

    def _signal_handler(self, signum, frame):
        self.logger.info(f"Signal {signum} received; shutting down.")
        self.running = False

    def run(self):
        self.known_encodings = self._load_encodings()
        self._init_camera()
        self._init_relay()
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        prev_frame = None
        try:
            while self.running:
                try:
                    frame = self.picam2.capture_array()
                except Exception as e:
                    self.logger.error(f"Frame capture error: {e}")
                    time.sleep(0.1)
                    continue
                if prev_frame is not None:
                    if self._detect_motion(prev_frame, frame):
                        boxes, names = self._recognize_faces(frame)
                        for (top, right, bottom, left), name in zip(boxes, names):
                            cv2.rectangle(frame, (left, top), (right, bottom), (0, 255, 0), 2)
                            confidence = names[0][1]
                            self.logger.info(
                                f"Recognized {name} with confidence {confidence:.2f}"
                            )
                            if confidence > self.args.confidence_threshold:
                                self._activate_relay()
                prev_frame = frame
                time.sleep(0.1)
        except Exception as e:
            self.logger.error(f"Unexpected error: {e}")
        finally:
            self._cleanup()

    def _cleanup(self):
        if self.relay is not None:
            try:
                self.relay.off()
                self.relay.close()
            except Exception:
                pass
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception:
                pass
        self._save_encodings(self.known_encodings)
        self.logger.info("Cleanup complete.")


def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Facial Recognition Door Access System")
    parser.add_argument("--motion_threshold", type=int, default=MOTION_THRESHOLD, help="Motion detection pixel threshold")
    parser.add_argument("--confidence_threshold", type=float, default=CONFIDENCE_THRESHOLD, help="Facial recognition confidence threshold")
    parser.add_argument("--door_open_duration", type=int, default=5, help="Relay activation duration (seconds)")
    parser.add_argument("--debounce_time", type=int, default=2, help="Debounce time (seconds)")
    parser.add_argument("--log_level", type=str, default=DEFAULT_LOG_LEVEL, choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level")
    args = parser.parse_args()
    system = DoorAccessSystem(args)
    system.run()


if __name__ == "__main__":
    main()

