import asyncio
import logging
import signal
import threading
from typing import Callable, Optional

import cv2
import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Base class for WebSocket connections (stubbed for the exercise)."""
    def __init__(self):
        self._connections: set = set()
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            for conn in list(self._connections):
                try:
                    conn.send(data)
                except (OSError, BrokenPipeError):
                    self._connections.discard(conn)


class CameraFeed:
    """Streams video from the Raspberry Pi V2 camera via picamera2 and broadcasts JPEG frames to WebSocket clients."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if Picamera2 is None:
            raise RuntimeError("picamera2 library is not installed")
        if detect_motion_function is None:
            raise ValueError("detect_motion_function must not be None")

        self.detect_motion_function = detect_motion_function
        self.picam2: Optional[Picamera2] = None
        self.buffer: bytes = b""
        self.jpeg_data: Optional[bytes] = None
        self.prev_frame: Optional[np.ndarray] = None
        self.running = False
        self.loop: Optional[asyncio.AbstractEventLoop] = None
        self.lock = threading.Lock()
        self._stop_event = threading.Event()

    def start(self, loop: asyncio.AbstractEventLoop, websocket_handler: WebSocketHandler) -> None:
        if self.running:
            logger.warning("CameraFeed already started.")
            return

        self.loop = loop
        self.running = True
        self.websocket_handler = websocket_handler

        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                lores={"size": (640, 480), "format": "YUV420"},
                encode="lores",
            )
            self.picam2.configure(config)
            self.picam2.start()
            logger.info("Camera started successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            self.stop()
            raise

        self._stop_event.clear()
        self._capture_thread = threading.Thread(target=self._capture_loop, daemon=True)
        self._capture_thread.start()

    def _capture_loop(self) -> None:
        while not self._stop_event.is_set():
            try:
                frame = self.picam2.capture_array()
                if frame is None:
                    logger.warning("Received None frame from camera.")
                    continue

                with self.lock:
                    self.buffer += frame.tobytes()

                self._process_jpeg()
                self._detect_motion(frame)

                if self.websocket_handler.has_connections():
                    with self.lock:
                        if self.jpeg_data is not None:
                            try:
                                self.websocket_handler.broadcast(self.jpeg_data)
                            except Exception as e:
                                logger.error(f"Broadcast error: {e}")
                            finally:
                                self.jpeg_data = None
            except Exception as e:
                logger.error(f"Error in capture loop: {e}")
                if not self._stop_event.is_set():
                    asyncio.run_on_executor(self.loop, self.stop)
                    break

    def _process_jpeg(self) -> None:
        with self.lock:
            if "\xff\xd8" not in self.buffer:
                return

            idx = self.buffer.find("\xff\xd9")
            if idx == -1:
                return

            frame_data = self.buffer[:idx + 2]
            self.buffer = self.buffer[idx + 2:]

            if frame_data.startswith(b"\xff\xd8"):
                self.jpeg_data = frame_data

    def _detect_motion(self, frame: np.ndarray) -> None:
        if self.prev_frame is not None:
            try:
                self.detect_motion_function(self.prev_frame, frame)
            except Exception as e:
                logger.error(f"Motion detection error: {e}")
        self.prev_frame = frame

    def stop(self) -> None:
        if not self.running:
            return
        self.running = False
        self._stop_event.set()
        if self._capture_thread and self._capture_thread.is_alive():
            self._capture_thread.join(timeout=5)
        if self.picam2:
            try:
                self.picam2.stop()
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
            finally:
                self.picam2 = None
        logger.info("Camera stopped.")


def _signal_handler(signum, frame, camera_feed: Optional[CameraFeed]):
    logger.info(f"Signal {signum} received, shutting down.")
    if camera_feed:
        camera_feed.stop()


def main():
    if Picamera2 is None:
        logger.error("picamera2 library is not installed. Install with: pip install picamera2")
        return

    def motion_callback(prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
        logger.info("Motion detected!")

    camera_feed = CameraFeed(detect_motion_function=motion_callback)
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)

    class _StubWebSocketHandler(WebSocketHandler):
        def __init__(self):
            super().__init__()
            self._connections.add(None)

    handler = _StubWebSocketHandler()

    def _shutdown(signum, frame):
        _signal_handler(signum, frame, camera_feed)

    signal.signal(signal.SIGINT, lambda s, f: _shutdown(s, f))
    signal.signal(signal.SIGTERM, lambda s, f: _shutdown(s, f))

    try:
        camera_feed.start(loop, handler)
        loop.run_forever()
    except KeyboardInterrupt:
        pass
    finally:
        camera_feed.stop()
        loop.close()


if __name__ == "__main__":
    main()

