#!/usr/bin/env python3
"""
Beehive Thermal Monitor

Monitors a beehive using an AMG88XX thermal camera, detects motion,
captures images with picamera2, and logs events.

Hardware:
  - Raspberry Pi (any model with I2C, e.g. Pi 4 Model B)
  - AMG88XX thermal camera at I2C address 0x69
  - Raspberry Pi Camera Module (optional)

Dependencies:
  pip install smbus2 adafruit-circuitpython-amg88xx picamera2 matplotlib
"""

import json
import logging
import logging.handlers
import os
import signal
import sys
import threading
import time
from pathlib import Path

import numpy as np
import matplotlib.pyplot as plt

try:
    from smbus2 import SMBus
except ImportError:
    SMBus = None

try:
    import board
    import adafruit_amg88xx
except ImportError:
    board = None
    adafruit_amg88xx = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None


DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False,
}


class ThermalMonitor:
    def __init__(self, config_path: str):
        self.config = self._load_config(config_path)
        self.thermal_data = np.zeros((300, 8, 8), dtype=np.float32)
        self.data_index = 0
        self.running = True
        self.thermal_camera = None
        self.picam2 = None
        self.logger = None
        self.motion_detected = False
        self.motion_detection_thread = None
        self.sampling_thread = None
        self.sampling_rate = self.config["sampling_rate"]
        self.motion_threshold = self.config["motion_detection_threshold"]
        self.log_file_path = self.config["logging_file_path"]
        self.log_max_size = self.config["log_max_size"]
        self.enable_camera = self.config["enable_camera"]
        self.last_frame = None
        self._lock = threading.Lock()

    def _load_config(self, config_path: str) -> dict:
        try:
            with open(config_path, "r") as f:
                config = json.load(f)
            required = ["sampling_rate", "motion_detection_threshold",
                        "logging_file_path", "log_max_size", "enable_camera"]
            missing = [k for k in required if k not in config]
            if missing:
                raise ValueError(f"Missing config keys: {missing}")
            return config
        except FileNotFoundError:
            logging.warning(f"Config file not found: {config_path}. Using defaults.")
            return dict(DEFAULT_CONFIG)
        except (json.JSONDecodeError, ValueError) as e:
            logging.error(f"Config error: {e}. Using defaults.")
            return dict(DEFAULT_CONFIG)

    def _setup_logging(self) -> logging.Logger:
        logger = logging.getLogger("ThermalMonitor")
        logger.setLevel(logging.INFO)
        handler = logging.handlers.RotatingFileHandler(
            self.log_file_path, maxBytes=self.log_max_size, backupCount=1
        )
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def _init_thermal_camera(self) -> bool:
        if board is None or adafruit_amg88xx is None:
            self.logger.error("adafruit-circuitpython-amg88xx not installed.")
            return False
        try:
            i2c = SMBus(1)
            self.thermal_camera = adafruit_amg88xx.AMG88XX(i2c, addr=0x69)
            self.logger.info("AMG88XX initialized at address 0x69.")
            return True
        except Exception as e:
            self.logger.error(f"Failed to initialize AMG88XX: {e}")
            return False

    def _init_camera(self) -> bool:
        if Picamera2 is None:
            self.logger.warning("picamera2 not installed; camera disabled.")
            return False
        try:
            self.picam2 = Picamera2()
