    import adafruit_amg88xx
except ImportError:
    board = None
    adafruit_amg88xx = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None


DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False,
}


class ThermalMonitor:
    def __init__(self, config_path: str):
        self.config = self._load_config(config_path)
        self.thermal_data = np.zeros((300, 8, 8), dtype=np.float32)
        self.data_index = 0
        self.running = True
        self.thermal_camera = None
        self.picam2 = None
        self.logger = None
        self.motion_detected = False
        self.motion_detection_thread = None
        self.sampling_thread = None
        self.sampling_rate = self.config["sampling_rate"]
        self.motion_threshold = self.config["motion_detection_threshold"]
        self.log_file_path = self.config["logging_file_path"]
        self.log_max_size = self.config["log_max_size"]
        self.enable_camera = self.config["enable_camera"]
        self.last_frame = None
        self._lock = threading.Lock()

    def _load_config(self, config_path: str) -> dict:
        try:
            with open(config_path, "r") as f:
                config = json.load(f)
            required = ["sampling_rate", "motion_detection_threshold",
                        "logging_file_path", "log_max_size", "enable_camera"]
            missing = [k for k in required if k not in config]
            if missing:
                raise ValueError(f"Missing config keys: {missing}")
            return config
        except FileNotFoundError:
            logging.warning(f"Config file not found: {config_path}. Using defaults.")
            return dict(DEFAULT_CONFIG)
        except (json.JSONDecodeError, ValueError) as e:
