import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np

try:
    import websocket
except ImportError:
    websocket = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Buffers complete JPEG frames from picamera2 and broadcasts them over WebSocket.

    Designed to be used with picamera2's capture_buffer or a custom output that
    feeds raw JPEG bytes into the write() method.
    """

    def __init__(self, websocket_handler: "WebSocketHandler"):
        if websocket_handler is None:
            raise TypeError("websocket_handler must not be None")
        if not hasattr(websocket_handler, "has_connections") or not callable(
            getattr(websocket_handler, "has_connections")
        ):
            raise TypeError("websocket_handler must have a callable has_connections()")
        if not hasattr(websocket_handler, "broadcast") or not callable(
            getattr(websocket_handler, "broadcast")
        ):
            raise TypeError("websocket_handler must have a callable broadcast(data)")

        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self._closed = False

    def write(self, data: bytes) -> int:
        """
        Called by picamera2 for each chunk of JPEG data.
        Detects new-frame boundaries (\xff\xd8) and broadcasts complete frames.
        """
        if self._closed:
            return 0

        try:
            with self.lock:
                self.buffer.write(data)

                # Detect new-frame boundary: look for \xff\xd8 in the last few bytes
                if data.endswith(b"\xff\xd8"):
                    frame_data = self.buffer.getvalue()
                    if frame_data:
                        self.buffer.seek(0)
                        self.buffer.truncate(0)
                        self._send_frame(frame_data)
        except Exception as e:
            logger.error("Error in CameraStreamBuffer.write: %s", e)
            return 0

        return len(data)

    def _send_frame(self, frame_data: bytes) -> None:
        """Broadcast a complete frame to all WebSocket connections."""
        if not self.websocket_handler.has_connections():
            return
        try:
            self.websocket_handler.broadcast(frame_data)
        except Exception as e:
            logger.error("Error broadcasting frame: %s", e)

    def flush(self) -> None:
        """Emit any remaining buffered frame on shutdown."""
        with self.lock:
            if self.buffer.tell() > 0:
                frame_data = self.buffer.getvalue()
                if frame_data:
                    self._send_frame(frame_data)
                self.buffer.seek(0)
                self.buffer.truncate(0)

    def close(self) -> None:
        """Mark the buffer as closed so write() returns early."""
        self._closed = True


class MotionDetectionBuffer:
    """
    Buffers complete JPEG frames from picamera2 and runs motion detection.

    Designed to be used with picamera2's capture_buffer or a custom output that
    feeds raw JPEG bytes into the write() method.
    """

    def __init__(
        self,
        detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
    ):
        if detect_motion_function is None:
            raise TypeError("detect_motion_function must not be None")
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")

        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self._closed = False

    def write(self, data: bytes) -> int:
        """
        Called by picamera2 for each chunk of JPEG data.
        Detects new-frame boundaries (\xff\xd8) and runs motion detection.
        """
        if self._closed:
            return 0

        try:
            with self.lock:
                self.buffer.write(data)

                # Detect new-frame boundary: look for \xff\xd8 in the last few bytes
                if data.endswith(b"\xff\xd8"):
                    frame_data = self.buffer.getvalue()
                    if frame_data:
                        self.buffer.seek(0)
                        self.buffer.truncate(0)
                        self._process_frame(frame_data)
        except Exception as e:
            logger.error("Error in MotionDetectionBuffer.write: %s", e)
            return 0

        return len(data)

    def _process_frame(self, frame_data: bytes) -> None:
        """Decode a complete JPEG frame and run motion detection."""
        try:
            frame = self._convert_to_opencv_frame(frame_data)
            if frame is None:
                return

            self.previous_frame = self.current_frame
            self.current_frame = frame

            if self.previous_frame is not None:
                try:
                    self.detect_motion_function(self.previous_frame, self.current_frame)
                except Exception as e:
                    logger.error("Error in motion detection function: %s", e)
        except Exception as e:
            logger.error("Error processing frame: %s", e)

    def _convert_to_opencv_frame(self, frame_data: bytes) -> Optional[np.ndarray]:
        """Decode JPEG bytes into an OpenCV BGR image."""
        try:
            data = np.frombuffer(frame_data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if frame is None:
                logger.error("cv2.imdecode returned None for frame data")
                return None
            return frame
        except Exception as e:
            logger.error("Error converting frame data: %s", e)
            return None

    def flush(self) -> None:
        """No-op: motion detection is stateless between frames."""
        pass

    def close(self) -> None:
        """Mark the buffer as closed so write() returns early."""
        self._closed = True


class WebSocketHandler:
    """Stub WebSocket handler exposing has_connections() and broadcast(data)."""

    def __init__(self):
        self._connections: list = []
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            for conn in self._connections:
                try:
                    conn.send(data)
                except Exception as e:
                    logger.error("Error sending to WebSocket connection: %s", e)

    def add_connection(self, connection) -> None:
        with self._lock:
            self._connections.append(connection)

    def remove_connection(self, connection) -> None:
        with self._lock:
            if connection in self._connections:
                self._connections.remove(connection)


def _signal_handler(signum, frame, camera: Optional[Picamera2] = None):
    """Handle SIGINT/SIGTERM: stop camera and flush buffers."""
    logger.info("Received signal %s, shutting down...", signum)
    if camera is not None:
        try:
            camera.stop()
        except Exception as e:
            logger.error("Error stopping camera: %s", e)
    logger.info("Shutdown complete.")


def main() -> None:
    """Minimal demo: start camera, stream JPEGs, run motion detection."""
    logging.basicConfig(level=logging.INFO)

    if Picamera2 is None:
        logger.error("picamera2 library not available")
        return

    camera = Picamera2()
    stream_buffer = CameraStreamBuffer(WebSocketHandler())
    motion_buffer = MotionDetectionBuffer(
        lambda prev, curr: logger.info("Motion detected")
    )

    def _detect_motion(prev: np.ndarray, curr: np.ndarray) -> None:
        logger.info("Motion detected")

    try:
        camera.configure(
            camera.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                controls={"FrameRate": 10.0},
            )
        )
        camera.start()
        logger.info("Camera started: 640x480 @ 10 fps")

        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, camera))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, camera))

        while True:
            frame = camera.capture_array()
            if frame is None:
                logger.warning("capture_array returned None")
                time.sleep(0.01)
                continue

            # picamera2 returns RGB; convert to BGR for OpenCV consistency
            bgr_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
            ret, jpeg = cv2.imencode(".jpg", bgr_frame)
            if not ret:
                logger.error("Failed to encode frame to JPEG")
                continue

            stream_buffer.write(jpeg.tobytes())
            motion_buffer.write(jpeg.tobytes())

            time.sleep(0.033)  # ~30 fps loop

    except Exception as e:
        logger.error("Fatal error in main loop: %s", e)
    finally:
        stream_buffer.flush()
        motion_buffer.flush()
        try:
            camera.stop()
        except Exception as e:
            logger.error("Error stopping camera during cleanup: %s", e)
        logger.info("Cleanup complete.")


if __name__ == "__main__":
    main()

