                    logger.error("Error in motion detection function: %s", e)
        except Exception as e:
            logger.error("Error processing frame: %s", e)

    def _convert_to_opencv_frame(self, frame_data: bytes) -> Optional[np.ndarray]:
        """Decode JPEG bytes into an OpenCV BGR image."""
        try:
            data = np.frombuffer(frame_data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if frame is None:
                logger.error("cv2.imdecode returned None for frame data")
                return None
            return frame
        except Exception as e:
            logger.error("Error converting frame data: %s", e)
            return None

    def flush(self) -> None:
        """No-op: motion detection is stateless between frames."""
        pass

    def close(self) -> None:
        """Mark the buffer as closed so write() returns early."""
        self._closed = True


class WebSocketHandler:
    """Stub WebSocket handler exposing has_connections() and broadcast(data)."""

    def __init__(self):
        self._connections: list = []
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            for conn in self._connections:
                try:
                    conn.send(data)
                except Exception as e:
                    logger.error("Error sending to WebSocket connection: %s", e)

    def add_connection(self, connection) -> None:
        with self._lock:
            self._connections.append(connection)

    def remove_connection(self, connection) -> None:
        with self._lock:
            if connection in self._connections:
                self._connections.remove(connection)


def _signal_handler(signum, frame, camera: Optional[Picamera2] = None):
    """Handle SIGINT/SIGTERM: stop camera and flush buffers."""
    logger.info("Received signal %s, shutting down...", signum)
    if camera is not None:
        try:
            camera.stop()
        except Exception as e:
            logger.error("Error stopping camera: %s", e)
    logger.info("Shutdown complete.")


def main() -> None:
    """Minimal demo: start camera, stream JPEGs, run motion detection."""
    logging.basicConfig(level=logging.INFO)

    if Picamera2 is None:
        logger.error("picamera2 library not available")
        return

    camera = Picamera2()
    stream_buffer = CameraStreamBuffer(WebSocketHandler())
    motion_buffer = MotionDetectionBuffer(
        lambda prev, curr: logger.info("Motion detected")
    )

    def _detect_motion(prev: np.ndarray, curr: np.ndarray) -> None:
        logger.info("Motion detected")

    try:
        camera.configure(
            camera.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                controls={"FrameRate": 10.0},
            )
        )
        camera.start()
        logger.info("Camera started: 640x480 @ 10 fps")

        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, camera))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, camera))

        while True:
            frame = camera.capture_array()
            if frame is None:
                logger.warning("capture_array returned None")
                time.sleep(0.01)
                continue

            # picamera2 returns RGB; convert to BGR for OpenCV consistency
            bgr_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
            ret, jpeg = cv2.imencode(".jpg", bgr_frame)
            if not ret:
                logger.error("Failed to encode frame to JPEG")
                continue

            stream_buffer.write(jpeg.tobytes())
            motion_buffer.write(jpeg.tobytes())

            time.sleep(0.033)  # ~30 fps loop

    except Exception as e:
        logger.error("Fatal error in main loop: %s", e)
    finally:
        stream_buffer.flush()
        motion_buffer.flush()
        try:
            camera.stop()
        except Exception as e:
            logger.error("Error stopping camera during cleanup: %s", e)
        logger.info("Cleanup complete.")


if __name__ == "__main__":
    main()

