import os
import sys
import signal
import threading
import time
import logging
import cv2
import numpy as np
from twilio.rest import Client
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output
from flask import Flask, Response, render_template_string

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

TWILIO_ACCOUNT_SID = os.environ.get('TWILIO_ACCOUNT_SID')
TWILIO_AUTH_TOKEN = os.environ.get('TWILIO_AUTH_TOKEN')
TWILIO_PHONE_NUMBER = os.environ.get('TWILIO_PHONE_NUMBER')
RECIPIENT_PHONE_NUMBER = os.environ.get('RECIPIENT_PHONE_NUMBER')
FACE_CASCADE_PATH = '/home/pi/Downloads/IoT-and-Computing-Lab-main/haarcascade_frontalface_default.xml'

HTML_PAGE = """
<!DOCTYPE html>
<html>
<head><title>Raspberry Pi Security Camera</title></head>
<body>
    <h1>Raspberry Pi Security Camera</h1>
    <img src="/stream.mjpg" style="width:640px; height:480px;">
</body>
</html>
"""

app = Flask(__name__)

output = None
picam2 = None
twilio_client = None
shutdown_event = threading.Event()


def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down...")
    shutdown_event.set()


def initialize_twilio():
    global twilio_client
    if not all([TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_PHONE_NUMBER, RECIPIENT_PHONE_NUMBER]):
        logging.error("Missing Twilio environment variables. Exiting.")
        return False
    try:
        twilio_client = Client(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
        logging.info("Twilio client initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize Twilio client: {e}")
        return False


def send_sms():
    if not twilio_client:
        logging.error("Twilio client not initialized. Cannot send SMS.")
        return
    try:
        message = twilio_client.messages.create(
            to=RECIPIENT_PHONE_NUMBER,
            from_=TWILIO_PHONE_NUMBER,
            body="Motion and face detected!"
        )
        logging.info(f"SMS sent successfully. SID: {message.sid}")
    except Exception as e:
        logging.error(f"Failed to send SMS: {e}")


def detect_motion_and_faces(frame):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    gray = cv2.GaussianBlur(gray, (21, 21), 0)
    motion_detected = False
    faces = []

    if os.path.exists(FACE_CASCADE_PATH):
        face_cascade = cv2.CascadeClassifier(FACE_CASCADE_PATH)
        if face_cascade.empty():
            logging.error("Failed to load face cascade classifier.")
            face_cascade = None

        if face_cascade is not None:
            faces = face_cascade.detectMultiScale(
                gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
            )
            faces = [(x, y, w, h) for (x, y, w, h) in faces if w * h > 10000]

        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

    if len(faces) > 0:
        motion_detected = True
        logging.info("Motion and face detected!")
        send_sms()

    return frame, motion_detected


def stream_processing_thread():
    global output, picam2
    try:
        output = Output()
        picam2 = Picamera2()
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "BGR888"},
            controls={"FrameRate": 15}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera started successfully.")

        encoder = MJPEGEncoder()
        encoder.output = output
        picam2.start_recording(encoder, quality=80)

        while not shutdown_event.is_set():
            frame = picam2.capture_array()
            if frame is None:
                continue
            frame = cv2.flip(frame, -1)
            processed_frame, motion_detected = detect_motion_and_faces(frame)
            if motion_detected:
                logging.info("Motion detected!")
            output.write(processed_frame)
            time.sleep(1.0 / 15.0)

    except Exception as e:
        logging.error(f"Error in stream processing thread: {e}")
    finally:
        logging.info("Stopping stream processing thread.")
        if picam2:
            try:
                picam2.stop_recording()
            except Exception:
                pass
            try:
                picam2.stop()
            except Exception:
                pass
        if output:
            try:
                output.close()
            except Exception:
                pass


def generate():
    global output
    while not shutdown_event.is_set():
        try:
            if output is None:
                time.sleep(0.1)
                continue
            frame = output.read()
            if frame is None:
                continue
            if frame.startswith(b'\xff\xd8'):
                pass
            else:
                output.write(frame)
            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
        except Exception as e:
            logging.error(f"Error generating stream: {e}")
            time.sleep(0.1)
    yield b"end"


@app.route("/")
def index():
    return render_template_string(HTML_PAGE)


@app.route("/stream.mjpg")
def stream():
    return Response(generate(), mimetype="multipart/x-mixed-replace; boundary=frame")


def main():
    global output, picam2
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not os.path.exists(FACE_CASCADE_PATH):
        logging.error(f"Haar cascade file not found at {FACE_CASCADE_PATH}")
        sys.exit(1)

    if not initialize_twilio():
        sys.exit(1)

    stream_thread = threading.Thread(target=stream_processing_thread, daemon=True)
    stream_thread.start()

    try:
        app.run(host='0.0.0.0', port=8000, debug=False, threaded=True)
    except Exception as e:
        logging.error(f"Error running Flask app: {e}")
    finally:
        shutdown_event.set()
        if picam2:
            try:
                picam2.stop()
            except Exception:
                pass
        if output:
            try:
                output.close()
            except Exception:
                pass
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

