import sys
import cv2
import config
import face
import gpiozero

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_door = None
_mixer = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _door, _mixer
    if _door is not None:
        try:
            _door.close()
        except Exception:
            pass
        _door = None
    if _mixer is not None:
        try:
            _mixer.quit()
        except Exception:
            pass
        _mixer = None


# ---------------------------------------------------------------------------
# Initialization
# ---------------------------------------------------------------------------
try:
    pygame.mixer.init(48000)
    _mixer = pygame.mixer
except pygame.error as exc:
    print(f"Error initializing pygame mixer: {exc}", file=sys.stderr)
    _mixer = None

try:
    sound_welcome = _mixer.Sound("welcome.wav")
    sound_wait = _mixer.Sound("wait.wav")
    sound_later = _mixer.Sound("later.wav")
except (OSError, pygame.error) as exc:
    print(f"Error loading sound files: {exc}", file=sys.stderr)
    sound_welcome = sound_wait = sound_later = None

try:
    model = cv2.face.EigenFaceRecognizer_create()
    model.read(config.TRAINING_FILE)
except cv2.error as exc:
    print(f"Error loading face recognition model: {exc}", file=sys.stderr)
    model = None

try:
    from picamera2 import Picamera2
    _picam2 = Picamera2()
    _picam2.configure(_picam2.create_preview_configuration(
        main={"size": (640, 480), "format": "BGR888"}))
    _picam2.start()
except Exception as exc:
    print(f"Error initializing camera: {exc}", file=sys.stderr)
    _picam2 = None

try:
    _door = gpiozero.Button(18, pull_up=True, bounce_time=0.05)
except Exception as exc:
    print(f"Error initializing door lock GPIO 18: {exc}", file=sys.stderr)
    _door = None


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def play_sound(sound):
    if sound is None:
        return
    try:
        sound.play()
    except pygame.error as exc:
        print(f"Error playing sound: {exc}", file=sys.stderr)


def recognize_face():
    """Capture a frame, run EigenFace recognition, and return (label, confidence)."""
    if _picam2 is None:
        return None, None
    try:
        frame = _picam2.capture_array()
    except Exception as exc:
        print(f"Error capturing frame: {exc}", file=sys.stderr)
        return None, None
    if frame is None or frame.size == 0:
        return None, None
    try:
        label, confidence = model.predict(frame)
    except cv2.error as exc:
        print(f"Error during face recognition: {exc}", file=sys.stderr)
        return None, None
    return label, confidence


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        while _running:
            if _door is not None and _door.is_button_up:
                label, confidence = recognize_face()
                if label is not None and confidence is not None:
                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        print("Recognized face! Unlocking door...")
                        if _door is not None:
                            _door.off()
                        play_sound(sound_welcome)
                    else:
                        print("Face not recognized.")
                        play_sound(sound_wait)
                else:
                    print("No face detected.")
                    play_sound(sound_later)
            time.sleep(0.1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

