import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration -----------------------------------------------------------
I2C_ADDRESS = 0x27          # PCF8574 I2C backpack default address
LCD_COLUMNS = 16
LCD_ROWS = 2
DHT_PIN = board.D4          # GPIO4 (physical pin 7)
UPDATE_INTERVAL = 2.0       # seconds between readings

# --- Globals -----------------------------------------------------------------
lcd = None
dht_device = None
running = True


def cleanup(signum=None, frame=None):
    """Clear the LCD and release resources on exit or signal."""
    global lcd, dht_device, running
    running = False
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the 16x2 I2C character LCD; return the LCD object or None."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS,
                                               address=I2C_ADDRESS)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize LCD at 0x{I2C_ADDRESS:02X}: {exc}",
              file=sys.stderr)
        return None


def init_dht22():
    """Initialize the DHT22 sensor; return the device object or None."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize DHT22 on GPIO4: {exc}", file=sys.stderr)
        return None


def read_dht22(device):
    """Read temperature (C) and humidity (%) from the DHT22.

    Returns (temperature, humidity) on success, or (None, None) on any error.
    """
    try:
        temperature = device.temperature
        humidity = device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # DHT22 checksum / timing errors are common; log and continue.
        print(f"[WARN] DHT22 read error: {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"[ERROR] Unexpected DHT22 failure: {exc}", file=sys.stderr)
        return None, None


def display_data(lcd_obj, temperature, humidity):
    """Write temperature and humidity to the LCD, or an error message."""
    if temperature is None or humidity is None:
        lcd_obj.message = "Sensor Error"
        return
    temp_str = f"Temp: {temperature:.1f} C"
    hum_str = f"Humidity: {humidity:.1f}%"
    lcd_obj.message = temp_str
    lcd_obj.cursor_position = (0, 1)
    lcd_obj.message = hum_str


def main():
    global lcd, dht_device

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # --- Initialize I2C bus -------------------------------------------------
    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    # --- Initialize LCD -----------------------------------------------------
    lcd = init_lcd(i2c_bus)
    if lcd is None:
        cleanup()
        sys.exit(1)

    # --- Initialize DHT22 sensor -------------------------------------------
    dht_device = init_dht22()
    if dht_device is None:
        cleanup()
        sys.exit(1)

    # --- Main loop ----------------------------------------------------------
    try:
        while running:
            temperature, humidity = read_dht22(dht_device)
            display_data(lcd, temperature, humidity)
            time.sleep(UPDATE_INTERVAL)
    except Exception as exc:
        print(f"[ERROR] Unexpected runtime error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

