import time
import signal
import sys
from gpiozero import OutputDevice, InputDevice

TRIGGER_PIN = 23
ECHO_PIN = 24
SPEED_OF_SOUND_CM_PER_S = 34300.0
DISTANCE_FACTOR = SPEED_OF_SOUND_CM_PER_S / 2.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def measure_distance(trigger, echo):
    try:
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.1
        while echo.value == 0:
            if time.time() > timeout:
                raise TimeoutError("Echo never went HIGH")
            pulse_start = time.time()

        timeout = time.time() + 0.1
        while echo.value == 1:
            if time.time() > timeout:
                raise TimeoutError("Echo never went LOW")
            pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * DISTANCE_FACTOR
        return distance
    except TimeoutError as e:
        print(f"Sensor timeout: {e}")
        return None
    except Exception as e:
        print(f"Error measuring distance: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        trigger = OutputDevice(TRIGGER_PIN)
        echo = InputDevice(ECHO_PIN)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    try:
        time.sleep(2)
        while running:
            distance = measure_distance(trigger, echo)
            if distance is not None:
                print(f"Measured Distance = {distance:.2f} cm")
            time.sleep(0.5)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        trigger.close()
        echo.close()
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

