import serial
import time
import signal
import sys

# Configuration for RS485 sensor via USB-to-RS485 adapter
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1          # seconds
READ_INTERVAL = 0.5  # seconds between readings

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    """Initialize the serial connection with explicit 8N1 framing."""
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout
        )
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None

def read_temperature(serial_connection):
    """Read one line from the serial port and extract the first float."""
    try:
        raw = serial_connection.readline()
        if not raw:
            return None  # timeout, no data
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        # Extract the first substring that looks like a float
        for token in line.split():
            try:
                return float(token)
            except ValueError:
                continue
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}")
        return None

def display_temperature(temperature):
    """Print the temperature value formatted to one decimal place."""
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} C")

def main():
    """Main loop: initialize serial, read, display, repeat."""
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            temperature = read_temperature(serial_connection)
            display_temperature(temperature)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

