import signal
import sys
import time
import logging

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor over I2C."""

    DEFAULT_I2C_BUS = 1
    DEFAULT_I2C_ADDRESS = 0x38

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, i2c_address=DEFAULT_I2C_ADDRESS):
        self.i2c_address = i2c_address
        self.bus = None
        try:
            self.bus = SMBus(i2c_bus)
        except (IOError, OSError) as e:
            logger.error(f"Failed to open I2C bus {i2c_bus}: {e}")
            self.bus = None
        if self.bus is not None:
            try:
                self.bus.read_byte_data(self.i2c_address, 0x71)
            except (IOError, OSError) as e:
                logger.error(f"DHT20 not detected at address 0x{self.i2c_address:02X} on bus {i2c_bus}: {e}")
                self.bus = None

    def _crc8(self, data):
        """Compute CRC-8 (polynomial 0x31, init 0xFF) over the first 6 bytes."""
        crc = 0xFF
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        """Trigger a measurement and return (temperature, humidity, crc_error)."""
        if self.bus is None:
            logger.error("I2C bus not initialized; cannot measure.")
            return None, None, True

        try:
            self.bus.write_i2c_block_data(self.i2c_address, 0xAC, [0x33, 0x00])
        except (IOError, OSError) as e:
            logger.error(f"Failed to write measurement command: {e}")
            return None, None, True

        start = time.monotonic()
        while True:
            try:
                status = self.bus.read_byte_data(self.i2c_address, 0x71)
            except (IOError, OSError) as e:
                logger.error(f"Failed to read status register: {e}")
                return None, None, True
            if (status & 0x80) == 0:
                break
            if time.monotonic() - start > 0.1:
                logger.error("Measurement timed out waiting for status bit 7 to clear.")
                return None, None, True
            time.sleep(0.01)

        try:
            data = self.bus.read_i2c_block_data(self.i2c_address, 0x71, 7)
        except (IOError, OSError) as e:
            logger.error(f"Failed to read measurement data: {e}")
            return None, None, True

        if len(data) < 7:
            logger.error(f"Short read: expected 7 bytes, got {len(data)}.")
            return None, None, True

        calculated_crc = self._crc8(data[:6])
        crc_error = calculated_crc != data[6]

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        temperature = float(temperature_raw) / 5242.88 - 50.0
        humidity = float(humidity_raw) / 0x100000 * 100.0

        return temperature, humidity, crc_error

    def close(self):
        """Release the I2C bus handle."""
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


def main():
    sensor = DHT20()
    if sensor.bus is None:
        logger.error("Sensor initialization failed. Exiting.")
        sys.exit(1)

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received; shutting down.")
        sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        temperature, humidity, crc_error = sensor.measure()
        if crc_error:
            logger.error("CRC error detected; data may be corrupted.")
        else:
            logger.info(f"Temperature: {temperature:.2f} C")
            logger.info(f"Humidity: {humidity:.2f} %")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

