import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_ADDRESS_MULTIPLEXER = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1
READ_INTERVAL_SECONDS = 2


def initialize_i2c():
    """Initializes the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer at address 0x70."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDRESS_MULTIPLEXER)
        return multiplexer
    except ValueError as e:
        print(f"Error: TCA9548A multiplexer not found at address 0x{I2C_ADDRESS_MULTIPLEXER:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_sensors(multiplexer):
    """Initializes the BME280 and TSL2591 sensors via the TCA9548A multiplexer."""
    bme280 = None
    tsl2591 = None

    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[BME280_CHANNEL], address=0x76)
    except ValueError as e:
        print(f"Error: BME280 not found on multiplexer channel {BME280_CHANNEL}: {e}")
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")

    try:
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[TSL2591_CHANNEL], address=0x29)
    except ValueError as e:
        print(f"Error: TSL2591 not found on multiplexer channel {TSL2591_CHANNEL}: {e}")
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")

    return bme280, tsl2591


def read_and_print_sensor_data(bme280, tsl2591):
    """Reads data from the BME280 and TSL2591 sensors and prints the results."""
    if bme280 is None or tsl2591 is None:
        print("One or more sensors failed to initialize. Skipping data read.")
        return

    try:
        temperature = bme280.temperature
        humidity = bme280.humidity
        light_intensity = tsl2591.lux

        print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %, Light Intensity: {light_intensity:.1f} lux")

    except Exception as e:
        print(f"Error reading sensor data: {e}")


def main():
    """Main function to run the sensor reading loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280, tsl2591 = initialize_sensors(multiplexer)
    if bme280 is None and tsl2591 is None:
        print("No sensors initialized. Exiting.")
        return

    try:
        while True:
            read_and_print_sensor_data(bme280, tsl2591)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")


if __name__ == "__main__":
    main()

