import time
import signal
import sys
import RPi.GPIO as GPIO
import adafruit_dht

# Pin definitions (BCM numbering)
DHT_PIN = 4
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

# PWM frequency (Hz)
PWM_FREQ = 100

# Sampling interval (seconds)
SAMPLE_INTERVAL = 1.0

# Global state for cleanup
_running = True
_pwm_red = None
_pwm_green = None
_pwm_blue = None
_dht = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _pwm_red, _pwm_green, _pwm_blue, _dht
    for pwm in (_pwm_red, _pwm_green, _pwm_blue):
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
    _pwm_red = _pwm_green = _pwm_blue = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
        _dht = None


def _set_led(red_duty, green_duty, blue_duty):
    if _pwm_red is not None:
        _pwm_red.ChangeDutyCycle(red_duty)
    if _pwm_green is not None:
        _pwm_green.ChangeDutyCycle(green_duty)
    if _pwm_blue is not None:
        _pwm_blue.ChangeDutyCycle(blue_duty)


def _read_temperature():
    global _dht
    if _dht is None:
        _dht = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    try:
        return _dht.temperature
    except RuntimeError as e:
        print(f"DHT11 read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected DHT11 error: {e}")
        return None


def main():
    global _running, _pwm_red, _pwm_green, _pwm_blue

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    try:
        GPIO.setup(RED_PIN, GPIO.OUT)
        GPIO.setup(GREEN_PIN, GPIO.OUT)
        GPIO.setup(BLUE_PIN, GPIO.OUT)

        _pwm_red = GPIO.PWM(RED_PIN, PWM_FREQ)
        _pwm_green = GPIO.PWM(GREEN_PIN, PWM_FREQ)
        _pwm_blue = GPIO.PWM(BLUE_PIN, PWM_FREQ)
        _pwm_red.start(0)
        _pwm_green.start(0)
        _pwm_blue.start(0)

        last_temp = None
        while _running:
            temp = _read_temperature()
            if temp is not None:
                last_temp = temp
                if temp < 20:
                    _set_led(0, 0, 100)
                elif temp <= 25:
                    _set_led(0, 100, 0)
                else:
                    _set_led(100, 0, 0)
                print(f"Temperature: {temp:.1f}°C -> LED: {'Blue' if temp < 20 else 'Green' if temp <= 25 else 'Red'}")
            else:
                print("Temperature read failed; keeping last LED state.")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

