            logging.info(f"GPIO setup successful: relay on pin {self.relay_pin}.")
        except GPIOZeroError as e:
            logging.error(f"GPIO setup failed: {e}")
            self.cleanup()
            sys.exit(1)

    def _setup_socket(self):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.sock.bind(('', self.port))
            self.sock.listen(1)
            self.sock.settimeout(1.0)
            logging.info(f"Listening on port {self.port}.")
        except socket.error as e:
            logging.error(f"Socket setup failed: {e}")
            self.cleanup()
            sys.exit(1)

    def _validate_ip(self, client_address):
        if client_address[0] != self.allowed_ip:
            logging.warning(f"Unauthorized connection from {client_address[0]}.")
            return False
        return True

    def _handle_command(self, command):
        if command['command'] == 'pump_on':
            self.relay.on()
            self.pump_on = True
            logging.info("Pump turned ON.")
            return {"pump": "on", "temperature": 25.0}
        elif command['command'] == 'pump_off':
            self.relay.off()
            self.pump_on = False
            logging.info("Pump turned OFF.")
            return {"pump": "off", "temperature": 25.0}
        elif command['command'] == 'get_status':
            return {"pump": "on" if self.pump_on else "off", "temperature": 25.0}
        else:
            logging.warning(f"Unknown command: {command['command']}")
            return {"error": "Unknown command"}

    def _receive_command(self, conn, addr):
        try:
            data = conn.recv(1024)
            if not data:
                logging.info("Connection closed by client.")
                return
            command = json.loads(data.decode('utf-8'))
            response = self._handle_command(command)
            conn.sendall(json.dumps(response).encode('utf-8'))
        except json.JSONDecodeError:
            logging.error("Invalid JSON received.")
            try:
                conn.sendall(json.dumps({"error": "Invalid JSON"}).encode('utf-8'))
            except socket.error:
                pass
        except socket.error as e:
            logging.error(f"Socket error during communication: {e}")
        except Exception as e:
            logging.error(f"Unexpected error handling command: {e}")
        finally:
            conn.close()

    def run(self):
        try:
            while True:
                try:
                    conn, addr = self.sock.accept()
                    logging.info(f"Connection from {addr[0]}.")
                    self._receive_command(conn, addr)
                except socket.timeout:
                    continue
                except socket.error as e:
                    logging.error(f"Socket accept error: {e}")
                    break
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Shutting down.")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.relay is not None:
            try:
                self.relay.off()
                self.relay.close()
                logging.info("GPIO cleanup complete.")
            except Exception as e:
                logging.error(f"GPIO cleanup error: {e}")
        if self.sock is not None:
            try:
                self.sock.close()
                logging.info("Socket closed.")
            except Exception as e:
                logging.error(f"Socket close error: {e}")


def main():
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=17, help="GPIO pin for relay (BCM)")
    parser.add_argument("--dht_pin", type=int, default=4, help="GPIO pin for DHT11 (BCM)")
    parser.add_argument("--port", type=int, default=12345, help="TCP port")
    parser.add_argument("--allowed_ip", type=str, default="192.168.1.100", help="Allowed client IP")
    parser.add_argument("--log_file", type=str, default="hydroponics.log", help="Log file path")
    args = parser.parse_args()

    controller = HydroponicsController(
        args.relay_pin, args.dht_pin, args.port, args.allowed_ip, args.log_file
    )
    controller.run()


if __name__ == "__main__":
    main()

