import time
import logging
import signal
import sys
from smbus2 import SMBus, i2c_msg

try:
    from adafruit_bmp280 import BMP280
except ImportError:
    logging.error("adafruit-circuitpython-bmp280 not installed. Install with: pip install adafruit-circuitpython-bmp280")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
I2C_ADDR = 0x76
SEA_LEVEL_PRESSURE = 1013.25
NUM_SAMPLES = 100
TRIM_PERCENTAGE = 0.25

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

def read_register(bus, addr, reg):
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]

def verify_bmp280(bus, addr):
    chip_id = read_register(bus, addr, 0xD0)
    if chip_id != 0x58:
        raise RuntimeError(f"BMP280 not found at 0x{addr:02X}. Chip ID read 0x{chip_id:02X}")

def initialize_bmp280(bus_number=I2C_BUS, address=I2C_ADDR):
    try:
        bus = SMBus(bus_number)
    except OSError as e:
        logger.error(f"Failed to open I2C bus {bus_number}: {e}")
        return None
    try:
        verify_bmp280(bus, address)
        bmp280 = BMP280(bus, address=address)
        logger.info("BMP280 initialized successfully.")
        return bmp280, bus
    except Exception as e:
        logger.error(f"Error initializing BMP280: {e}")
        try:
            bus.close()
        except Exception:
            pass
        return None, None

def calculate_altitude(bmp280, sea_level_pressure=SEA_LEVEL_PRESSURE):
    try:
        pressure = bmp280.pressure
        altitude = bmp280.altitude
        logger.info(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
        return altitude
    except Exception as e:
        logger.error(f"Error reading sensor data: {e}")
        return None

def collect_baseline_pressure(bmp280, num_samples=NUM_SAMPLES, trim_percentage=TRIM_PERCENTAGE):
    logger.info(f"Collecting baseline pressure data ({num_samples} samples)...")
    pressures = []
    for i in range(num_samples):
        if not _running:
            logger.info("Baseline collection interrupted.")
            return None
        try:
            pressures.append(bmp280.pressure)
        except Exception as e:
            logger.error(f"Error reading pressure during baseline: {e}")
            return None
        time.sleep(0.1)
    if not pressures:
        logger.error("No pressure data collected for baseline.")
        return None
    sorted_pressures = sorted(pressures)
    start = int(len(sorted_pressures) * trim_percentage)
    end = len(sorted_pressures) - int(len(sorted_pressures) * trim_percentage)
    baseline_pressure = sum(sorted_pressures[start:end]) / (len(sorted_pressures[start:end]))
    logger.info(f"Baseline pressure established: {baseline_pressure:.2f} hPa")
    return baseline_pressure

def main():
    bmp280, bus = initialize_bmp280()
    if bmp280 is None:
        logger.error("Failed to initialize BMP280. Exiting.")
        if bus:
            bus.close()
        return

    baseline_pressure = collect_baseline_pressure(bmp280)
    if baseline_pressure is None:
        logger.warning("Baseline calibration failed. Using default sea level pressure.")
        baseline_pressure = SEA_LEVEL_PRESSURE

    try:
        while _running:
            altitude = calculate_altitude(bmp280, baseline_pressure)
            if altitude is not None:
                logger.info(f"Relative altitude: {altitude:.2f} meters")
            time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        if bus:
            try:
                bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
        logger.info("Program terminated.")

if __name__ == "__main__":
    main()

