import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591


def main():
    # Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize TCA9548A I2C multiplexer at default address 0x70
    try:
        i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return

    # Initialize BME280 sensor on multiplexer channel 0 (default address 0x76 or 0x77)
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(
            i2c_multiplexer[0], address=0x76
        )
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return

    # Initialize TSL2591 light sensor on multiplexer channel 1 (default address 0x29)
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1])
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return

    print("Sensors initialized. Starting readings...")

    try:
        while True:
            try:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
                light_intensity = tsl2591_sensor.lux

                print(
                    f"Temperature: {temperature:.2f} C, "
                    f"Humidity: {humidity:.2f} %, "
                    f"Light Intensity: {light_intensity:.2f} lux"
                )
            except Exception as e:
                print(f"Error reading sensor data: {e}")

            time.sleep(2)

    except KeyboardInterrupt:
        print("\nExiting program.")


