import time
import signal
import sys
from gpiozero import PWMOutputDevice

PWM_PIN = 18
FREQ_HZ = 50
TEMP_PATH = '/sys/class/thermal/thermal_zone0/temp'
INTERVAL_S = 1.0
TEMP_40_DC = 0.0
TEMP_50_DC = 100.0

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    with open(TEMP_PATH, 'r') as f:
        return float(f.read().strip()) / 1000.0

def compute_duty_cycle(temp):
    if temp <= 40.0:
        return TEMP_40_DC
    if temp >= 50.0:
        return TEMP_50_DC
    return TEMP_40_DC + (temp - 40.0) * (TEMP_50_DC - TEMP_40_DC) / (50.0 - 40.0)

def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=FREQ_HZ, initial_value=0.0)
    except Exception as e:
        print(f'Failed to initialize PWM on GPIO{PWM_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                temp = read_cpu_temp()
                dc = compute_duty_cycle(temp)
                fan.value = dc / 100.0
                print(f'CPU: {temp:.1f}C -> Fan: {dc:.1f}%')
            except (IOError, OSError) as e:
                print(f'Error reading CPU temperature: {e}', file=sys.stderr)
            except Exception as e:
                print(f'Unexpected error: {e}', file=sys.stderr)

            time.sleep(INTERVAL_S)
    finally:
        fan.value = 0.0
        fan.close()
        print('Fan control stopped.')

if __name__ == '__main__':
    main()

