import time
import board
import adafruit_dht
import signal
import sys

# Global sensor reference for cleanup
sensor = None

def cleanup():
    """Release sensor resources."""
    global sensor
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass
        sensor = None

def signal_handler(sig, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print("\nSignal received, exiting...")
    cleanup()
    sys.exit(0)

def main():
    global sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DHT11 sensor on GPIO4 (board.D4)
    try:
        sensor = adafruit_dht.DHT11(board.D4)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor: {e}")
        print("Check wiring: VCC to 3.3V, DATA to GPIO4 (pin 7), GND to GND.")
        sys.exit(1)

    print("DHT11 sensor initialized. Reading every 5 seconds. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C")
                    print(f"Humidity: {humidity:.1f}%")
                else:
                    print("Sensor returned None values.")

            except RuntimeError as e:
                # DHT sensors frequently throw RuntimeError due to timing issues
                print(f"Read error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

