import random
import time
import signal
import sys

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

HEATER_PIN = 17
TEMP_MIN = 10
TEMP_MAX = 30
TEMP_THRESHOLD = 20
ITERATIONS = 5
DELAY_SECONDS = 2


def get_simulated_temperature():
    """Return a random temperature in [10, 30) degrees Celsius."""
    return random.uniform(TEMP_MIN, TEMP_MAX)


def control_heater(heater, temperature):
    """Drive the heater pin based on the current temperature."""
    if temperature < TEMP_THRESHOLD:
        heater.on()
        print('Heater ON')
    else:
        heater.off()
        print('Heater OFF')


def main():
    heater = None
    try:
        heater = OutputDevice(HEATER_PIN)
        heater.off()

        for i in range(ITERATIONS):
            temperature = get_simulated_temperature()
            print(f'Temperature: {temperature:.2f}°C')
            control_heater(heater, temperature)
            time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print('\nScript interrupted by user.')
    except GPIOZeroError as exc:
        print(f'GPIO error: {exc}', file=sys.stderr)
    except Exception as exc:
        print(f'Unexpected error: {exc}', file=sys.stderr)
    finally:
        if heater is not None:
            try:
                heater.off()
                heater.close()
            except Exception:
                pass
        print('GPIO cleanup completed.')


