import time
import signal
import sys
import json
from datetime import datetime, timezone

try:
    from gpiozero import PWMLED
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

try:
    import adafruit_dht
    import board
    DHT_AVAILABLE = True
except ImportError:
    DHT_AVAILABLE = False
    print("Warning: adafruit-circuitpython-dht or board is not installed; DHT22 logging disabled.", file=sys.stderr)

LED_PIN = 17
DHT_PIN = 4
PWM_FREQ = 100
DUTY_MAX = 90
DAY_HOLD = 10
NIGHT_HOLD = 10
SUNRISE_DURATION = 600
SUNSET_DURATION = 600
DHT_INTERVAL = 5

running = True
led = None
dht_device = None


def log_entry(brightness, temp, hum):
    ts = datetime.now(timezone.utc).isoformat()
    data = {
        "timestamp": ts,
        "brightness": round(brightness, 1),
        "temperature": temp,
        "humidity": hum,
    }
    print(json.dumps(data))


def cleanup(signum=None, frame=None):
    global running, led, dht_device
    running = False
    if led is not None:
        try:
            led.value = 0
            led.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
    sys.exit(0)


def read_dht22():
    if not DHT_AVAILABLE:
        return None, None
    for attempt in range(3):
        try:
            temp = dht_device.temperature
            hum = dht_device.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            print(f"DHT22 read attempt {attempt + 1} failed: {e}", file=sys.stderr)
        except Exception as e:
            print(f"DHT22 unexpected error: {e}", file=sys.stderr)
        time.sleep(0.5)
    return None, None


def main():
    global led, dht_device

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        led = PWMLED(LED_PIN, frequency=PWM_FREQ)
        led.value = 0
    except Exception as e:
        print(f"Failed to initialize PWMLED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    if DHT_AVAILABLE:
        try:
            dht_device = adafruit_dht.DHT22(board.D4)
        except Exception as e:
            print(f"Failed to initialize DHT22 on GPIO{DHT_PIN}: {e}", file=sys.stderr)
            dht_device = None

    current_brightness = 0
    is_manual = False
    manual_brightness = 0

    try:
        while running:
            if is_manual:
                try:
                    user_input = input("Enter brightness (0-90), 'auto', or 'exit': ").strip().lower()
                except EOFError:
                    break

                if user_input == 'exit':
                    break
                elif user_input == 'auto':
                    is_manual = False
                    continue

                val = int(user_input)
                if 0 <= val <= DUTY_MAX:
                    manual_brightness = val
                    current_brightness = val
                else:
                    print("Brightness must be between 0 and 90.", file=sys.stderr)
                    continue
            else:
                elapsed = time.time() % (SUNRISE_DURATION + SUNSET_DURATION + DAY_HOLD + NIGHT_HOLD)

                if elapsed < SUNRISE_DURATION:
                    ramp = elapsed / SUNRISE_DURATION * DUTY_MAX
                    current_brightness = min(ramp, DUTY_MAX)
                elif elapsed < SUNRISE_DURATION + DAY_HOLD:
                    current_brightness = DUTY_MAX
                elif elapsed < SUNRISE_DURATION + DAY_HOLD + SUNSET_DURATION:
                    ramp = (SUNRISE_DURATION + DAY_HOLD + SUNSET_DURATION - elapsed) / SUNSET_DURATION * DUTY_MAX
                    current_brightness = max(0, DUTY_MAX - ramp)
                else:
                    current_brightness = 0

            try:
                led.value = current_brightness / 100.0
            except Exception as e:
                print(f"Failed to set PWM duty cycle: {e}", file=sys.stderr)

            temp, hum = read_dht22()
            log_entry(current_brightness, temp, hum)

            if not is_manual:
                time.sleep(DHT_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

