import os
import sys
import time
import json
import signal
import logging
import logging.handlers
import threading
from datetime import datetime, timedelta

import board
import busio
import adafruit_bme280_i2c
import sqlite3
from flask import Flask, render_template_string

DEFAULT_CONFIG = {
    "polling_interval": 60,
    "database_path": "weather_data.db",
    "log_level": "INFO",
    "log_file": "error.log",
    "i2c_address_1": 0x76,
    "i2c_address_2": 0x77,
    "flask_port": 5000,
    "flask_host": "0.0.0.0",
    "flask_debug": False,
    "flask_use_reloader": False,
}

app = Flask(__name__)

shutdown_event = threading.Event()


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        return {**DEFAULT_CONFIG, **config}
    except FileNotFoundError:
        print(f"Config file '{config_file}' not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        print(f"Error decoding config file: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_level, log_file):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")
    logger = logging.getLogger()
    logger.setLevel(numeric_level)
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    return logger


def init_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        while not i2c.try_lock():
            time.sleep(0.1)
        i2c.unlock()
        return i2c
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        return None


def init_bme280(i2c, address):
    try:
        sensor = adafruit_bme280_i2c.Adafruit_BME280_I2C(i2c, address=address)
        logging.info(f"BME280 initialized at address 0x{address:02X}")
        return sensor
    except Exception as e:
        logging.error(f"Failed to initialize BME280 at 0x{address:02X}: {e}")
        return None


def read_bme280(sensor, address, max_retries=3, retry_delay=10):
    for attempt in range(max_retries):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            pressure = sensor.pressure
            if temperature is None or humidity is None or pressure is None:
                raise ValueError("Sensor returned None for one or more readings")
            return temperature, humidity, pressure
        except Exception as e:
            logging.error(f"Error reading BME280 at 0x{address:02X} (attempt {attempt + 1}/{max_retries}): {e}")
            if attempt < max_retries - 1:
                time.sleep(retry_delay)
    logging.critical(f"Failed to read BME280 at 0x{address:02X} after {max_retries} attempts. Disabling.")
    return None, None, None


def validate_data(temperature, humidity, pressure):
    if not all(isinstance(v, (int, float)) for v in (temperature, humidity, pressure)):
        return False
    if not (-40 <= temperature <= 85):
        logging.error(f"Temperature out of range: {temperature}")
        return False
    if not (0 <= humidity <= 100):
        logging.error(f"Humidity out of range: {humidity}")
        return False
    if not (300 <= pressure <= 1100):
        logging.error(f"Pressure out of range: {pressure}")
        return False
    return True


def store_data(db_path, timestamp, sensor_id, temperature, humidity, pressure):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS readings (timestamp TEXT, sensor_id INTEGER, temperature REAL, humidity REAL, pressure REAL, PRIMARY KEY (timestamp, sensor_id))"
        )
        cursor.execute(
            "INSERT OR REPLACE INTO readings (timestamp, sensor_id, temperature, humidity, pressure) VALUES (?, ?, ?, ?, ?)",
            (timestamp, sensor_id, temperature, humidity, pressure),
        )
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")


def get_last_24_hours_data(db_path):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cutoff = (datetime.now() - timedelta(hours=24)).isoformat()
        cursor.execute(
            "SELECT timestamp, sensor_id, temperature, humidity, pressure FROM readings WHERE timestamp >= ? ORDER BY timestamp DESC",
            (cutoff,),
        )
        data = cursor.fetchall()
        conn.close()
        return data
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
        return []


def create_html_table(data):
    rows = ""
    for row in data:
        ts, sid, temp, hum, pres = row
        rows += f"<tr><td>{ts}</td><td>{sid}</td><td>{temp:.1f}</td><td>{hum:.1f}</td><td>{pres:.1f}</td></tr>"
    return f"<table border='1'>{rows}</table>"


INDEX_TEMPLATE = """
<!DOCTYPE html>
<html>
<head><title>BME280 Weather Station</title></head>
<body>
    <h1>BME280 Weather Station Data</h1>
    <p>Last 24 hours:</p>
    {{ table }}
</body>
</html>
"""


@app.route("/")
def index():
    data = get_last_24_hours_data(config["database_path"])
    return render_template_string(INDEX_TEMPLATE, table=create_html_table(data))


def run_flask(port, host, debug, use_reloader):
    try:
        app.run(host=host, port=port, debug=debug, use_reloader=use_reloader)
    except Exception as e:
        logging.error(f"Flask server error: {e}")


def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received; shutting down.")
    shutdown_event.set()


def main():
    global config
    config = load_config()
    setup_logging(config["log_level"], config["log_file"])
    logging.info("Starting BME280 Weather Station")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = init_i2c()
    if i2c is None:
        logging.critical("I2C initialization failed; exiting.")
        sys.exit(1)

    sensors = {}
    for name, address in [("sensor1", config["i2c_address_1"]), ("sensor2", config["i2c_address_2"])]:
        sensors[name] = init_bme280(i2c, address)

    flask_thread = threading.Thread(target=run_flask, args=(config["flask_port"], config["flask_host"], config["flask_debug"], config["flask_use_reloader"]), daemon=True)
    flask_thread.start()

    try:
        while not shutdown_event.is_set():
            for name, sensor in sensors.items():
                if sensor is None:
                    continue
                temp, hum, pres = read_bme280(sensor, config[f"i2c_address_{name.split('_')[0] + 1}"])
                if temp is not None and hum is not None and pres is not None:
                    if validate_data(temp, hum, pres):
                        store_data(config["database_path"], datetime.now().isoformat(), name.split('_')[0] + 1, temp, hum, pres)
                else:
                    sensors[name] = None
            shutdown_event.wait(config["polling_interval"])
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        shutdown_event.set()
        if flask_thread.is_alive():
            flask_thread.join(timeout=5)
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

