import logging
import signal
import subprocess
import sys
import time
from pathlib import Path

from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class FanController:
    """
    Controls a 4-pin PWM fan connected to a Raspberry Pi GPIO pin.

    Uses gpiozero for hardware PWM generation.  The fan is assumed to be
    a logic-level PWM fan that accepts a 100 Hz signal on the 'PWM' pin.
    """

    PWM_FREQUENCY = 100  # Hz
    TEMP_CHECK_INTERVAL = 5  # seconds

    def __init__(self, fan_pin: int = 14):
        self.fan_pin = fan_pin
        self._running = True
        self._fan: PWMOutputDevice | None = None

        # gpiozero PWMOutputDevice exposes frequency and value (0.0–1.0).
        try:
            self._fan = PWMOutputDevice(
                pin=fan_pin,
                frequency=self.PWM_FREQUENCY,
                initial_value=0.0,
            )
            logging.info(
                "PWM fan controller initialized on GPIO%d @ %d Hz.",
                fan_pin,
                self.PWM_FREQUENCY,
            )
        except Exception as exc:
            logging.error("Failed to initialize PWM on GPIO%d: %s", fan_pin, exc)
            raise

    def _read_cpu_temp(self) -> float | None:
        """Return CPU temperature in °C, or None on failure."""
        try:
            result = subprocess.run(
                ["vcgencmd", "measure_temp"],
                capture_output=True,
                text=True,
                timeout=5,
            )
            if result.returncode != 0:
                logging.error(
                    "vcgencmd exited with code %d: %s", result.returncode, result.stderr.strip()
                )
                return None

            output = result.stdout.strip()
            # Expected format: temp=42.8'C
            if not output.startswith("temp="):
                logging.error("Unexpected vcgencmd output: %r", output)
                return None

            temp_str = output.split("=", 1)[1].split("'C", 1)[0]
            return float(temp_str)

        except FileNotFoundError:
            logging.error("vcgencmd not found; is this running on a Raspberry Pi?")
            return None
        except subprocess.TimeoutExpired:
            logging.error("vcgencmd timed out.")
            return None
        except (ValueError, IndexError) as exc:
            logging.error("Failed to parse CPU temperature: %s", exc)
            return None
        except Exception as exc:
            logging.error("Unexpected error reading CPU temperature: %s", exc)
            return None

    def _set_fan_speed(self, duty_percent: float) -> None:
        """Set fan duty cycle (0–100 %)."""
        if self._fan is None:
            return
        try:
            self._fan.value = max(0.0, min(100.0, float(duty_percent))) / 100.0
            logging.info("Fan speed set to %.0f%%", duty_percent)
        except Exception as exc:
            logging.error("Failed to set fan speed: %s", exc)

    def _temperature_to_speed(self, temp_c: float) -> float:
        """Map a temperature reading to a fan duty-cycle percentage."""
        if temp_c > 70:
            return 100.0
        if temp_c > 60:
            return 85.0
        if temp_c > 50:
            return 70.0
        if temp_c > 40:
            return 50.0
        if temp_c > 32:
            return 25.0
        if temp_c > 25:
            return 15.0
        return 0.0

    def run(self) -> None:
        """Main control loop."""
        logging.info("Fan control loop started.")
        while self._running:
            temp = self._read_cpu_temp()
            if temp is not None:
                speed = self._temperature_to_speed(temp)
                self._set_fan_speed(speed)
                logging.info("CPU temp: %.1f°C -> Fan: %.0f%%", temp, speed)
            else:
                logging.warning("Temperature read failed; keeping current fan speed.")

            # Sleep in small increments so signals are handled promptly.
            slept = 0.0
            while self._running and slept < self.TEMP_CHECK_INTERVAL:
                time.sleep(0.25)
                slept += 0.25

    def stop(self) -> None:
        """Stop the fan and release GPIO resources."""
        self._running = False
        if self._fan is not None:
            try:
                self._fan.value = 0.0
                self._fan.close()
                logging.info("Fan stopped and GPIO released.")
            except Exception as exc:
                logging.error("Error during fan shutdown: %s", exc)
            finally:
                self._fan = None


def main() -> None:
    controller = FanController(fan_pin=14)

    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down...", signum)
        controller.stop()
        sys.exit(0)

    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        controller.run()
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    except Exception as exc:
        logging.error("Fatal error in main loop: %s", exc)
    finally:
        controller.stop()


if __name__ == "__main__":
    main()

