# Environmental Monitoring Script for Raspberry Pi 4 Model B
# Reads temperature and humidity from a sensor over a serial port.
# Alerts when temperature or humidity exceed predefined thresholds.

import serial
import time
import sys

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# Thresholds for alerts
TEMPERATURE_THRESHOLD = 30.0  # Celsius
HUMIDITY_THRESHOLD = 70.0     # Percentage


def initialize_serial(port, baudrate, timeout):
    """Initialize the serial connection with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None


def read_sensor_data(serial_connection):
    """Read a line from the serial port and parse temperature/humidity."""
    try:
        raw_data = serial_connection.readline()
        if not raw_data:
            print("Warning: No data received (sensor absent or timeout).")
            return None, None

        data = raw_data.decode('ascii', errors='replace').strip()
        if not data:
            print("Warning: Empty line received.")
            return None, None

        parts = data.split(',')
        if len(parts) != 2:
            print(f"Warning: Malformed data (expected 2 fields, got {len(parts)}): '{data}'")
            return None, None

        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity

    except ValueError as e:
        print(f"Error parsing data '{data}': {e}")
        return None, None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor data: {e}")
        return None, None


def check_thresholds(temperature, humidity):
    """Check if temperature or humidity exceed thresholds and print alerts."""
    if temperature is not None and humidity is not None:
        if temperature > TEMPERATURE_THRESHOLD:
            print(f"Alert: Temperature {temperature:.1f}°C exceeds threshold {TEMPERATURE_THRESHOLD}°C")
        if humidity > HUMIDITY_THRESHOLD:
            print(f"Alert: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")


def main():
    """Main function to read sensor data and check thresholds."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            temperature, humidity = read_sensor_data(serial_connection)
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            check_thresholds(temperature, humidity)
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

