import subprocess
import time
import signal
import sys
import logging

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    PWMOutputDevice = None
    GPIOZeroError = Exception

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

FAN_PIN = 14
PWM_FREQ = 100
POLL_INTERVAL = 5

TEMP_THRESHOLDS = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info(f"Received signal {signum}; shutting down.")
    _running = False


def get_cpu_temperature():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5,
            check=True
        )
        return float(result.stdout.strip().split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired,
            IndexError, ValueError) as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None


def get_fan_speed(temp):
    for threshold, speed in TEMP_THRESHOLDS:
        if temp > threshold:
            return speed
    return 0


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
    if PWMOutputDevice is not None:
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
            logging.info(f"PWM fan control started on GPIO{FAN_PIN} @ {PWM_FREQ} Hz.")
        except GPIOZeroError as e:
            logging.warning(f"Failed to initialise PWM on GPIO{FAN_PIN}: {e}. "
                            "Running in degraded mode (logging only).")
            fan = None
    else:
        logging.warning("gpiozero not available; running in degraded mode.")

    last_speed = 0

    try:
        while _running:
            temp = get_cpu_temperature()
            if temp is not None:
                speed = get_fan_speed(temp)
                if fan is not None:
                    try:
                        fan.value = speed / 100.0
                        last_speed = speed
                    except GPIOZeroError as e:
                        logging.error(f"Error setting fan speed: {e}")
                else:
                    logging.info(f"CPU: {temp:.1f}°C -> fan: {speed}%")
            else:
                logging.warning("Temperature read failed; keeping last fan speed.")

            for _ in range(POLL_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
            except Exception:
                pass
        logging.info("Fan control stopped.")


if __name__ == '__main__':
    main()

