import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def main():
    led_state = False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off': ").strip().lower()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")

            print(f"LED is {'ON' if led_state else 'OFF'}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()

if __name__ == "__main__":
    main()

