#!/usr/bin/env python3
"""
led_control.py - Control an LED with a button using gpiozero.

Hardware:
  - LED + 330 ohm resistor -> GPIO 17 (physical pin 11)
  - Button -> 3.3V (physical pin 1)
  - Button -> GPIO 5 (physical pin 29)
  - Button -> 10 kohm pull-down resistor -> GND (physical pin 6)

GPIO 2 is avoided because it carries a fixed on-board pull-up resistor
that conflicts with an external pull-down resistor.
"""

import sys
import time

try:
    from gpiozero import LED, Button
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)


LED_PIN = 17
BUTTON_PIN = 5
POLL_INTERVAL = 0.1  # seconds


def main():
    """Main loop: poll the button and drive the LED accordingly."""
    led = None
    button = None
    try:
        # Initialize devices with explicit pin numbers.
        # gpiozero uses BCM numbering by default.
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=False)

        print("LED control started. Press Ctrl+C to exit.")

        while True:
            if button.is_pressed:
                if not led.is_lit:
                    led.on()
                print("Button pressed! LED is ON")
            else:
                if led.is_lit:
                    led.off()
                print("Button released! LED is OFF")

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
    except DeviceClosed as e:
        print(f"Device closed unexpectedly: {e}", file=sys.stderr)
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        # Ensure the LED is off and resources are released on every exit path.
        if led is not None:
            try:
                led.off()
                led.close()
            except Exception:
                pass
        if button is not None:
            try:
                button.close()
            except Exception:
                pass
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

