import sys
import threading
import signal
import time
import RPi.GPIO as GPIO
import DOG

# Constants
DEFAULT_LOG_FILE = "data.log"
RECEIVE_INTERVAL = 0.1  # seconds

# Global variables
log_file_name = DEFAULT_LOG_FILE
receive_thread = None
receive_event_flag = threading.Event()
receive_lock = threading.Lock()


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM to ensure clean shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    stop_server()
    GPIO.cleanup()
    sys.exit(0)


def help_command(args):
    """Displays help information for commands."""
    if len(args) == 1:
        print("Available commands:")
        print("  start <filename>  - Start the server and log data to the specified file.")
        print("  stop              - Stop the server.")
        print("  display           - Display the contents of the log file.")
        print("  send <data>       - Send data using DOG.send().")
        print("  write <data>      - Write data directly to the log file.")
        print("  help [command]    - Show help for a specific command.")
        print("  exit              - Stop the server and exit.")
    elif len(args) == 2:
        command = args[1]
        if command == "start":
            print("Usage: start <filename>")
        elif command == "stop":
            print("Usage: stop")
        elif command == "display":
            print("Usage: display")
        elif command == "send":
            print("Usage: send <data>")
        elif command == "write":
            print("Usage: write <data>")
        elif command == "help":
            print("Usage: help [command]")
        else:
            print(f"Unknown command: {command}")
    else:
        print("Usage: help [command]")


def start_server(filename):
    """Starts the data logging server."""
    global log_file_name, receive_thread

    if receive_thread is not None and receive_thread.is_alive():
        print("Server is already running.")
        return

    log_file_name = filename
    try:
        with open(log_file_name, "a") as f:
            pass  # Touch the file to ensure it exists
    except IOError as e:
        print(f"Error creating/opening log file '{log_file_name}': {e}")
        return

    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()
    print(f"Server started. Logging to '{log_file_name}'.")


def stop_server():
    """Stops the data logging server."""
    global receive_thread

    if receive_thread is not None and receive_thread.is_alive():
        receive_event_flag.set()  # Signal the receive thread to stop
        receive_thread.join(timeout=2.0)
        if receive_thread.is_alive():
            print("Warning: receive thread did not stop gracefully.")
        receive_thread = None
    print("Server stopped.")


def receive_data():
    """Continuously receives data and writes it to the log file."""
    while receive_event_flag.is_set():
        try:
            data = DOG.receive()
            if data:
                with receive_lock:
                    try:
                        with open(log_file_name, "a") as f:
                            f.write(data + "\n")
                    except IOError as e:
                        print(f"Error writing to log file: {e}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            time.sleep(RECEIVE_INTERVAL)
        time.sleep(RECEIVE_INTERVAL)


def display_command(args):
    """Displays the contents of the log file."""
    if log_file_name == DEFAULT_LOG_FILE:
        print("No log file specified. Use 'start <filename>' to specify a log file.")
        return
    try:
        with open(log_file_name, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Log file '{log_file_name}' not found.")
    except IOError as e:
        print(f"Error reading log file: {e}")


def send_command(args):
    """Sends data using DOG.send()."""
    if len(args) < 2:
        print("Usage: send <data>")
        return
    data = " ".join(args[1:])
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_command(args):
    """Writes data directly to the log file."""
    if len(args) < 2:
        print("Usage: write <data>")
        return
    data = " ".join(args[1:])
    if log_file_name == DEFAULT_LOG_FILE:
        print("No log file specified. Use 'start <filename>' to specify a log file.")
        return
    try:
        with open(log_file_name, "a") as f:
            f.write(data + "\n")
        print(f"Wrote: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def exit_command(args):
    """Stops the server and exits."""
    stop_server()
    GPIO.cleanup()
    sys.exit(0)


def main():
    """Main function to run the server."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    command_table = {
        "help": help_command,
        "start": start_server,
        "stop": stop_server,
        "display": display_command,
        "send": send_command,
        "write": write_command,
        "exit": exit_command,
    }

    while True:
        try:
            command = input("JAYES@ROVER53:\t").strip().lower().split()
            if not command:
                continue

            if command[0] in command_table:
                command_table[command[0]](command)
            else:
                print(f"Unknown command: {command[0]}")
        except EOFError:
            break
        except Exception as e:
            print(f"An error occurred: {e}")

    stop_server()
    GPIO.cleanup()


if __name__ == "__main__":
    main()

