import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two IR sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
SAMPLE_COUNT = 10
SAMPLE_INTERVAL = 0.5  # seconds


def setup_gpio():
    """Configure GPIO pins for the IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)


def read_ir_sensor(pin):
    """Read the state of an IR sensor. Returns 0 (black) or 1 (white)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return -1  # invalid reading


def decide_steering(left_state, right_state):
    """Decide steering direction based on sensor readings.

    Returns:
        'forward' if both sensors see white (line lost),
        'turn-left' if only left sensor sees black,
        'turn-right' if only right sensor sees black,
        'search' if both sensors see black (line found).
    """
    if left_state == 1 and right_state == 1:
        return "forward"
    if left_state == 0 and right_state == 1:
        return "turn-left"
    if left_state == 1 and right_state == 0:
        return "turn-right"
    return "search"


def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")


def main():
    setup_gpio()
    try:
        for sample_index in range(SAMPLE_COUNT):
            left_state = read_ir_sensor(LEFT_SENSOR_PIN)
            right_state = read_ir_sensor(RIGHT_SENSOR_PIN)

            if left_state == -1 or right_state == -1:
                print(f"Sample {sample_index}: Sensor read error - skipping")
                time.sleep(SAMPLE_INTERVAL)
                continue

            steering = decide_steering(left_state, right_state)
            print(f"Sample {sample_index}: left={left_state} right={right_state} steering={steering}")

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

