#!/usr/bin/env python3
"""Flask web server controlling an LED on GPIO 17 (BCM) using gpiozero."""

import signal
import sys
from flask import Flask, render_template_string

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

LED_PIN = 17
led = None

INDEX_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
    <h1>LED Control</h1>
    <p>Current state: {{ state }}</p>
    <a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
</body>
</html>
"""


def init_led():
    """Initialize the LED; exit if the Pi or pin is unavailable."""
    global led
    try:
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO {LED_PIN} (BCM).")
    except BadPinFactory:
        print("Error: No GPIO pin factory available. Are you running on a Raspberry Pi?", file=sys.stderr)
        sys.exit(1)
    except GPIOZeroError as e:
        print(f"Error initializing LED on GPIO {LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)


def cleanup(signum=None, frame=None):
    """Release the LED resource and exit."""
    global led
    if led is not None:
        try:
            led.close()
            print("LED resource released.")
        except Exception as e:
            print(f"Error closing LED: {e}", file=sys.stderr)
        finally:
            led = None
    if signum is not None:
        sys.exit(0)


@app.route("/")
def index():
    """Display the current LED state and control links."""
    state = "ON" if led.is_lit else "OFF"
    return render_template_string(INDEX_HTML, state=state)


@app.route("/light_on")
def light_on():
    """Turn the LED on and return a status page."""
    if led is None:
        return render_template_string("<h1>Error</h1><p>LED not initialized.</p>"), 500
    led.on()
    return render_template_string("<h1>LED ON</h1><p>Turned LED on. <a href=\"/\">Back</a></p>")


@app.route("/light_off")
def light_off():
    """Turn the LED off and return a status page."""
    if led is None:
        return render_template_string("<h1>Error</h1><p>LED not initialized.</p>"), 500
    led.off()
    return render_template_string("<h1>LED OFF</h1><p>Turned LED off. <a href=\"/\">Back</a></p>")


if __name__ == "__main__":
    init_led()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host="0.0.0.0", port=8080, debug=False)
    finally:
        cleanup()

