#!/usr/bin/python3

"""
OutputPin: robust GPIO output control on Raspberry Pi using pigpio.

Requires the pigpio daemon to be running (sudo pigpiod).
"""

import pigpio
import time
import sys
from typing import Optional


class OutputPinError(Exception):
    """Custom exception for OutputPin errors."""
    pass


class OutputPin:
    """
    Controls a single GPIO pin as a digital output using pigpio.

    Parameters
    ----------
    pin_number : int
        Broadcom BCM pin number (0-31).
    initial_value : int
        Initial output level: 0 (LOW) or 1 (HIGH).
    pi : Optional[pigpio.pi]
        An existing pigpio.pi() connection. If None, a new connection is
        created and managed by the OutputPin.
    """

    def __init__(self, pin_number: int, initial_value: int, pi: Optional[pigpio.pi] = None):
        if not (0 <= pin_number <= 31):
            raise OutputPinError(
                f"Invalid pin number {pin_number}; must be 0-31."
            )
        if initial_value not in (0, 1):
            raise OutputPinError(
                f"Invalid initial_value {initial_value}; must be 0 or 1."
            )

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi: Optional[pigpio.pi] = None
        self._connected = False

        if pi is None:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise OutputPinError(
                    "Failed to connect to pigpio daemon. Is pigpiod running?"
                )
        else:
            self.pi = pi

        try:
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pi.write(self.pin_number, self.initial_value)
            self._connected = True
        except pigpio.error as e:
            self.shutdown()
            raise OutputPinError(f"Failed to initialize pin {self.pin_number}: {e}") from e

    def set_value(self, value: int) -> None:
        """
        Set the output value of the pin.

        Parameters
        ----------
        value : int
            Desired output level: 0 (LOW) or 1 (HIGH).
        """
        if not self._connected:
            raise OutputPinError("Pin is not initialized.")
        if value not in (0, 1):
            raise OutputPinError(
                f"Invalid value {value}; must be 0 or 1."
            )
        try:
            self.pi.write(self.pin_number, value)
        except pigpio.error as e:
            raise OutputPinError(f"Failed to write to pin {self.pin_number}: {e}") from e

    def shutdown(self) -> None:
        """
        Release the pin: set it to INPUT mode and close the pigpio connection.
        Safe to call even if initialization partially failed.
        """
        if self.pi is not None:
            try:
                if self._connected:
                    self.pi.set_mode(self.pin_number, pigpio.INPUT)
            except pigpio.error:
                pass  # Best-effort during shutdown
            try:
                self.pi.stop()
            except pigpio.error:
                pass
            finally:
                self.pi = None
                self._connected = False

    def __del__(self):
        self.shutdown()


if __name__ == "__main__":
    PIN = 17  # BCM GPIO 17 (physical pin 11)
    TOGGLE_INTERVAL = 0.5  # seconds
    RUN_DURATION = 5.0  # seconds

    try:
        pin = OutputPin(PIN, initial_value=0)
        start = time.monotonic()
        while time.monotonic() - start < RUN_DURATION:
            pin.set_value(1 if pin.initial_value == 0 else 0)
            pin.initial_value = 1 - pin.initial_value
            time.sleep(TOGGLE_INTERVAL)
    except OutputPinError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if 'pin' in locals():
            pin.shutdown()
        print("GPIO cleanup complete.")

