import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz standard for 4-wire PWM fans

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Warning: Could not initialize hardware PWM on GPIO{FAN_PIN}: {e}")
        print("Falling back to software PWM (may have lower resolution).")
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)

    print(f"PWM fan control on GPIO{FAN_PIN} at {PWM_FREQ} Hz. Type 'q' or Ctrl+C to quit.")

    while running:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
        except EOFError:
            break

        if not user_input:
            continue

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if 0 <= speed <= 100:
            fan.value = speed / 100.0
            print(f"Fan speed set to {speed:.1f}%")
        else:
            print("Speed out of range. Please enter a value between 0 and 100.")

except Exception as e:
    print(f"An error occurred: {e}")

finally:
    cleanup()
    print("Fan control stopped. GPIO resources released.")

