import http.server
import socketserver
import signal
import sys
from gpiozero import LED

LED_PIN = 18
PORT = 8080

led = None
httpd = None


class LEDRequestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            led.on()
            self._respond(200, 'LED is ON')
        elif self.path == '/led/off':
            led.off()
            self._respond(200, 'LED is OFF')
        else:
            self._respond(404, 'Not Found')

    def _respond(self, status_code, message):
        self.send_response(status_code)
        self.send_header('Content-type', 'text/plain')
        self.end_headers()
        self.wfile.write(message.encode('utf-8'))

    def log_message(self, fmt, *args):
        sys.stderr.write(f'{self.address_string()} - {fmt % args}\n')


def _shutdown(signum, frame):
    global httpd
    sys.stderr.write(f'\nReceived signal {signum}, shutting down...\n')
    if httpd is not None:
        httpd.shutdown()


def main():
    global led, httpd
    try:
        led = LED(LED_PIN)
    except Exception as e:
        sys.stderr.write(f'Failed to initialize LED on GPIO{LED_PIN}: {e}\n')
        sys.exit(1)

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        httpd = socketserver.ThreadingTCPServer(('', PORT), LEDRequestHandler)
    except OSError as e:
        sys.stderr.write(f'Failed to bind socket on port {PORT}: {e}\n')
        led.close()
        sys.exit(1)

    sys.stderr.write(f'Server listening on port {PORT}\n')
    try:
        httpd.serve_forever()
    except Exception as e:
        sys.stderr.write(f'Server error: {e}\n')
    finally:
        if httpd is not None:
            httpd.server_close()
        if led is not None:
            led.close()
        sys.stderr.write('Server stopped.\n')


if __name__ == '__main__':
    main()

