import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

I2C_BUS = 1
BH1750_ADDR = 0x23
POWER_ON = 0x01
CONTINUOUS_HIGH_RES = 0x10

running = True

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

bus = None
try:
    bus = SMBus(I2C_BUS)
except OSError as e:
    print(f"Error: Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(f"Error: Unexpected I2C initialization failure: {e}", file=sys.stderr)
    sys.exit(1)

try:
    # Probe the sensor address to confirm it is present
    try:
        bus.read_byte(BH1750_ADDR)
    except OSError:
        print(f"Error: No device found at I2C address 0x{BH1750_ADDR:02X} on bus {I2C_BUS}.", file=sys.stderr)
        sys.exit(1)

    # Power on the sensor
    try:
        bus.write_byte(BH1750_ADDR, POWER_ON)
    except OSError as e:
        print(f"Error: Failed to power on BH1750 at 0x{BH1750_ADDR:02X}: {e}", file=sys.stderr)
        sys.exit(1)

    # Set continuous high-resolution mode
    try:
        bus.write_byte(BH1750_ADDR, CONTINUOUS_HIGH_RES)
    except OSError as e:
        print(f"Error: Failed to set continuous mode on BH1750: {e}", file=sys.stderr)
        sys.exit(1)

    # Allow a brief settle period for the first measurement
    time.sleep(0.18)

    while running:
        try:
            raw = bus.read_word_data(BH1750_ADDR, 0x00)
            lux = raw / 1.2
            print(f"Ambient Light: {lux:.2f} lux")
        except OSError as e:
            print(f"Warning: I2C read error (sensor may be disconnected): {e}", file=sys.stderr)
        except Exception as e:
            print(f"Warning: Unexpected read error: {e}", file=sys.stderr)

        time.sleep(1)

except Exception as e:
    print(f"Error: {e}", file=sys.stderr)

finally:
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    print("\nExiting cleanly.")

