import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

I2C_BUS = 1
I2C_ADDR = 0x23
I2C_FREQ_HZ = 400000
BH1750_ONCE_HIRES_1 = 0x20
CONV_MS = 0.12
READ_INTERVAL_S = 3

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def read_lux(bus):
    bus.write_byte(I2C_ADDR, BH1750_ONCE_HIRES_1)
    time.sleep(CONV_MS)
    data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    return raw / 1.2

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        try:
            bus.read_byte(I2C_ADDR)
        except OSError:
            print("Error: BH1750 not found at address 0x23. Check wiring.")
            sys.exit(1)

        while _running:
            try:
                lux = read_lux(bus)
                print(f"Illuminance: {lux:.2f} lux")
            except OSError as e:
                print(f"Error: I2C communication failed: {e}")
                sys.exit(2)

            for _ in range(int(READ_INTERVAL_S * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

