#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpad A (GPIO5) = bit 4 (red)
Touchpad B (GPIO6) = bit 2 (green)
Touchpad C (GPIO12) = bit 1 (blue)

Discrete LEDs: green (GPIO7), blue (GPIO8)
HT16K33 display: I2C 0x70
APA102 strip: 7 pixels, data GPIO10, clock GPIO11
Piezo buzzer: GPIO13
"""

import signal
import sys
import time

import board
import busio
import digitalio
from gpiozero import Button

try:
    import adafruit_ht16k33.ht16k33 as HT16K33
except Exception:
    HT16K33 = None

try:
    import adafruit_apa102.apa102 as APA102
except Exception:
    APA102 = None

try:
    from adafruit_circuitpython_actuators.buzzer import Piezo
except Exception:
    Piezo = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
TOUCH_PINS = [board.D5, board.D6, board.D12]   # A, B, C
LED_PINS = [board.D7, board.D8]                 # green, blue
BUZZER_PIN = board.D13

DISPLAY_ADDR = 0x70
NUM_PIXELS = 7

# Bit weights: A=4, B=2, C=1
BIT_WEIGHTS = [4, 2, 1]

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_touch_buttons = []
_leds = []
_display = None
_strip = None
_buzzer = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _display, _strip, _buzzer, _leds
    for led in _leds:
        try:
            led.off()
        except Exception:
            pass
    for led in _leds:
        try:
            led.close()
        except Exception:
            pass
    _leds.clear()
    if _display is not None:
        try:
            _display.fill(0)
            _display.show()
        except Exception:
            pass
    if _strip is not None:
        try:
            _strip.fill((0, 0, 0))
            _strip.show()
        except Exception:
            pass
    if _buzzer is not None:
        try:
            _buzzer.off()
        except Exception:
            pass


def _init_touchpads():
    global _touch_buttons
    buttons = []
    for idx, pin in enumerate(TOUCH_PINS):
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.05)
            buttons.append(btn)
        except Exception as exc:
            print(f"Warning: failed to init touchpad {idx}: {exc}", file=sys.stderr)
    return buttons


def _init_leds():
    global _leds
    leds = []
    for pin in LED_PINS:
        try:
            led = digitalio.DigitalInOut(pin)
            led.direction = digitalio.Direction.OUTPUT
            led.value = False
            leds.append(led)
        except Exception as exc:
            print(f"Warning: failed to init LED: {exc}", file=sys.stderr)
    return leds


def _init_display():
    global _display
    if HT16K33 is None:
        print("Warning: adafruit_ht16k33 not available; display disabled.", file=sys.stderr)
        return None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        disp = HT16K33.HT16K33(i2c, address=DISPLAY_ADDR)
        disp.brightness = 0.5
        disp.fill(0)
        disp.show()
        return disp
    except Exception as exc:
        print(f"Warning: failed to init display: {exc}", file=sys.stderr)
        return None


def _init_strip():
    global _strip
    if APA102 is None:
        print("Warning: adafruit_apa102 not available; strip disabled.", file=sys.stderr)
        return None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        strip = APA102.APA102(i2c, NUM_PIXELS)
        strip.brightness = 0.5
        strip.fill((0, 0, 0))
        strip.show()
        return strip
    except Exception as exc:
        print(f"Warning: failed to init strip: {exc}", file=sys.stderr)
        return None


def _init_buzzer():
    global _buzzer
    if Piezo is None:
        print("Warning: adafruit_circuitpython_actuators.buzzer not available; buzzer disabled.", file=sys.stderr)
        return None
    try:
        buzzer = Piezo(BUZZER_PIN)
        buzzer.off()
        return buzzer
    except Exception as exc:
        print(f"Warning: failed to init buzzer: {exc}", file=sys.stderr)
        return None


def _value_to_color(bit_states):
    """Map bit states to RGB: A=red, B=green, C=blue."""
    r = 255 if bit_states[0] else 0
    g = 255 if bit_states[1] else 0
    b = 255 if bit_states[2] else 0
    return (r, g, b)


def _update_strip(bit_states, value):
    if _strip is None:
        return
    try:
        if value == 0:
            _strip.fill((10, 10, 10))
        elif value == 7:
            _strip.fill((255, 255, 255))
        else:
            color = _value_to_color(bit_states)
            _strip.fill([color if i == value else (0, 0, 0) for i in range(NUM_PIXELS)])
        _strip.show()
    except Exception as exc:
        print(f"Strip update error: {exc}", file=sys.stderr)


def _update_display(bit_states, value):
    if _display is None:
        return
    try:
        _display.fill(0)
        _display.print_hex(value)
        _display.show()
    except Exception as exc:
        print(f"Display update error: {exc}", file=sys.stderr)


def _update_leds(bit_states):
    if not _leds:
        return
    try:
        _leds[0].value = bool(bit_states[1])   # green (bit 2)
        _leds[1].value = bool(bit_states[2])   # blue  (bit 1)
    except Exception as exc:
        print(f"LED update error: {exc}", file=sys.stderr)


def _play_tone(value):
    if _buzzer is None:
        return
    try:
        midi_note = 60 + value
        freq = 440.0 * (2.0 ** ((midi_note - 69) / 12.0))
        _buzzer.frequency = freq
        _buzzer.value = 0.5
        time.sleep(0.5)
        _buzzer.off()
    except Exception as exc:
        print(f"Buzzer error: {exc}", file=sys.stderr)


def _handle_touch(idx):
    """Toggle the bit at idx and refresh all outputs."""
    global _bit_states
    if idx < len(_bit_states):
        _bit_states[idx] = not _bit_states[idx]
    value = sum(w * s for w, s in zip(BIT_WEIGHTS, _bit_states))
    _update_strip(_bit_states, value)
    _update_display(_bit_states, value)
    _update_leds(_bit_states)
    _play_tone(value)


def main():
    global _bit_states, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _bit_states = [False, False, False]

    _touch_buttons = _init_touchpads()
    _leds = _init_leds()
    _display = _init_display()
    _strip = _init_strip()
    _buzzer = _init_buzzer()

    if not _touch_buttons:
        print("Warning: no touchpads initialized; exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            for btn in _touch_buttons:
                if btn.is_pressed:
                    _handle_touch(btn.pin.number - TOUCH_PINS[0].number)
                    break
            time.sleep(0.01)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

