    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO setup error on pin {pin}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}")
        sys.exit(1)

def turn_on(led):
    """Turns the LED on for 2 seconds."""
    try:
        led.on()
        time.sleep(2)
    except Exception as e:
        print(f"Error turning LED on: {e}")

def turn_off(led):
    """Turns the LED off for 2 seconds."""
    try:
        led.off()
        time.sleep(2)
    except Exception as e:
        print(f"Error turning LED off: {e}")

def main():
