#!/usr/bin/env python3
"""
LED Blink on GPIO17 using gpiozero.

Wiring: LED anode -> 330 ohm resistor -> GPIO17 (physical pin 11)
        LED cathode -> GND (physical pin 6)
"""

import time
import sys
from gpiozero import LED
from gpiozero.exc import GPIODeviceError

def main():
    # Create LED object inside try block so it is not left dangling on error
    try:
        led = LED(17)
    except GPIODeviceError as e:
        print(f"Failed to initialize LED on GPIO17: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during LED initialization: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            led.on()
            print("LED is ON")
            time.sleep(1)

            led.off()
            print("LED is OFF")
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram stopped by user")
    except GPIODeviceError as e:
        print(f"GPIO device error during operation: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Ensure LED is off before exiting
        try:
            led.off()
        except Exception:
            pass

if __name__ == "__main__":
    main()

