import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0

def main():
    try:
        led = LED(LED_PIN)
    except (BadPinFactory, GPIOZeroError) as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            led.on()
            time.sleep(ON_DURATION)
            led.off()
            time.sleep(OFF_DURATION)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"Error during blink loop: {e}", file=sys.stderr)
    finally:
        try:
            led.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

