import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(0)

LED_PIN = 18
BLINK_COUNT = 5
ON_DURATION = 1.0
OFF_DURATION = 1.0


def blink_led(led: LED, count: int, on_time: float, off_time: float) -> None:
    """Blink the LED `count` times with the specified on/off durations."""
    for i in range(count):
        print(f"Blinking LED (cycle {i + 1}/{count})")
        led.on()
        time.sleep(on_time)
        led.off()
        time.sleep(off_time)


def main() -> None:
    led = None
    try:
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO {LED_PIN} (BCM). Starting blink sequence...")
        blink_led(led, BLINK_COUNT, ON_DURATION, OFF_DURATION)
        print("Blink sequence completed successfully.")
    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting...")
    except (GPIOZeroError, BadPinFactory) as exc:
        print(f"GPIO error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        if led is not None:
            try:
                led.off()
                led.close()
                print("LED turned off and GPIO resources released.")
            except Exception as cleanup_exc:
                print(f"Warning during cleanup: {cleanup_exc}")


if __name__ == "__main__":
    main()

