import RPi.GPIO as GPIO
import time
import sys

# Pin assignments (BCM numbering)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

PWM_FREQ = 200  # Hz

# Preset RGB values (R, G, B) with each component in [0, 255]
COLORS = [
    (255, 0, 0),   # Red
    (0, 255, 0),   # Green
    (0, 0, 255),   # Blue
    (255, 255, 0), # Yellow
    (0, 255, 255), # Cyan
]


def setup_gpio():
    """Configure GPIO mode and set pins as outputs."""
    try:
        GPIO.setmode(GPIO.BCM)
    except Exception as exc:
        print(f"Error setting GPIO mode: {exc}", file=sys.stderr)
        sys.exit(1)

    for pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as exc:
            print(f"Error setting up GPIO{pin}: {exc}", file=sys.stderr)
            GPIO.cleanup()
            sys.exit(1)


def create_pwm_channels():
    """Create and start PWM channels at 200 Hz."""
    pwm_channels = {}
    for pin, name in (
        (RED_PIN, "red"),
        (GREEN_PIN, "green"),
        (BLUE_PIN, "blue"),
    ):
        try:
            pwm = GPIO.PWM(pin, PWM_FREQ)
            pwm.start(0)
            pwm_channels[name] = pwm
        except Exception as exc:
            print(f"Error creating PWM on {name} (GPIO{pin}): {exc}", file=sys.stderr)
            cleanup_gpio()
            sys.exit(1)
    return pwm_channels


def set_color(pwm_channels, red, green, blue):
    """Set the RGB LED to the given color (0-255 each)."""
    try:
        pwm_channels["red"].ChangeDutyCycle(red)
        pwm_channels["green"].ChangeDutyCycle(green)
        pwm_channels["blue"].ChangeDutyCycle(blue)
    except Exception as exc:
        print(f"Error setting color: {exc}", file=sys.stderr)


def cleanup_gpio():
    """Stop all PWM channels and release GPIO resources."""
    print("Cleaning up GPIO...")
    try:
        GPIO.cleanup()
    except Exception as exc:
        print(f"Error during GPIO cleanup: {exc}", file=sys.stderr)


def main():
    setup_gpio()
    pwm_channels = create_pwm_channels()

    try:
        for red, green, blue in COLORS:
            print(f"Setting color: R={red}, G={green}, B={blue}")
            set_color(pwm_channels, red, green, blue)
            time.sleep(1)

        print("Color sequence complete.")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")

    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

