import argparse
import json
import logging
import signal
import sys
import time
import urllib.request
import urllib.error
from collections import deque
from pathlib import Path

import numpy as np
import tflite_runtime.interpreter as tflite
from smbus2 import SMBus


class SensorReadError(Exception):
    pass


class ModelLoadError(Exception):
    pass


class AlertError(Exception):
    pass


class ConfigurationError(Exception):
    pass


DEFAULT_CONFIG = {
    "i2c_bus": 1,
    "vibration_address": 0x1D,
    "current_address": 0x40,
    "scale_factor": 0.001,
    "shunt_resistance": 0.1,
    "failure_threshold": 0.8,
    "alert_endpoint": "http://example.com/alerts",
    "model_path": "model.tflite",
    "log_file": "predictive_maintenance.log",
    "simulate": False,
}


def load_config(config_file: str) -> dict:
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        required = ["i2c_bus", "vibration_address", "current_address", "scale_factor", "shunt_resistance",
                    "failure_threshold", "alert_endpoint", "model_path", "log_file", "simulate"]
        for key in required:
            if key not in cfg:
                raise ConfigurationError(f"Missing required config key: {key}")
        return cfg
    except FileNotFoundError:
        raise ConfigurationError(f"Config file not found: {config_file}")
    except json.JSONDecodeError as e:
        raise ConfigurationError(f"Invalid JSON in config file: {e}")
    except Exception as e:
        raise ConfigurationError(f"Error loading config: {e}")


def read_vibration(bus: SMBus, address: int, simulate: bool) -> tuple:
    if simulate:
        return (np.random.uniform(-100, 100) * 0.001,
                np.random.uniform(-100, 100) * 0.001,
                np.random.uniform(-100, 100) * 0.001)
    try:
        x = bus.read_word_data(address, 0x00)
        y = bus.read_word_data(address, 0x02)
        z = bus.read_word_data(address, 0x04)
        x = (x >> 8) | (x << 8)
        y = (y >> 8) | (y << 8)
        z = (z >> 8) | (z << 8)
        return (x * 0.001, y * 0.001, z * 0.001)
    except OSError as e:
        raise SensorReadError(f"Failed to read vibration sensor at 0x{address:02X}: {e}")


def read_current(bus: SMBus, address: int, simulate: bool) -> float:
    if simulate:
        return np.random.uniform(-100, 100)
    try:
        data = bus.read_word_data(address, 0x01)
        data = (data >> 8) | (data << 8)
        current = (data * 0.01) / 0.1
        return current
    except OSError as e:
        raise SensorReadError(f"Failed to read current sensor at 0x{address:02X}: {e}")


def load_model(model_path: str) -> tflite.Interpreter:
    try:
        p = Path(model_path)
        if not p.is_file():
            raise ModelLoadError(f"Model file not found: {model_path}")
        interpreter = tflite.Interpreter(model_path=str(p))
        interpreter.allocate_tensors()
        return interpreter
    except Exception as e:
        raise ModelLoadError(f"Failed to load TFLite model: {e}")


def run_inference(interpreter: tflite.Interpreter, x: float, y: float, z: float, current: float) -> float:
    input_details = interpreter.get_input_details()
    output_details = interpreter.get_output_details()
    input_data = np.array([[x, y, z, current]], dtype=np.float32)
    interpreter.set_tensor(input_details[0]["index"], input_data)
    interpreter.invoke()
    output_data = interpreter.get_tensor(output_details[0]["index"])
    return float(output_data[0][0])


def send_alert(endpoint: str, probability: float) -> None:
    try:
        data = json.dumps({"failure_probability": round(probability, 4)}).encode("utf-8")
        req = urllib.request.Request(endpoint, data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=5) as resp:
            if resp.getcode() != 200:
                logging.warning(f"Alert sent but server returned {resp.getcode()}")
    except urllib.error.URLError as e:
        raise AlertError(f"Failed to send alert to {endpoint}: {e}")
    except Exception as e:
        raise AlertError(f"Failed to send alert: {e}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Predictive Maintenance System for Raspberry Pi")
    parser.add_argument("--config", default=None, help="Path to JSON configuration file")
    args = parser.parse_args()

    config = DEFAULT_CONFIG.copy()
    if args.config:
        try:
            config.update(load_config(args.config))
        except ConfigurationError as e:
            print(f"Configuration error: {e}", file=sys.stderr)
            sys.exit(1)

    log_file = config["log_file"]
    logging.basicConfig(filename=log_file, level=logging.INFO,
                        format="%(asctime)s - %(levelname)s - %(message)s")

    bus: SMBus | None = None
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, signal_handler)

    try:
        bus = SMBus(config["i2c_bus"])
    except OSError as e:
        logging.error(f"Failed to open I2C bus {config['i2c_bus']}: {e}")
        sys.exit(1)

    try:
        interpreter = load_model(config["model_path"])
    except ModelLoadError as e:
        logging.error(f"Model load error: {e}")
        sys.exit(1)

    window_size = 5
    x_window = deque(maxlen=window_size)
    y_window = deque(maxlen=window_size)
    z_window = deque(maxlen=window_size)
    current_window = deque(maxlen=window_size)

    try:
        while running:
            try:
                if config["simulate"]:
                    vx, vy, vz = read_vibration(bus, config["vibration_address"], True)
                    current = read_current(bus, config["current_address"], True)
                else:
                    vx, vy, vz = read_vibration(bus, config["vibration_address"], False)
                    current = read_current(bus, config["current_address"], False)

                x_window.append(vx)
                y_window.append(vy)
                z_window.append(vz)
                current_window.append(current)

                x_avg = np.mean(x_window)
                y_avg = np.mean(y_window)
                z_avg = np.mean(z_window)
                current_avg = np.mean(current_window)

                probability = run_inference(interpreter, x_avg, y_avg, z_avg, current_avg)

                logging.info(f"X: {x_avg:.4f}, Y: {y_avg:.4f}, Z: {z_avg:.4f}, Current: {current_avg:.4f}, "
                             f"Probability: {probability:.4f}")

                if probability > config["failure_threshold"]:
                    logging.warning(f"Potential failure detected! Probability: {probability:.4f}")
                    try:
                        send_alert(config["alert_endpoint"], probability)
                    except AlertError as e:
                        logging.error(f"Alert error: {e}")

            except SensorReadError as e:
                logging.error(f"Sensor read error: {e}")
                try:
                    bus.close()
                except Exception:
                    pass
                try:
                    bus = SMBus(config["i2c_bus"])
                except OSError as e:
                    logging.error(f"Failed to re-open I2C bus: {e}")
                    time.sleep(5)
            except Exception as e:
                logging.error(f"Unexpected error: {e}")

            time.sleep(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

