import signal
import sys

SERVO_PIN = 18
PWM_FREQ = 50
DUTY_MIN = 2.5   # 0 degrees
DUTY_MAX = 12.5  # 180 degrees
MIN_HR = 40
MAX_HR = 180

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SERVO_PIN, GPIO.OUT)

def start_pwm():
    pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
    pwm.start(0)
    return pwm

def angle_to_duty(angle):
    if not 0 <= angle <= 180:
        raise ValueError(f"Angle {angle} out of range 0-180")
    return DUTY_MIN + (angle / 180.0) * (DUTY_MAX - DUTY_MIN)

def heart_rate_to_angle(heart_rate):
    if not MIN_HR <= heart_rate <= MAX_HR:
        raise ValueError(f"Heart rate {heart_rate} out of range {MIN_HR}-{MAX_HR}")
    return (heart_rate - MIN_HR) * (180 / (MAX_HR - MIN_HR))

def set_servo_angle(pwm, angle):
    duty = angle_to_duty(angle)
    pwm.ChangeDutyCycle(duty)
    time.sleep(0.02)
    pwm.ChangeDutyCycle(0)

def cleanup(pwm):
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    pwm = None
    try:
        pwm = start_pwm()
        readings = [62, 75, 88, 110, 95]
        for hr in readings:
            if not _running:
                break
            try:
                angle = heart_rate_to_angle(hr)
                set_servo_angle(pwm, angle)
                print(f"Heart Rate: {hr} bpm -> Angle: {angle:.1f} degrees")
            except ValueError as e:
                print(f"Skipping invalid reading: {e}", file=sys.stderr)
            time.sleep(0.8)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup(pwm)

if __name__ == "__main__":
    main()

