import os
import time
import json
import gzip
import threading
import datetime
import random
import signal
import sys

try:
    from smbus2 import SMBus
except ImportError:
    SMBus = None

# MCP39F511N I2C addresses
SENSOR_ADDRESSES = [0x3B, 0x3C, 0x3D]

# Global state
log_file = None
log_file_lock = threading.Lock()
running = True


def signal_handler(signum, frame):
    global running
    running = False


def get_simulated_data():
    """Return a dict with simulated MCP39F511N readings."""
    return {
        "active_power": round(random.uniform(50, 200), 2),
        "voltage": round(random.uniform(220, 240), 2),
        "current": round(random.uniform(0.2, 1.0), 3),
        "frequency": round(random.uniform(59.5, 60.5), 2),
        "power_factor": round(random.uniform(0.8, 1.0), 3),
        "timestamp": datetime.datetime.now().isoformat(),
    }


def log_data(data):
    """Append a JSON line to the log file, rotating and compressing as needed."""
    global log_file
    try:
        with log_file_lock:
            today = datetime.date.today().strftime("%Y-%m-%d")
            log_filename = f"energy_log_{today}.json"
            log_path = os.path.join(os.getcwd(), log_filename)

            # Rotate if file exceeds 1 MB
            if os.path.exists(log_path) and os.path.getsize(log_path) > 1024 * 1024:
                try:
                    os.rename(log_path, f"{log_filename}_{datetime.datetime.now().strftime('%H%M%S')}.json.gz")
                    with gzip.open(f"{log_filename}_{datetime.datetime.now().strftime('%H%M%S')}.json.gz", "wt") as f:
                        f.write(json.dumps(data))
                except OSError as e:
                    print(f"Error compressing log file: {e}")
                    return

            # Create directory if needed
            log_dir = os.path.dirname(log_path)
            if log_dir and not os.path.exists(log_dir):
                try:
                    os.makedirs(log_dir, exist_ok=True)
                except OSError as e:
                    print(f"Error creating log directory: {e}")
                    return

            # Open log file with exclusive lock
            with open(log_path, "a") as f:
                f.write(json.dumps(data) + "\n")

            # Set permissions to 0o600
            try:
                os.chmod(log_path, 0o600)
            except OSError as e:
                print(f"Error setting file permissions: {e}")

    except Exception as e:
        print(f"Error logging data: {e}")


def data_acquisition_thread():
    """Background thread: acquire simulated data every 5 seconds."""
    while running:
        try:
            for addr in SENSOR_ADDRESSES:
                data = get_simulated_data()
                data["sensor_id"] = addr
                log_data(data)
        except Exception as e:
            print(f"Error in acquisition thread: {e}")
        time.sleep(5)


def view_current_readings():
    """Display the most recent reading for each sensor."""
    try:
        with log_file_lock:
            if not os.path.exists("energy_log_*.json"):
                print("No log data available.")
                return
            recent_files = [
                f for f in os.listdir()
                if f.startswith("energy_log_") and f.endswith(".json")
            ]
            if not recent_files:
                print("No log data available.")
                return
            recent_files.sort(key=os.path.getmtime, reverse=True)
            recent_file = recent_files[0]
            with open(recent_file, "r") as f:
                lines = f.readlines()
            if not lines:
                print("No log data available.")
                return
            recent_data = json.loads(lines[-1])
            print(f"Sensor 0x{recent_data['sensor_id']:02X} - {recent_data}")
    except Exception as e:
        print(f"Error viewing current readings: {e}")


def view_data_by_date(date):
    """Display all readings for a given date."""
    try:
        date_str = date.strftime("%Y-%m-%d")
        pattern = f"energy_log_{date_str}*.json"
        files = [f for f in os.listdir() if f.startswith(f"energy_log_{date_str}") and f.endswith(".json")]
        if not files:
            print("No data found for this date.")
            return
        all_data = []
        for f in files:
            with open(f, "r") as g:
                for line in g:
                    try:
                        all_data.append(json.loads(line))
                    except json.JSONDecodeError:
                        continue
        if not all_data:
            print("No data found for this date.")
            return
        for d in all_data:
            print(f"Sensor 0x{d['sensor_id']:02X} - {d}")
    except Exception as e:
        print(f"Error viewing data by date: {e}")


def analyze_data(sensor_id, date):
    """Display min/max/avg active power for a sensor on a given date."""
    try:
        date_str = date.strftime("%Y-%m-%d")
        pattern = f"energy_log_{date_str}*.json"
        files = [f for f in os.listdir() if f.startswith(f"energy_log_{date_str}") and f.endswith(".json")]
        if not files:
            print("No data found for this date.")
            return
        all_data = []
        for f in files:
            with open(f, "r") as g:
                for line in g:
                    try:
                        d = json.loads(line)
                        if d["sensor_id"] == sensor_id:
                            all_data.append(d)
                    except json.JSONDecodeError:
                        continue
        if not all_data:
            print("No data found for this sensor and date.")
            return
        active_powers = [d["active_power"] for d in all_data]
        print(f"Sensor 0x{sensor_id:02X} - Min: {min(active_powers):.2f} W, Max: {max(active_powers):.2f} W, Avg: {sum(active_powers) / len(active_powers):.2f} W")
    except Exception as e:
        print(f"Error analyzing data: {e}")


def main():
    global log_file

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start acquisition thread
    acquisition_thread = threading.Thread(target=data_acquisition_thread, daemon=True)
    acquisition_thread.start()

    while running:
        print("\nOptions:")
        print("1. View current readings")
        print("2. View data for a given date")
        print("3. Analyze data (min/max/avg active power)")
        print("4. Quit")

        choice = input("Enter your choice: ").strip()

        if choice == "1":
            view_current_readings()
        elif choice == "2":
            try:
                date = datetime.datetime.strptime(input("Enter date (YYYY-MM-DD): ").strip(), "%Y-%m-%d").date()
                view_data_by_date(date)
            except ValueError:
                print("Invalid date format. Please use YYYY-MM-DD.")
        elif choice == "3":
            try:
                sensor_id = int(input("Enter sensor ID (hex, e.g., 0x3B): ").strip(), 16)
                date = datetime.datetime.strptime(input("Enter date (YYYY-MM-DD): ").strip(), "%Y-%m-%d").date()
                analyze_data(sensor_id, date)
            except ValueError:
                print("Invalid input. Please enter a valid hex sensor ID and date.")
        elif choice == "4":
            running = False
            break
        else:
            print("Invalid choice. Please try again.")

    print("Exiting...")


if __name__ == "__main__":
    main()

