import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
LED_PIN = 18
READING_THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
SENSOR_FAILURE_PROBABILITY = 0.1
MAX_RETRIES = 1

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def simulate_water_quality_reading():
    """Simulates a water quality reading as a percentage (0-100)."""
    return random.randint(0, 100)

def validate_reading(reading):
    """Validates the simulated water quality reading."""
    if not isinstance(reading, (int, float)):
        raise ValueError("Invalid reading type. Expected int or float.")
    if not 0 <= reading <= 100:
        raise ValueError("Invalid reading value. Must be between 0 and 100.")

def control_led(led, reading):
    """Controls the LED based on the water quality reading."""
    if reading < READING_THRESHOLD:
        led.on()
        print("Water quality is low! LED ON")
    else:
        led.off()
        print("Water quality is acceptable. LED OFF")

def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    led = None
    try:
        # Initialize LED with error handling
        try:
            led = LED(LED_PIN)
            print(f"LED initialized on GPIO{LED_PIN} (BCM).")
        except GPIOZeroError as e:
            print(f"Error initializing LED on GPIO{LED_PIN}: {e}")
            sys.exit(1)

        for i in range(NUM_READINGS):
            if not _running:
                print("Monitoring interrupted by user.")
                break

            reading = None
            for attempt in range(MAX_RETRIES + 1):
                if random.random() < SENSOR_FAILURE_PROBABILITY:
                    print(f"Reading {i+1}: Sensor failure simulated.")
                else:
                    try:
                        reading = simulate_water_quality_reading()
                        print(f"Reading {i+1}: Simulated water quality = {reading}%")
                        break
                    except Exception as e:
                        print(f"Reading {i+1}: Error simulating reading: {e}")

                if attempt < MAX_RETRIES:
                    print(f"Reading {i+1}: Retrying in {DELAY_SECONDS} seconds...")
                    time.sleep(DELAY_SECONDS)

            if reading is not None:
                try:
                    validate_reading(reading)
                    control_led(led, reading)
                except ValueError as e:
                    print(f"Reading {i+1}: Validation error: {e}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if led is not None:
            led.close()
            print("LED resource released.")
        print("Program finished.")

if __name__ == "__main__":
    main()

