import adafruit_tcs34725
from PIL import Image

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_color_sensor(i2c_bus):
    try:
        sensor = adafruit_tcs34725.TCS34725(i2c_bus, address=0x29)
        sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        sensor.gain = adafruit_tcs34725.GAIN_4X
        return sensor
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}")
        return None

def get_sensor_color_data(color_sensor):
    try:
        r, g, b, c = color_sensor.color_rgb_bytes
        return r, g, b, c
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return 0, 0, 0, 0

def find_dominant_image_color(image_path):
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(10000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        print(f"Image file not found: {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    try:
        while running:
            r, g, b, c = get_sensor_color_data(color_sensor)
            print(f"Sensor Data - R: {r}, G: {g}, B: {b}, Clear: {c}")

            dominant_color = find_dominant_image_color('image.jpg')
            print(f"Dominant Image Color: {dominant_color}")

            time.sleep(1)
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

