#!/usr/bin/env python3
"""
Wildlife tracking system command handler for Raspberry Pi.
Listens on 127.0.0.1:9099 for TCP connections and accepts remote control commands.
Supports start/stop tracking and reporting GPS coordinates.
"""

import socket
import json
import logging
import signal
import sys
import time

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    stream=sys.stderr
)

# Constants
LISTEN_HOST = '127.0.0.1'
LISTEN_PORT = 9099
SOCKET_TIMEOUT = 2  # seconds

# Global state
tracking_state = 'stopped'
gps_module = None
gps_serial_port = None
gps_i2c_bus = None

# Graceful shutdown flag
running = True


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for clean shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def initialize_gps():
    """Initialize the GPS module, trying UART first, then I2C, then simulate."""
    global gps_module, gps_serial_port, gps_i2c_bus

    # Try UART (pyserial)
    try:
        import serial
        gps_serial_port = serial.Serial(
            port='/dev/serial0',
            baudrate=9600,
            timeout=1
        )
        logging.info("GPS initialized via UART on /dev/serial0")
        gps_module = 'uart'
        return
    except serial.SerialException as e:
        logging.warning(f"UART GPS init failed: {e}")
    except ImportError:
        logging.warning("pyserial not installed, skipping UART GPS")

    # Try I2C (smbus2)
    try:
        import smbus2
        gps_i2c_bus = smbus2.SMBus(1)
        # Verify module presence by reading status register (0x06)
        status = gps_i2c_bus.read_byte_data(0x42, 0x06)
        if status & 0x01:
            logging.info("GPS initialized via I2C at address 0x42")
            gps_module = 'i2c'
            return
        else:
            logging.warning("I2C GPS at 0x42 reported not ready")
    except Exception as e:
        logging.warning(f"I2C GPS init failed: {e}")

    # Fallback to simulated GPS
    logging.info("No GPS module detected, using simulated coordinates")
    gps_module = 'simulated'


def read_gps_position():
    """Read GPS coordinates from the configured module.
    Returns (latitude, longitude) or (None, None) on failure."""
    if gps_module == 'simulated':
        return 37.7749, -122.4194

    try:
        if gps_module == 'uart':
            # Read NMEA sentence (e.g., GPGSV)
            data = gps_serial_port.readline()
            if not data:
                return None, None
            sentence = data.decode('utf-8', errors='ignore').strip()
            if not sentence.startswith('$GPGSV'):
                return None, None
            # Parse for lat/lon (simplified)
            parts = sentence.split(',')
            if len(parts) < 4:
                return None, None
            lat_raw = parts[2]
            lon_raw = parts[4]
            if not lat_raw or not lon_raw:
                return None, None
            # Convert to float (basic parsing)
            latitude = float(lat_raw)
            longitude = float(lon_raw)
            return latitude, longitude
        elif gps_module == 'i2c':
            # Read lat/lon registers (example: 0x00-0x03 for lat, 0x04-0x07 for lon)
            # This is a simplified example; real implementation would use proper I2C protocol
            return 37.7749, -122.4194
        else:
            return None, None
    except Exception as e:
        logging.error(f"GPS read error: {e}")
        return None, None


def handle_command(command_text):
    """Process a single command received from a client.
    Returns the response string or None on error."""
    global tracking_state

    try:
        command = json.loads(command_text)
        action = command.get('action')

        if action == 'start':
            tracking_state = 'running'
            logging.info("Tracking started")
            return json.dumps({'status': 'ok', 'state': 'running'})
        elif action == 'stop':
            tracking_state = 'stopped'
            logging.info("Tracking stopped")
            return json.dumps({'status': 'ok', 'state': 'stopped'})
        elif action == 'report':
            latitude, longitude = read_gps_position()
            if latitude is not None and longitude is not None:
                return json.dumps({'status': 'ok', 'coordinates': {'lat': latitude, 'lon': longitude}})
            else:
                return json.dumps({'status': 'error', 'message': 'GPS read failed'})
        else:
            return json.dumps({'status': 'error', 'message': 'Invalid action'})
    except json.JSONDecodeError:
        logging.error("Invalid JSON command received")
        return json.dumps({'status': 'error', 'message': 'Invalid JSON'})
    except Exception as e:
        logging.error(f"Command handling error: {e}")
        return json.dumps({'status': 'error', 'message': 'Internal error'})


def cleanup():
    """Release all resources."""
    global gps_serial_port, gps_i2c_bus
    if gps_serial_port:
        try:
            gps_serial_port.close()
            logging.info("UART GPS port closed")
        except Exception as e:
            logging.error(f"Error closing UART port: {e}")
        gps_serial_port = None
    if gps_i2c_bus:
        try:
            gps_i2c_bus.close()
            logging.info("I2C GPS bus closed")
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
        gps_i2c_bus = None


def main():
    """Main entry point: listen for connections and handle commands."""
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPS
    initialize_gps()

    # Create and bind socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind((LISTEN_HOST, LISTEN_PORT))
        server_socket.listen(1)
        server_socket.settimeout(SOCKET_TIMEOUT)
        logging.info(f"Listening on {LISTEN_HOST}:{LISTEN_PORT}")
    except socket.error as e:
        logging.error(f"Socket bind/listen failed: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                client_connection, client_address = server_socket.accept()
                logging.info(f"Accepted connection from {client_address}")
            except socket.timeout:
                continue
            except socket.error as e:
                if running:
                    logging.error(f"Accept error: {e}")
                continue

            try:
                # Receive command
                try:
                    command_data = client_connection.recv(1024)
                    if not command_data:
                        logging.warning("Empty response from client")
                        client_connection.close()
                        continue
                    command_text = command_data.decode('utf-8')
                except socket.timeout:
                    logging.warning("Socket timeout during recv")
                    client_connection.close()
                    continue
                except UnicodeDecodeError:
                    logging.warning("Invalid encoding from client")
                    client_connection.close()
                    continue

                # Process and send response
                response = handle_command(command_text)
                try:
                    client_connection.sendall(response.encode('utf-8'))
                except socket.error as e:
                    logging.error(f"Send error: {e}")
                    client_connection.close()
                    continue

                client_connection.close()
                logging.info(f"Connection closed, response sent")

            except Exception as e:
                logging.error(f"Connection handling error: {e}")
                try:
                    client_connection.close()
                except Exception:
                    pass

    finally:
        cleanup()
        server_socket.close()
        logging.info("Server shutdown complete")


if __name__ == "__main__":
    main()

