import time
import sys
from gpiozero import LED
from gpiozero.exc import GPIODeviceError

LED_PIN = 17
MOISTURE_THRESHOLD = 30
INITIAL_MOISTURE = 50
RESET_MOISTURE = 60


def main():
    led = None
    try:
        led = LED(LED_PIN)
    except GPIODeviceError as e:
        print(f"Error: Failed to initialize LED on GPIO {LED_PIN}: {e}")
        sys.exit(1)

    moisture = INITIAL_MOISTURE

    try:
        while True:
            print(f"Moisture: {moisture}")

            if moisture < MOISTURE_THRESHOLD:
                if not led.is_lit:
                    led.on()
                print("Watering started!")
            else:
                if led.is_lit:
                    led.off()
                print("Watering stopped!")

            moisture -= 1
            if moisture < 0:
                moisture = RESET_MOISTURE

            time.sleep(2)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        if led is not None:
            led.off()
            led.close()
        print("Program finished.")


if __name__ == "__main__":
    main()

