import smbus2
import time
import math
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

MPU6050_ADDRESS = 0x68
POWER_MGMT_REGISTER = 0x6B
ACCEL_XOUT_H = 0x3B

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def init_mpu6050(bus):
    try:
        bus.write_byte_data(MPU6050_ADDRESS, POWER_MGMT_REGISTER, 0x00)
        logging.info("MPU6050 initialized (wake from sleep).")
    except OSError as e:
        logging.error(f"Failed to initialize MPU6050: {e}")
        raise

def read_accel_magnitude(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDRESS, ACCEL_XOUT_H, 6)
        x = (data[0] << 8) | data[1]
        y = (data[2] << 8) | data[3]
        z = (data[4] << 8) | data[5]
        magnitude = math.sqrt(x**2 + y**2 + z**2)
        return magnitude
    except OSError as e:
        logging.error(f"I2C read error: {e}")
        return None

def detect_anomaly(magnitude, history):
    if len(history) < 10:
        return False
    mean = sum(history) / len(history)
    variance = sum((x - mean)**2 for x in history) / len(history)
    std_dev = max(variance**0.5, 1.0)
    z_score = abs(magnitude - mean) / std_dev
    return z_score > 3.0

def main():
    bus = None
    try:
        bus = smbus2.SMBus(1)
        init_mpu6050(bus)
        history = []
        for i in range(15):
            if not running:
                break
            magnitude = read_accel_magnitude(bus)
            if magnitude is not None:
                history.append(magnitude)
                if detect_anomaly(magnitude, history):
                    logging.warning(f"Anomaly detected at iteration {i}: magnitude={magnitude:.2f}")
                else:
                    logging.info(f"Normal reading at iteration {i}: magnitude={magnitude:.2f}")
            time.sleep(0.2)
    except OSError as e:
        logging.error(f"I2C bus error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
