import signal
import sys
import time

from gpiozero import AngularServo, OutputDeviceBadValue, Device
from gpiozero.pins.native import NativeFactory

# Use the native pin factory to avoid pigpio daemon dependency on Raspberry Pi OS
Device.pin_factory = NativeFactory()


class RoboticArm:
    """Control a robotic arm with three SG90 servos using gpiozero."""

    def __init__(self, base_pin=17, shoulder_pin=27, gripper_pin=22):
        self.base_servo = None
        self.shoulder_servo = None
        self.gripper_servo = None
        self._initialize_servos(base_pin, shoulder_pin, gripper_pin)

    def _initialize_servos(self, base_pin, shoulder_pin, gripper_pin):
        """Create AngularServo objects with 50 Hz PWM and 0.5-2.5 ms pulse widths."""
        try:
            self.base_servo = AngularServo(
                base_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=0.5 / 1000,
                max_pulse_width=2.5 / 1000,
                frame_width=20 / 1000,
            )
            self.shoulder_servo = AngularServo(
                shoulder_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=0.5 / 1000,
                max_pulse_width=2.5 / 1000,
                frame_width=20 / 1000,
            )
            self.gripper_servo = AngularServo(
                gripper_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=0.5 / 1000,
                max_pulse_width=2.5 / 1000,
                frame_width=20 / 1000,
            )
        except (ValueError, RuntimeError) as e:
            self.release()
            raise RuntimeError(f"Failed to initialize servos: {e}") from e

    def move_joint(self, servo, target_angle):
        """Move a single servo to target_angle, clamped to [-90, 90]."""
        if servo is None:
            raise ValueError("Servo object is None")
        try:
            clamped = max(-90, min(90, int(target_angle)))
            servo.angle = clamped
            time.sleep(0.4)
        except OutputDeviceBadValue as e:
            print(f"Error: Invalid angle for servo: {e}")
        except Exception as e:
            print(f"Error moving servo: {e}")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints to the specified pose."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos (set angle to None) so they stop holding torque."""
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.angle = None
                except Exception:
                    pass

    def cleanup(self):
        """Release servos and close underlying GPIO resources."""
        self.release()
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.close()
                except Exception:
                    pass


def run_demo_sequence(robot_arm):
    """Execute a sequence of poses for demonstration."""
    poses = [
        (0, 0, 0),
        (45, -30, 20),
        (-45, 30, -20),
        (0, 0, 0),
    ]
    for base_angle, shoulder_angle, gripper_angle in poses:
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)
        time.sleep(0.5)


def main():
    arm = RoboticArm(base_pin=17, shoulder_pin=27, gripper_pin=22)

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, cleaning up...")
        arm.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        run_demo_sequence(arm)
    except (RuntimeError, ValueError, OutputDeviceBadValue) as e:
        print(f"An error occurred: {e}")
    finally:
        arm.cleanup()


if __name__ == "__main__":
    main()

