class Laser:
    """Controls a laser module via gpiozero OutputDevice."""

    def __init__(self, pin=17):
        self.pin = pin
        try:
            self.device = OutputDevice(pin)
        except GPIOZeroError as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        self.device.on()

    def off(self):
        self.device.off()

    def close(self):
        if hasattr(self, 'device') and self.device is not None:
            self.device.close()


class Aim:
    """Controls two servo motors (horizontal and vertical) via gpiozero.Servo."""

    def __init__(self, ld, sd, hp, vp):
        if len(hp) != len(vp):
            raise ValueError("Horizontal and vertical position lists must have the same length.")
        self.hp = hp
        self.vp = vp
        self.ld = ld
        self.sd = sd
        self.laser = Laser()
        try:
            self.hservo = Servo(18)
            self.vservo = Servo(19)
        except GPIOZeroError as e:
            raise RuntimeError(f"Failed to initialize servos on GPIO18/19: {e}") from e

    def aim(self, nums):
        try:
            for b in nums:
                if not 1 <= b <= len(self.hp):
