import sys
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None


def init_relay():
    """Initialize the relay GPIO pin; exit on failure."""
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)


def cleanup(signum=None, frame=None):
    """Release the GPIO resource on exit or signal."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def relay_control():
    """Handle POST requests to toggle the relay via JSON 'state' field."""
    if relay is None:
        return jsonify({'error': 'Relay not initialized'}), 503

    try:
        req_data = request.get_json(silent=True)
    except Exception:
        return jsonify({'error': 'Invalid request'}), 400

    if not isinstance(req_data, dict):
        return jsonify({'error': 'Invalid request'}), 400

    state = req_data.get('state')
    if state is None:
        return jsonify({'error': 'Invalid request'}), 400

    if state not in ('on', 'off'):
        return jsonify({'error': 'Invalid request'}), 400

    try:
        if state == 'on':
            relay.on()
        else:
            relay.off()
    except GPIOZeroError as exc:
        return jsonify({'error': f'GPIO error: {exc}'}), 500

    return jsonify({'status': 'Relay state changed'}), 200


if __name__ == '__main__':
    init_relay()
    signal.signal(signal.SIGTERM, cleanup)
    signal.signal(signal.SIGINT, cleanup)
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        cleanup()

