import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit library not found. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants for servo control
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
SERVO_INCREMENT = 5
SERVO_DELAY = 0.04

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_servokit(i2c_bus=1, i2c_address=0x40):
    """Initializes the ServoKit with error handling."""
    try:
        kit = ServoKit(channels=16, i2c=None, address=i2c_address)
        return kit
    except OSError as e:
        print(f"I2C communication error initializing ServoKit at 0x{i2c_address:02X} on bus {i2c_bus}: {e}")
        return None
    except ValueError as e:
        print(f"Invalid parameters for ServoKit initialization: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None

def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle with validation and error handling."""
    if kit is None:
        print("ServoKit not initialized. Cannot move servo.")
        return False

    if not (0 <= servo_num < 16):
        print(f"Invalid servo number: {servo_num}. Must be between 0 and 15.")
        return False

    if not (0 <= target_angle <= 180):
        print(f"Invalid target angle: {target_angle}. Must be between 0 and 180.")
        return False

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = 0

        if target_angle > current_angle:
            angle_range = range(int(current_angle), int(target_angle) + 1, SERVO_INCREMENT)
        else:
            angle_range = range(int(current_angle), int(target_angle) - 1, -SERVO_INCREMENT)

        for angle in angle_range:
            if not _running:
                return False
            kit.servo[servo_num].angle = angle
            time.sleep(SERVO_DELAY)

        return True

    except OSError as e:
        print(f"I2C communication error moving servo {servo_num}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")
        return False

def grab_object(kit, servo_num=0):
    """Moves a servo to the grab angle."""
    print(f"Grabbing object with servo {servo_num}...")
    return move_servo(kit, servo_num, GRAB_ANGLE)

def release_object(kit, servo_num=0):
    """Moves a servo to the release angle."""
    print(f"Releasing object with servo {servo_num}...")
    return move_servo(kit, servo_num, RELEASE_ANGLE)

def cleanup(kit):
    """Safely stops all servos and releases resources."""
    if kit is not None:
        for i in range(16):
            try:
                kit.servo[i].angle = None
            except Exception:
                pass

def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        if grab_object(kit, 0):
            time.sleep(1)
            if release_object(kit, 0):
                print("Object grabbing and releasing sequence completed successfully.")
            else:
                print("Failed to release object.")
        else:
            print("Failed to grab object.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup(kit)
        print("Servo control sequence finished.")

if __name__ == "__main__":
    main()

