import logging
from gpiozero import OutputDevice

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)

# BCM GPIO pin assignments
PUMP_PIN = 20
LIGHT_PIN = 21

# Dictionary mapping plain-English intents to gpiozero OutputDevice objects
actuators = {
    "pump": OutputDevice(PUMP_PIN),
    "light": OutputDevice(LIGHT_PIN),
}


def apply_intent(intent_name: str) -> None:
    """Drive the named actuator based on the recognized intent."""
    device = actuators.get(intent_name)
    if device is None:
        logging.warning("Unknown intent: %s", intent_name)
        return

    if intent_name == "pump":
        device.on()
        logging.info("Pump turned ON")
    elif intent_name == "light":
        device.toggle()
        logging.info("Grow light toggled")
    elif intent_name == "pump_off":
        device.off()
        logging.info("Pump turned OFF")
    else:
        logging.warning("Unknown intent: %s", intent_name)


def parse_phrase(phrase: str) -> None:
    """Parse a plain-English phrase and apply the recognized intent."""
    phrase = phrase.lower().strip()
    for intent in ("pump on", "pump off", "light toggle"):
        if intent in phrase:
            apply_intent(intent.split()[0])
            return
    logging.warning("Unknown phrase: %s", phrase)


def main() -> None:
    """Process a list of test phrases and ensure safe shutdown."""
    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    try:
        for phrase in test_phrases:
            parse_phrase(phrase)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        # Turn off all actuators and release GPIO resources
        for device in actuators.values():
            try:
                device.off()
                device.close()
            except Exception as cleanup_err:
                logging.error("Error during cleanup: %s", cleanup_err)
        logging.info("Actuators shut down safely")


if __name__ == "__main__":
    main()

