    Returns:
        Number of half-steps required to reach the angle.

    Raises:
        ValueError: If angle is outside the valid range.
    """
    if not 0 <= angle_degrees <= 360:
        raise ValueError(f"Angle must be between 0 and 360, got {angle_degrees}")
    return int(round((angle_degrees / 360.0) * STEPS_PER_REVOLUTION))


def rotate_to_bearing(angle_degrees):
    """Rotate the antenna to the specified bearing using a stepper motor.

