    CONTROL_CH_1 = 0x80
    CONTROL_CH_0 = 0x40
    CONTROL_A_1 = 0x20
    CONTROL_A_0 = 0x10
    CONTROL_SQW_1 = 0x08
    CONTROL_SQW_0 = 0x04
    CONTROL_PIE = 0x02
    CONTROL_AIE = 0x01

    def __init__(self, bus_num=1, addr=0x68):
        """Initialize the DS1338 RTC.

        Args:
            bus_num: I2C bus number (default 1 for Raspberry Pi 3/4/5).
            addr: I2C address of the DS1338 (default 0x68).

        Raises:
            OSError: If the I2C bus cannot be opened or the device is absent.
        """
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as e:
            raise OSError(f"Failed to open I2C bus {bus_num}: {e}")

        # Verify device presence with a zero-length write (probe).
        try:
            self.bus.write_byte(self.addr, 0x00)
        except OSError as e:
            self._close_bus()
            raise OSError(
                f"No DS1338 found at address 0x{addr:02X} on bus {bus_num}: {e}"
            )

        # Reset the clock to a known state (00:00:00, 01/01/2000).
        self.write_all(year=20, month=1, date=1, hours=0, minutes=0, seconds=0)

    # ------------------------------------------------------------------
    # Low-level I2C helpers
    # ------------------------------------------------------------------
    def _read_register(self, reg):
        """Read a single byte from the specified register."""
        try:
            return self.bus.read_byte_data(self.addr, reg)
        except OSError as e:
            raise OSError(f"I2C read error at register 0x{reg:02X}: {e}")

    def _write_register(self, reg, value):
        """Write a single byte to the specified register."""
        try:
            self.bus.write_byte_data(self.addr, reg, value & 0xFF)
        except OSError as e:
            raise OSError(f"I2C write error at register 0x{reg:02X}: {e}")

    # ------------------------------------------------------------------
    # BCD helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _bcd_to_int(bcd):
