        return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(n):
        """Convert an integer (0-99) to two-digit BCD."""
        if not 0 <= n <= 99:
            raise ValueError(f"Value {n} out of BCD range 0-99")
        return ((n // 10) << 4) | (n % 10)

