    # Public register accessors
    # ------------------------------------------------------------------
    def read_seconds(self):
        """Read the seconds register (0-59)."""
        raw = self._read_register(self.REG_SECONDS)
        return self._bcd_to_int(raw & 0x7F)  # mask CH bit

    def read_minutes(self):
