        """Read all time/date registers and return a dict."""
        return {
            "seconds": self.read_seconds(),
            "minutes": self.read_minutes(),
            "hours": self.read_hours(),
            "date": self.read_date_day(),
            "month": self.read_month(),
            "year": self.read_year(),
        }

    def read_datetime(self, century=21):
        """Read the current datetime, applying the given century.

        Args:
            century: Century value (default 21 -> 20xx).

        Returns:
            datetime object.
        """
        y = self.read_year()
        if not 0 <= y <= 99:
