# Reads CO2 concentration from a serial sensor on a Raspberry Pi Zero W.
# Logs readings to a file with timestamps.

import serial
import time
import signal
import sys
from datetime import datetime

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# Log file path
LOG_FILE = 'co2_readings_log.txt'

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_serial(port, baud, timeout):
    """Open and return a serial connection, or None on failure."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None


def read_co2_data(serial_connection):
    """Read one line from the serial port and return the integer ppm value."""
    try:
        raw = serial_connection.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

    if not raw:
        return None  # timeout, no data

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Decode error: {e}", file=sys.stderr)
        return None

    if not data:
        return None

    try:
        return int(data)
    except ValueError:
        print(f"Invalid data received (not an integer): '{data}'", file=sys.stderr)
        return None


def log_co2_data(log_file, timestamp, co2_concentration):
    """Append a timestamped CO2 reading to the log file."""
    try:
        with open(log_file, 'a') as f:
            f.write(f"{timestamp}, {co2_concentration} ppm\n")
    except IOError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)


def main():
    """Main loop: open serial port, read CO2, log every 5 seconds."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            co2_value = read_co2_data(serial_connection)

            if co2_value is not None:
                timestamp = datetime.now().isoformat(timespec='seconds')
                print(f"CO2 Concentration: {co2_value} ppm")
                log_co2_data(LOG_FILE, timestamp, co2_value)
            else:
                print("No valid CO2 data received this cycle.", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < 5:
                time.sleep(0.1)
                slept += 0.1

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

