import serial
import serial.tools.list_ports
import time
import threading
import signal
import sys
import logging
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

stop_event = threading.Event()
serial_port = None


def signal_handler(signum, frame):
    logging.info(f"Received signal {signum}, shutting down...")
    stop_event.set()


def read_flow_rate():
    global serial_port
    while not stop_event.is_set():
        try:
            if serial_port is None or not serial_port.is_open:
                logging.info("Serial port not open; attempting to reopen.")
                serial_port = serial.Serial(
                    SERIAL_PORT,
                    BAUD_RATE,
                    timeout=TIMEOUT
                )
                if not serial_port.is_open:
                    logging.error(f"Failed to open {SERIAL_PORT}")
                    time.sleep(1)
                    continue

            raw = serial_port.readline()
            if not raw:
                continue

            data = raw.decode('ascii', errors='replace').strip()
            if not data:
                continue

            flow_rate = float(data)
            logging.info(f'Flow Rate: {flow_rate} L/min')

            timestamp = datetime.now().isoformat(timespec='seconds')
            log_entry = f'{timestamp} - Flow Rate: {flow_rate} L/min\n'
            try:
                with open(LOG_FILE, 'a') as logfile:
                    logfile.write(log_entry)
            except OSError as e:
                logging.error(f"Failed to write to log file: {e}")

        except ValueError:
            logging.warning(f"Invalid data received (not a float): {data!r}")
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            try:
                if serial_port and serial_port.is_open:
                    serial_port.close()
            except Exception:
                pass
            serial_port = None
        except Exception as e:
            logging.error(f"Unexpected error: {e}")

        stop_event.wait(1)

    if serial_port and serial_port.is_open:
        try:
            serial_port.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")


def main():
    global serial_port
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        logging.info(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        sys.exit(1)

    flow_thread = threading.Thread(target=read_flow_rate, daemon=True)
    flow_thread.start()

    try:
        while not stop_event.is_set():
            time.sleep(0.1)
    finally:
        stop_event.set()
        flow_thread.join(timeout=5)
        if serial_port and serial_port.is_open:
            try:
                serial_port.close()
            except Exception:
                pass
        logging.info("Program terminated.")


if __name__ == '__main__':
    main()

