import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPS_readings:
    latitude: float = 0.0
    latitude_dir: str = ''
    longitude: float = 0.0
    longitude_dir: str = ''
    altitude: float = 0.0
    num_satellites: int = 0

def nmea_to_decimal(value: str, direction: str) -> Tuple[float, str]:
    if not value or not direction:
        raise ValueError("Empty coordinate or direction")
    try:
        degrees = int(value[:2])
        minutes = float(value[2:])
        decimal = degrees + minutes / 60.0
        if direction in ('S', 'W'):
            decimal = -decimal
        return decimal, direction
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid NMEA coordinate '{value}' with direction '{direction}': {e}")

def parse_gpgga(data: str) -> Optional[GPS_readings]:
    if not data.startswith('$GPGGA'):
        return None
    try:
        parts = data.split(',')
        if len(parts) < 15:
            raise ValueError(f"Incomplete GPGGA sentence: {len(parts)} fields")
        if parts[2] == '0':
            return None
        lat_deg, lat_min = parts[2], parts[3]
        lon_deg, lon_min = parts[4], parts[5]
        lat, lat_dir = nmea_to_decimal(lat_deg + lat_min, parts[1])
        lon, lon_dir = nmea_to_decimal(lon_deg + lon_min, parts[3])
        alt = float(parts[9]) if parts[9] else 0.0
        sats = int(parts[7]) if parts[7] else 0
        return GPS_readings(latitude=lat, latitude_dir=lat_dir, longitude=lon, longitude_dir=lon_dir, altitude=alt, num_satellites=sats)
    except (ValueError, IndexError) as e:
        logging.error(f"Error parsing GPGGA sentence: {e} - sentence: {data}")
        return None

def verify_checksum(sentence: str) -> bool:
    if '*' not in sentence:
        return False
    body, _, csum = sentence.partition('*')
    if not body.startswith('$'):
        return False
    body = body[1:]
    try:
        expected = int(csum.strip(), 16)
    except ValueError:
        return False
    computed = 0
    for ch in body:
        computed ^= ord(ch)
    return computed == expected

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                logging.info("Disconnected from GPS")
            except serial.SerialException as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

    def read_data(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open")
            return None
        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Serial read timeout - no data received")
                return None
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                return None
            if not verify_checksum(line):
                logging.warning(f"Checksum failed for: {line}")
                return None
            return parse_gpgga(line)
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading GPS data: {e}")
            return None

def main():
    gps = GPSReader()
    shutting_down = False

    def signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True
        logging.info(f"Signal {signum} received, shutting down...")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        sys.exit(1)

    try:
        while not shutting_down:
            readings = gps.read_data()
            if readings is not None:
                logging.info(f"GPS: Lat={readings.latitude:.6f} {readings.latitude_dir}, Lon={readings.longitude:.6f} {readings.longitude_dir}, Alt={readings.altitude:.2f}m, Sats={readings.num_satellites}")
    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        gps.disconnect()

if __name__ == '__main__':
    main()

