            print(f"Error initializing ESP8266: {e}")
            self.uart = None
            raise
        except Exception as e:
            print(f"Unexpected error initializing ESP8266: {e}")
            self.uart = None
            raise

    def _send_command(self, command, delay=1, max_retries=3):
        if not self.uart or not self.uart.is_open:
            print("UART not initialized or closed.")
            return None

        try:
            self.uart.reset_input_buffer()
            self.uart.reset_output_buffer()
            self.uart.write(command.encode('utf-8'))
            self.uart.flush()

            time.sleep(delay)

            response = self._read_response()

            for _ in range(max_retries):
                if response in ('OK', 'ERROR', 'FAIL'):
                    return response
                time.sleep(delay)
                response = self._read_response()

            return None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error sending command: {e}")
            return None

    def _read_response(self):
        if not self.uart or not self.uart.is_open:
            return None

        try:
            start_time = time.time()
            response = ""

            while time.time() - start_time < self.timeout:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk.decode('utf-8', errors='ignore')
                        if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
                            return response
                else:
                    time.sleep(0.1)

            return None
        except serial.SerialException as e:
            print(f"Serial communication error reading response: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error reading response: {e}")
            return None

