        return self._send_command('AT\r\n', delay=1, max_retries=3) == 'OK'

    def restart(self):
        return self._send_command('AT+RST\r\n', delay=2, max_retries=3) == 'OK'

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        return 'WIFI GOT IP' in self._read_response(delay=5, max_retries=3)

    def close(self):
        if self.uart and self.uart.is_open:
