import serial
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class SimpleGPS:
    """
    A class to interface with a GPS module via UART on a Raspberry Pi.
    Uses pyserial for robust serial communication.
    """

    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None

    def connect(self):
        """Establishes a serial connection to the GPS module."""
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on port {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial connection error: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        """Reads a line of data from the serial port."""
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.warning("Serial connection not open. Cannot read data.")
            return None

        try:
            data = self.serial_connection.readline()
            if not data:
                return None
            return data.decode('utf-8', errors='ignore').strip()
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error during serial read: {e}")
            return None

    def parse_gga(self, data):
        """Parses a GGA sentence and returns parsed data or None."""
        if not data:
            return None

        try:
            parts = data.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (too few fields): {data}")
                return None

            talker_id = parts[0]
            if not (talker_id == '$GPGGA' or talker_id == '$GNGGA'):
                logging.debug(f"Non-GGA sentence ignored: {data}")
                return None

            utc_time = parts[1]
            latitude = self._convert_to_decimal(parts[2], parts[3])
            latitude_direction = parts[4]
            longitude = self._convert_to_decimal(parts[5], parts[6])
            longitude_direction = parts[7]
            fix_quality = parts[8]
            num_satellites = parts[9]

            if not utc_time or not latitude or not longitude:
                logging.warning("Incomplete GPS data in GGA sentence.")
                return None

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'latitude_direction': latitude_direction,
                'longitude': longitude,
                'longitude_direction': longitude_direction,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }

        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error parsing GGA sentence: {e}")
            return None

    @staticmethod
    def _convert_to_decimal(coord, direction):
        """Converts NMEA coordinate format to decimal degrees."""
        if not coord or not direction:
            return None
        try:
            degrees = int(coord[:2])
            minutes = float(coord[2:])
            decimal = degrees + (minutes / 60.0)
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            logging.error(f"Error converting coordinate '{coord}' with direction '{direction}'.")
            return None

    def close(self):
        """Closes the serial connection."""
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing serial connection: {e}")
            except OSError as e:
                logging.error(f"OS error closing serial connection: {e}")
        self.serial_connection = None


def main():
    gps = SimpleGPS(port='/dev/serial0', baudrate=9600)

    def signal_handler(sig, frame):
        logging.info("Interrupt received, shutting down...")
        gps.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while True:
            data = gps.read_data()
            if data:
                parsed = gps.parse_gga(data)
                if parsed:
                    logging.info(f"Parsed GPS data: {parsed}")
            else:
                logging.debug("No data received or read error.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.close()


if __name__ == '__main__':
    main()

