import signal
import threading
import time
import json
from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)


class SerialCommunicator:
    """Thread-safe serial communication wrapper for USB-serial instruments."""

    def __init__(self, port='/dev/ttyUSB0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port = None
        self.lock = threading.Lock()

    def open(self):
        """Open the serial port; raise on failure."""
        with self.lock:
            if self.serial_port is not None and self.serial_port.is_open:
                return
            try:
                self.serial_port = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=1.0,
                )
            except serial.SerialException as exc:
                self.serial_port = None
                raise

    def close(self):
        """Idempotently close the serial port."""
        with self.lock:
            if self.serial_port is not None:
                try:
                    if self.serial_port.is_open:
                        self.serial_port.close()
                except serial.SerialException:
                    pass
                finally:
                    self.serial_port = None

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def send(self, command):
        """Send a command string, verify bytes written, and flush."""
        with self.lock:
            if self.serial_port is None or not self.serial_port.is_open:
                raise serial.SerialException("Port not open")
            try:
                payload = command.encode('ascii')
                written = self.serial_port.write(payload)
                if written != len(payload):
                    raise serial.SerialException(
                        f"Short write: {written}/{len(payload)} bytes"
                    )
                self.serial_port.flush()
            except serial.SerialException as exc:
                raise

    def receive_line(self):
        """Read one line (up to newline) with a 1-second timeout."""
        with self.lock:
            if self.serial_port is None or not self.serial_port.is_open:
                return None
            try:
                raw = self.serial_port.readline()
                if not raw:
                    return None
                return raw.decode('ascii', errors='replace').strip()
            except serial.SerialException as exc:
                return None


class DataManager:
    """Thread-safe in-memory data store."""

    def __init__(self):
        self.data = [
            {'id': 1, 'name': 'Task 1', 'done': False},
            {'id': 2, 'name': 'Task 2', 'done': False},
        ]
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return list(self.data)

    def get_by_id(self, item_id):
        with self.lock:
            return next((item for item in self.data if item['id'] == item_id), None)

    def create(self, name, done):
        if not name or not isinstance(done, bool):
            raise ValueError("Invalid input: name must be non-empty, done must be bool")
        with self.lock:
            new_id = self.data[-1]['id'] + 1 if self.data else 1
            self.data.append({'id': new_id, 'name': name, 'done': done})
            return self.data[-1]


data_manager = DataManager()
serial_comm = SerialCommunicator()


def _signal_handler(signum, frame):
    serial_comm.close()
    app.logger.info("Received signal %s, shutting down", signum)
    raise SystemExit(0)


@app.route('/version', methods=['GET'])
def version():
    try:
        with serial_comm:
            serial_comm.send('*IDN?\n')
            response = serial_comm.receive_line()
            if response is None:
                return Response(
                    'No response from device (timeout or error)',
                    status=504,
                    mimetype='text/plain',
                )
            return Response(response, mimetype='text/plain')
    except serial.SerialException as exc:
        app.logger.error("Serial error: %s", exc)
        return Response(str(exc), status=502, mimetype='text/plain')
    except Exception as exc:
        app.logger.exception("Unexpected error: %s", exc)
        return Response(str(exc), status=500, mimetype='text/plain')


@app.route('/data', methods=['GET'])
def get_all_data():
    try:
        data = data_manager.get_all()
        return jsonify(data)
    except Exception as exc:
        app.logger.exception("Error getting all data: %s", exc)
        return Response(str(exc), status=500, mimetype='text/plain')


@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    try:
        item = data_manager.get_by_id(item_id)
        if item is None:
            return Response(f'Item with ID {item_id} not found', status=404, mimetype='text/plain')
        return jsonify(item)
    except Exception as exc:
        app.logger.exception("Error getting data by ID: %s", exc)
        return Response(str(exc), status=500, mimetype='text/plain')


@app.route('/data', methods=['POST'])
def create_data():
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)
        if not name:
            return Response('Name is required', status=400, mimetype='text/plain')
        item = data_manager.create(name, done)
        return jsonify(item), 201
    except ValueError as exc:
        return Response(str(exc), status=400, mimetype='text/plain')
    except Exception as exc:
        app.logger.exception("Error creating data: %s", exc)
        return Response(str(exc), status=500, mimetype='text/plain')


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        serial_comm.close()

