import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'


def log_access(tag_id: str) -> None:
    """Append a timestamped RFID access entry to the log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)


def main() -> None:
    rfid_reader = None
    try:
        rfid_reader = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'RFID reader initialized on {SERIAL_PORT} at {BAUD_RATE} baud.')

        while True:
            try:
                raw_line = rfid_reader.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                time.sleep(1)
                continue

            if not raw_line:
                continue

            tag_id = raw_line.decode('ascii', errors='replace').strip()
            if not tag_id:
                continue

            log_access(tag_id)
            print(f'Access granted for RFID Tag: {tag_id}')

    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    except serial.SerialException as e:
        print(f'Serial port error: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        if rfid_reader is not None and rfid_reader.is_open:
            rfid_reader.close()
            print('Serial port closed.')


if __name__ == '__main__':
    main()

