import json
import time
import signal
import sys
from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


@app.route("/version", methods=["GET"])
def version():
    """Query the connected SCPI instrument for its identification string."""
    ser = None
    try:
        ser = serial.Serial(
            port="/dev/ttyUSB0",
            baudrate=9600,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
    except serial.SerialException as exc:
        return Response(
            f"Error opening /dev/ttyUSB0: {exc}",
            status=503,
            mimetype="text/plain",
        )

    try:
        try:
            ser.write(b"*IDN?\n")
        except serial.SerialException as exc:
            return Response(
                f"Error writing to serial port: {exc}",
                status=503,
                mimetype="text/plain",
            )

        time.sleep(0.1)

        try:
            raw = ser.read(ser.in_waiting or 64)
        except serial.SerialException as exc:
            return Response(
                f"Error reading from serial port: {exc}",
                status=503,
                mimetype="text/plain",
            )

        if not raw:
            return Response(
                "No response from instrument (timeout).",
                status=503,
                mimetype="text/plain",
            )

        return Response(
            raw.decode("utf-8", errors="replace").replace("\n", "<br>"),
            mimetype="text/html",
        )
    finally:
        if ser is not None and ser.is_open:
            ser.close()


@app.route("/getdata", methods=["GET"])
def get_all_data():
    """Return the entire in-memory data store as JSON."""
    return jsonify(data_store)


@app.route("/getset/<int:item_id>", methods=["GET"])
def get_item(item_id):
    """Return a single item by id as JSON, or 404 if not found."""
    item = next((it for it in data_store if it["id"] == item_id), None)
    if item is None:
        return Response("Not Found", status=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/getpost/<int:item_id>/<name>", methods=["GET"])
def post_item(item_id, name):
    """Append a new item with the given id and name, ignoring existing id."""
    new_item = {"id": item_id, "name": name, "done": False}
    data_store.append(new_item)
    return jsonify(data_store)


@app.route("/postjson", methods=["POST"])
def post_json_data():
    """Accept JSON or form-encoded data, create a new item, return updated store."""
    if request.is_json:
        payload = request.get_json(silent=True)
    else:
        payload = request.form

    if payload is None:
        return Response("Invalid request: no payload.", status=400, mimetype="text/plain")

    name = payload.get("name", "")
    done_str = payload.get("done", "False")

    try:
        done = done_str.lower() in ("true", "1", "true", "yes")
    except (TypeError, ValueError):
        done = False

    new_id = data_store[-1]["id"] + 1 if data_store else 1
    new_item = {"id": new_id, "name": name, "done": done}
    data_store.append(new_item)
    return jsonify(data_store)


@app.route("/postjson", methods=["GET"])
def get_json_data():
    """Return the current data store as JSON."""
    return jsonify(data_store)


if __name__ == "__main__":
    app.run(host="0.0.0.0", debug=False)

