import serial
import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400

def send_command(bluetooth, command):
    """Sends a command to the Bluetooth device with error handling."""
    try:
        bluetooth.write(f"X{command}\n".encode("utf-8"))
        bluetooth.flush()
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command '{command}': {e}")

def main():
    """Main function to handle user input and send commands."""
    bluetooth = None
    try:
        bluetooth = serial.Serial(BLUETOOTH_DEVICE, BLUETOOTH_BAUDRATE, timeout=1)
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if command.lower() == "exit":
                break

            send_command(bluetooth, command)

    except serial.SerialException as e:
        print(f"Error connecting to Bluetooth device: {e}", file=sys.stderr)
        sys.exit(1)
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if bluetooth is not None and bluetooth.is_open:
            bluetooth.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

